(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("pliny-natural-history-9-b", [{"sp": "HDR", "t": "Naturalis Historia (Libri XXVI–XXVIII)"}, {"sp": "HDR", "t": "Liber XXVI", "st": "26"}, {"sp": "N", "t": "Sensit facies hominum et novos omnique aevo priore incognitos non Italiae modo, verum etiam universae prope Europae morbos, tune quoque non tota Italia nec per Illyricum Galliasve aut Hispanias magno opere vagatos aut alibi quam Romae circaque, sine dolore quidem illos ac sine pernicie vitae, sed tanta foeditate, ut quaecumque mors praeferenda esset.", "st": "26.1"}, {"sp": "N", "t": "Gravissimum ex iis lichenas appellavere Graeco nomine, Latine, quoniam a mento fere oriebatur, ioculari primum lascivia, ut est procax multorum natura in alienis miseriis, mox et usurpato vocabulo mentagram, occupantem multis et l⟨a⟩tis totos utique voltus, oculis tantum inmunibus, descendentem vero et in colla pectusque ac manus foedo cutis furfure.", "st": "26.2"}, {"sp": "N", "t": "Non fuerat haec lues apud maiores patresque nostros et primum Ti. Claudi Caesaris principatu medio inrepsit in Italiam quodam Perusino equite Romano, quaestorio scriba, cum in Asia adparuisset, inde contagionem eius inportante. nec sensere id malum feminae aut servitia plebesque humilis aut media, sed proceres veloci transitu osculi maxime, foediore multorum, qui perpeti medicinam toleraverant, cicatrice quam morbo. causticis namque curabatur, ni usque in ossa corpus exustum esset, rebellante taedio. adveneruntque ex Aegypto, genetrice talium vitiorum, medici hanc solam operam adferentes magna sua praeda, siquidem certum est Manilium Cornutum e praetoriis legatum Aquitanicae provinciae HS CC elocasse in eo morbo curandum sese. accidit ⟨quo⟩que saepius, ut nova contra genera morborum gregatim sentirentur. quo mirabilius quid potest reperiri? aliqua gigni repente vitia terrarum in parte certa membrisque hominum certis vel aetatibus aut etiam fortunis, tanquam malo eligente, haec in pueris grassari, illa in adultis, haec proceres sentire, illa pauperes!", "st": "26.3"}, {"sp": "N", "t": "L. Paullo Q. Marcio censoribus primum in Italia carbunculum ⟨e⟩venisse annalibus notatum est, peculiare Narbonensis provinciae malum, quo duo consulates obiere condentibus haec nobis eodem anno, lulius Rufus atque L⟨ae⟩canius Bassus, ille medicorum inscitia sectus, hic vero pollici laevae manus evulso acu ab semet ipso tam parvo, ut vix cerni posset. nascitur in occultissimis corporum partibus et plerumque sub lingua duritia rubens vari modo, sed capite nigricans, alias livida, in corpus intendens neque intumescens, sine dolore, sine pruritu, sine alio quam somni indicio, quo gravatos in triduo aufert, aliquando et horrorem adferens circaque pusulas parvas, rarius febrem, stomachum faucesque ut invasit, ocissime exanimans.", "st": "26.4"}, {"sp": "N", "t": "Diximus elephantiasim ante Pompei Magni aetatem non accidisse in Italia, et ipsam a facie saepius incipientem, in nare prima veluti lenticula, mox in⟨c⟩rescente per totum corpus, maculosa variis coloribus et inaequali cute, alibi crassa, alibi tenui, dura, alibi ceu scabie aspera, ad postremum vero nigrescente et ad ossa carnes adprimente, intumescentibus digitis in pedibus manibusque. Aegypti peculiare hoc malum et, cum in reges incidisset, populis funebre, quippe in balineis solia temperabantur humano sanguine ad medicinam eam. et hic quidem morbus celeriter in Italia restinctus est, sicut et ille, quem gemursam appellavere prisci inter digitos pedum nascente⟨m⟩, etiam nomine oblitterato.", "st": "26.5"}, {"sp": "N", "t": "Id ipsum mirabile, alios desinere in nobis, alios durare, sicuti colum. Ti. Caesaris principatu inrepsit id malum, nec quisquam id prior imperatore ipso sensit, magna civitatis ambage, cum in edicto eius excusantis valetudinem legeret nomen incognitum. quid hoc esse dicamus aut quas deorura iras? parum enim erant homini certa morborum genera, cum supra trecenta essent, nisi etiam nova timerentur! neque ipsi autem homines pauciora sibi opera sua negotia inportant.", "st": "26.6"}, {"sp": "N", "t": "Haec apud priscos erant quae memoramus remedia, medicina⟨m⟩ ipsa quodammodo rerum natura faciente, et diu fuere.", "st": "26.6"}, {"sp": "N", "t": "Hippocratis certe, qui primus medendi praecepta clarissime condidit, referta herbarum mentione invenimus volumina, nec minus Diocli Carysti, qui secundus aetate famaque extitit, item Praxagorae et Chrysippi ac deinde Erasistrati C⟨ei⟩, Herophilo quidem, quamquam subtilioris sectae conditori, ante omnis celebratam rationem, ⟨i⟩am paulatim, usu efficacissimo rerum omnium magistro, peculiariter utique medicinae, ad verba garrulitatemque descendentem. sedere namque in scholis auditioni operatos gratius erat quam ire per solitudines et quaerere herbas alias aliis diebus anni.", "st": "26.6"}, {"sp": "N", "t": "Durabat tamen antiquitas firm magnasque confessae rei vindicabat reliquias, donec Asclepiades aetate Magni Pompei orandi magister nec satis in arte ea quaestuosus, ut ad alia quam forum sagacis ingenii, huc se repente convertit atque, ut necesse erat homini qui nec id egisset nec remedia nosset oculis usuque percipienda, torrenti ac meditata cotidie oratione blandiens omnia abdicavit totamque medicinam ad causas revocando coniecturae fecit, quinque res maxume communium auxiliorum professus, abstinentiam cibi, alias vini, fricationem corporis, ambulationem, gestationes, quae cum unusquisque semet ipsum sibi praestare posse intellegeret, faventibus cunctis, ut essent vera quae facillima erant, universum prope humanum genus circumegit in se non alio modo quam si caelo demissus advenisset.", "st": "26.7"}, {"sp": "N", "t": "Trahebat praeterea mentes artificio ⟨in⟩ani, alias vinum promittendo aegris dandoque tempestive, iam frigidam aquam et, quoniam causas morborum scrutari prius Herophilus instituerat, vini rationem inlustraverat Cleophantus apud priscos, ipse cognominari se frigida danda praeferens, ut auctor est M. Varro. alia quoque blandimenta excogitabat, iam suspendendo lectulos, quorum iactatu aut morbos extenuaret aut somnos adliceret, iam balneas avidissima homninum cupidine instituendo et alia multa dictu grata atque iucunda, magna auctoritate nec minore fama, cum occurrisset ignoto funeri, relato homine ab rogo atque servato, ne quis levibus momentis tantam conversionem factam existimet. id solum possumus indignari, unum hominem e levissima gente, sine opibus ullis orsum, vectigalis sui causa repente leges salutis humano generi dedisse, quas tamen postea abrogavere multi. Asclepiaden adiuvere multa in antiquorum cura nimis anxia et rudia, ut obruendi aegros veste sudoresque omni modo ciendi, nunc corpora ad ignes torrendi solesve adsiduo quaerendi in urbe nimbosa, immo vero tota Italia im⟨b⟩r⟨ici⟩trice, tum primum pensili balinearum usu ad infinitum blandiente. praeterea in quibusdam morbis mnedendi cruciatus detraxit, ut in anginis, quas curabant in fauces organo demisso. damnavit merito et vomitiones tune supra modum frequentes. arguit et medicamentorum potus stomacho inimicos, quod est magna ex parte verum. itaque nos in primis quae sunt stomacho utilia signamus.", "st": "26.8"}, {"sp": "N", "t": "Super omnia adiuvere eum magicae vanitates in tantum evectae, ut abrogare herbis fidem cunctis possent: Aethiopide herba amnes ac stagna siccari; on⟨othu⟩⟨ri⟩dis tactu clausa omnia aperiri; Achaemenide coniecta in aciem hostium trepidare agmina ac terga verti; latacen dari solitam a Persarum rege legatis, ut, quocumque venissent, omnium rerum copia abundarent, ac multa similia. ubinam istae fuere, cum Cimbri Teutonique terribili Marte ulularent aut cum Lucullus tot reges Magorum paucis legionibus sterneret? curve Romani duces primam semper in bellis commerciorum habuere curam? cur Caesaris miles ad Pharsaliam famem sensit, si abundantia omnis contingere unius herbae felicitate poterat? non satius fuit Aemilianum Scipionem Carthaginis portas herba patefacere quam machinis claustra per tot annos quatere? siccentur hodie Meroide Pomptinae paludes tantumque agri suburbanae reddatur Italiae! nam quae apud eundem Democritum invenitur compositio medicamenti, quo pulchri bonique et fortunati gignantur liberi, cui umquam Persarum regi tales dedit? mirum esset profecto hucusque provectam credulitatem antiquorum saluberrimis ortam initiis, si in ulla re modum humana ingenia novissent atque non hanc ipsam medicinam ab Asclepiade repertam probaturi suo loco essemus evectam ultra Magos etiam. haec est omni in re animorum condicio, ut a necessariis orsa primo cuncta pervenerint ad nimium. igitur demonstratarum priore libro herbarum reliquos effectus reddemus, adicientes ut quasque ratio dictabit.", "st": "26.9"}, {"sp": "N", "t": "Sed in lichenis remediis atque tam foedo malo plura undique acerva⟨b⟩imus, quamquam non paucis iam demonstratis. medetur ergo plantago trita, quinquefolium, radix albuci ex aceto, ficulni caules ex aceto decocti, hibisci radix cum glutino et aceto acri decocta ad quartas. defricant etiam pumice, ut rumicis radix trita ex aceto inlinatur. et flos visci cum calce subactus laudatur et tithymalli cum resina decoctum. lichen vero herba omnibus his praefertur, inde nomine invento. nascitur in saxis, folio uno ad radicem lato, caule uno parvo, longis foliis dependentibus. haec delet et stigmata. teritur cum melle. est aliud genus lichenis, petris totum adhaerens ut muscus, qui et ipse inlinitur. hic et sanguinem sistit volneribus instillatus et collectiones inlitus. morbum quoque regium cum melle sanat ore inlito et lingua. qui ita curentur, aqua salsa lavari iubentur, ungui oleo amygdalino, hortensiis abstinere. ad lichenas et thapsiae radice utuntur trita cum melle.", "st": "26.10"}, {"sp": "N", "t": "Anginae argemonia medetur sumpta ex vino, hysopumn cum fico decoctum et gargarizatum, peucedanum cum coagulo vituli marini aequis partibus, proserpinaca cum muria ex menis et oleo trita vel sub lingua habita, item sucus de quinquefolio potus cyathis III. hic et omnibus faucium vitiis medetur gargarizatus, verbascum privatim tonsillis in aqua potum,", "st": "26.11"}, {"sp": "N", "t": "strumis plantago, chelidonia cum melle et axungia, quinquefolium, radix persollatae, item cum axungia operitur folio suo inposita, item Artemisia, radix mandragorae ex aqua. sideritis latifolia clavo sinistra manu circumfossa adalligatur, custodienda sanatis ne rursus sata ⟨ta⟩edi⟨um⟩ herbariorum seelere, ut in quibusdam diximus, rebellet, quod et in ⟨i⟩is, quos Artemisia sanaverit, praedici reperio, item in ⟨i⟩is, quos plantago. damasoni⟨u⟩m, quae et alcima vocatur, sub solstitio collecta inponitur ex aqua caelesti, folium tritum vel radix tusa cum axungia ita, ut inposita folio suo operiatur. sic et ad omnes cervicis dolores tumoresque quacumque in parte. —", "st": "26.12"}, {"sp": "N", "t": "Bellis in pratis nascitur, flore albo, aliquatenus rubente. hanc cum Artemisia inlitam efficaciorem esse produnt.—", "st": "26.13"}, {"sp": "N", "t": "Condurdum quoque herba solstitialis, flore rubro, suspensa in collo conprimere dicitur strumas, item verbenaca cum plantagine.—Digitorum vitiis omnibus et privatim pterygiis quinquefolium medetur.", "st": "26.14"}, {"sp": "N", "t": "In pectoris vitiis vel gravissimum est tussis. huic medetur panacis radix in vino dulci, sucus hyoscyami etiam sanguinem excreantibus, nidor quoque accensi tussientibus, item scordotis mixto nasturcio et resina cum melle tunsa arida—facit et per se faciles excreationes—, item centaurium maius vel sanguinem reicientibus, cui vitio et plantaginis sucus medetur et Vettonica obolis III in aqua; contra purulentas contraque cruentas exscreationes persollatae radix drachmae pondere cum pineis nucleis XI, peucedani sucus. pectoris doloribus acorum subvenit, ide⟨m⟩ antidotis miscetur; tussi. daucum, item Scythica herba, eadem omnibus pectoris vitiis; tussi et purulenta excreantibus obolis III in passi totidem verbascum, cuius est flos aureus.", "st": "26.15"}, {"sp": "N", "t": "huic tanta vis, ut iumentis etiam non tussientibus modo, sed ilia quoque traheatibus auxilietur potu, quod et de Gentiana reperio. radix eacaliae conmanducata et in vino madefacta non tussi tantum, sed et faucibus prodest. hysopi v rami cum II rutae et ficis III decocti thoracem purgant, tussim sedant.", "st": "26.15"}, {"sp": "N", "t": "Bechion tussilago dicitur. duo eius genera. silvestris ubi nascitur, subesse aquas credunt, et hoc habent signum aquileges. folia sunt maiuscula quam hederae v aut VII, subalbida a terra, superne pallida, sine caule, sine flore, sine semine, radice tenui. quidam eandem esse arcion et alio nomine chamaeleucen putant. huius aridae cum radice fumus per harundinem haustus et devoratus veterem sanare dicitur tussim, sed in singulos haustus passum gustandum est.", "st": "26.16"}, {"sp": "N", "t": "altera a quibusdam salvia appellatur, similis verbasco. conteritur et colata calfit atque ita ad tussim laterisque dolores bibitur, contra scorpiones eadem et dracones marinos efficax. contra serpentes quoque ex oleo perungui ea prodest.—Hysopi fasciculus cum quadrante mellis decoquitur ad tussim, lateris, pectoris dolores, verbascum cum ruta ex aqua, Vettonicae farina bibitur ex aqua calida.", "st": "26.17"}, {"sp": "N", "t": "Stomachum conroborat scordotis suco, centaurium, Gentiana ex aqua pota, plantago aut per se in cibo sumpta aut cum lente alicaeve sorbitione. Vettonica alias gravis stomacho, vitia tamen sanat pota vel foliis conmanducata, item aristolochia pota, agaricum manducatum siccum, ut ex intervallo merum sorbeatur, nymphaea Heraclia inlita, peucedani sucus. psyllion ardoribus inponitur, vel cotyledon trita cum polenta vel aizoum.", "st": "26.18"}, {"sp": "N", "t": "Molon scapo est striato, foliis mollibus, parvis radice IIII digitorum, in qua extrema alii caput est. vocatur a quibusdam syron. ex vino stomacho … d⟨y⟩spnoeae medetur centaurium maius ecligmate, plantago suco vel cibo, Vettonicae tusae pondo libra, mellis Attici semuncia ex aqua calida cotidie bibentibus, aristolochia vel agaricum obolis ternis ex aqua calida aut lacte asini potum. cissanthemos ad orthopnoeas bibitur, item hysopum et asthmaticis, peucedani sucus in iocineris doloribus et pectoris laterisque, si febres non sint. sanguinem quoque expuentibus subvenit agaricum victoriati pondere tritum et in mulsi v cyathis datum. idem et amomon facit. iocineri privatim Teucria bibitur recens drachmis IIII in poscae hemina, Vettonicae drachma I in aquae calidae cyathis III ad cordis vitia in frigidae cyathis II. quinquefolii sucus iocineris et pulmonis vitiis sanguinemque reicientibus et cuicumque vitio sanguinis intus occurrit. iocineri anagallides mire prosunt. capnon herbam qui edere, bilem per urinam reddunt. acoron iocineri medetur, thoraci et praecordiis ⟨d⟩aucum.", "st": "26.19"}, {"sp": "N", "t": "Ephedra, ab aliis a⟨n⟩abasis vocata, nascitur ventoso fere tractu scandens arborem et ex ramis propendens, folio nullo cirris numerosa, qui sint iunci geniculati, radice pallida. datur ex vino nigro austere trita ad tussim, suspiria, tormina et sorbitione facta, in quam vinum addi convenit. item Gentiana madefacta pridie contrita denarii pondere in vini cyathis III.", "st": "26.20"}, {"sp": "N", "t": "Gaeum radiculas tenues habet nigras, bene olentes. medetur non modo pectoris doloribus aut lateris, sed et cruditates discutit iucundo sapore. verbenaca vero omnibus visceribus medetur, lateribus, pulmonibus, iocineribus, thoraci; peculiariter autem pulmonibus et quos ab ⟨i⟩is phthisis temptet radix herbae consiliginis, quam nuper inventam diximus. suum quidem et pecoris omnis remedium praesens est pulmonum vitio vel traiecta tantum in auricula. bibi debet ex aqua haberique in ore adsidue sub lingua. superficies eius herbae an sit in aliquo usu, adhuc incertum est. renibus prodest plantaginis cibus, Vettonicae potus, agaricum potum ut in tussi.", "st": "26.21"}, {"sp": "N", "t": "Tripolion in maritimis nascitur saxis, ubi adludit unda, neque in mari neque in sicco, folio ⟨i⟩satis crassiore, caule palm⟨um⟩ alto, in mucrone diviso, radice alba, odorata, crassa, calidi gustus. datur hepaticis in farre cocta. haec herba eadem videtur quibusdam quae polium, de qua suo loco diximus.", "st": "26.22"}, {"sp": "N", "t": "Gromphaena, alternis viridibus roseisque per caulem foliis, in posca sanguinem reicientibus medetur.", "st": "26.23"}, {"sp": "N", "t": "iocineri autem herba malundrum, nascens in segete ac pratis, flore albo, odorata. eius cauliculus conteritur ex vino vetere.", "st": "26.24"}, {"sp": "N", "t": "item herba calcetum e vin⟨a⟩ceis contrita inponitur. faciles praestat vomitiones radix Vettonicae, hellebori modo IIII drachmis in passo aut mulso, hysopum tritum cum melle, utilius praesumpto nasturcio aut irione, molemonium denarii pondere. et sill⟨y⟩b⟨i⟩ lacteus sucus, qui densatur in cummim, sumitur cum melle supra dicto pondere praecipueque bilem trahit. rursus sistunt vomitionem cuminum silvestre, Vettonicae farina; sumuntur ex aqua. abstergent fastidia cruditatesque digerunt daucum, Vettonicae farina ex aqua mulsa, plantago decocta caulium modo.—Singultus hemionium sedat, item aristolochia, suspiria cl⟨y⟩menus.—Pleuriticis et peripneumonicis centaurium mains, item hysopum bibitur, pleuriticis peucedani sucus.", "st": "26.25"}, {"sp": "N", "t": "alus autem, quam Galli sic vocant, Veneti cotoneam, medetur lateri, item renibus convolsisque et ruptis. similis est cunilae bubulae, cacuminibus thymo, dulcis et sitim sedans, radicis alibi albae, alibi nigrae.", "st": "26.26"}, {"sp": "N", "t": "eosdem effects in lateris doloribus habet chamaerops myrteis circa caules geminos foliis, capitibus Graeculae rosae, ex vino pota.—⟨I⟩sc⟨h⟩iadicos dolores et spinae levat agaricum potum ut in tussi, item ⟨s⟩toechadis aut Vettonicae farina ex aqua mulsa.", "st": "26.27"}, {"sp": "N", "t": "Plurimum tamen homini negotii alvus exhibet, cuius causa maior pars mortalium vivit. alias enim cibos non transmittit, alias non continet, alias non capit, alias non conficit, eoque mores venere, ut homo maxime cibo pereat. pessimum corporum vas instat ut creditor et saepius die appellat. huius gratia praecipue avaritia expetit, huic luxuria condit, huic navigatur ad Phasim, huic profundi vada exquiruntur; et nemo vilitatem eius aestimat consummationis foeditate. ergo numerosissima est circa hanc medicinae opera.", "st": "26.28"}, {"sp": "N", "t": "Sistit eam scordotis recens drachma cum vino trita vel decocta potu, Polemonia, quae et dysintericis ex vino datur, verbasci radix pota ex aqua II digitorum magnitudine, nymphaeae Heracliae semen cum vino potum, radix superior e xiphio drachmae pondere ex aceto, semen plantaginis in vino tritum vel ipsa ex aceto cocta aut alica ex suco eius sumpta, item cum lenticula cocta vel aridae farina inspersa potioni cum papavere tosto et trito vel sucus infusus aut potus, Vettonica in vino ferro calefacto. eadem coeliacis in vino austero datur; his et Hiberis inponitur uti dictum est. —Tenesmo radix nymphaeae Heracliae e vino bibitur, psyllium in aqua, acori radicis decoctum. aizoi sucus alvum sistit et dysinterias et t⟨a⟩enias rotundas pellit. symphyti radix pota in vino alvum et dysinteriam sistit, item dauci. aizoum foliis contritis ex vino torminibus resistit, alc⟨i⟩mae siccae farina torminibus pota cum vino.", "st": "26.28"}, {"sp": "N", "t": "Astragalus folia habet longa, incisuris multis obliquis, circa radicem caules III aut III, foliorum plenos, florem hyacinthi, radices villosas, inplicatas, rubras, praeduras. nascitur in petrosis, apricis et isdem nivalibus, sicut in Pheneo Arcadiae. vis ei ad spissanda corpora. alvum sistit radix in vino pota, quo fit ut moveat urinam repercusso liquore, sicut pleraque quae alvum sistunt. sanat et dysintericos in vino rubro tusa; difficile autem tunditur. eadem gingivarum suppurationi utilissima est fotu. colligitur exitu autumni, cum folia amisit; siccatur in umbra.", "st": "26.29"}, {"sp": "N", "t": "Et ladano sistitur alvus utroque, quod in segetibus nascitur contuso et cribrato. bibitur ex aqua mulsa, item nobili e vino. ledon appellatur herba, ex qua fit in Cypro barbis caprarum adhaerescens. nobilius in Arabia fit, iam et in Syria atque Africa quod toxicum vocant; nervos enim in arcu circumdatos lanis trahunt adhaerescente roscida lanugine. plura de eo diximus inter unguenta. hoc gravissimum odore est durissimumque tactu. plurimum enim terrae colligit, cum probetur maxime purum, odoratum, molle, viride, resinosum. natura ei molliendi, siccandi, concoquendi, somnum adliciendi. capillum fluentem cohibet nigritiamque custodit, auribus cum hydromelite aut rosaceo infunditur, furfures cutis et manantia ulcera sale addito sanat, tussim veterem cum st⟨y⟩race sumptum, efficacissimum ad ructus.", "st": "26.30"}, {"sp": "N", "t": "Alvum sistit et chondris sive pseudodictamnun. —Hypocisthis, orobethron quibusdam dicta, malo granato inmaturo similis, nascitur, ut diximus, sub cistho, unde nomen. haec arefacta in umbra sistit alvum, ex vino nigro austero utraque. duo enim genera eius, candida et rufa. usus in suco: spissat, siccat. et rufa magis stomachi rheumatismos emendat pota III obolis, sanguinis excreationes cum amylo, dysinterias pota et infusa, item verbenaca ex aqua data aut carentibus. febri ex vino Am⟨m⟩ineo, cochlearibus v additis in cyvthos III vini.", "st": "26.31"}, {"sp": "N", "t": "Laver quoque, nascens in rivis, condita et cocta torminibus medetur,", "st": "26.32"}, {"sp": "N", "t": "potamogiton vero ex vino dysintericis etiam et coeliacis, similis betae foliis, minor tantum hirsutiorque, paulum semper eminens extra aquam. usus in foliis: refrigerant, spissant, peculiariter cruribus vitiosis utilia et contra ulcerum nomas cum melle vel aceto. Castor hanc aliter noverat, tenui folio velut equinis saetis, thyrso longo et levi, in aquosis nascentem. radice sanabat strumas et duritias. potamogiton adversatur crocodilis; itaque secum habent eam qui venantur. alvum sistit et Achillea. eosdem effectus praestat et statice, VII caulibus veluti rosae capita sustinens.", "st": "26.33"}, {"sp": "N", "t": "Ceratia uno folio, radice nodosa et magna, in cibo coeliacis et dysintericis medetur. leontopodion alii leuceoron, alii doripetron, alii thorybethron vocant, cuius radix alvum sistit purgatque bilem, in aquam mulsam addito pondere denariorum II. nascitur in campestri et gracili solo. semen eius potum lymphatica somnia facere dicitur. lagopus sistit alvom e vino pota aut in febri ex aqua. eadem inguini adalligatur in tumore. nascitur in segetibus. multi super omnia laudant ad deploratos dysintericos quinquefolium decoctis in lacte radicibus potis et aristolochiam victoriati pondere in cyathis vini III. quae ex supra dictis calida sumentur, haec candente ferro temperari aptius erit.", "st": "26.34"}, {"sp": "N", "t": "E diverso purgat alvum sucus centaurii minoris drachma in hemina aquae cum exiguo salis et aceti bilemque detrahit, maiore tormina discutiuntur. Vettonica alvum solvit drachmis IIII in hydromelitis cyathis VIIII, item Euphorbeum vel agaricum drachmis II cum sale modico potum ex aqua aut in mulso obolis III. solvit et cyclaminos ex aqua pota aut balanis subditis, item chamaecissi balanus. hysopi manipulus decoctus ad tertias cum sale et pituitas trahit vel tritus cum oxymelite et sale pellitque ventris aninmalia. pituitam et bilem detrahit peucedani radix.", "st": "26.34"}, {"sp": "N", "t": "Alvum purgant anagallides ex aqua mulsa, item epithymum, qui est flos e thymo satureiae simili. differentia, quod hic herbaceus est, alterius thymi albus; quidam hippopheon vocant. stomacho minus utilis vomitiones movet, sed tormina et inflationes discutit. sumitur et ecligmate ad pectoris vitia cum melle et aliquando iride. alvum solvit a IIII drachmis ad VI cum melle et exiguo salis atque aceti. quidam aliter epithymum tradunt sine radice nasci, tenu⟨e⟩, sirailitudine pallioli, rubens, siccari in umbra, bibi ex aqua acetabuli parte dimidia, detrahere pituitam bilemque alvo leniter soluta.", "st": "26.35"}, {"sp": "N", "t": "et nymphaea in vino austero solvit et pycnocomon, erucae foliis crassioribus et acrioribus, radice rotunda, lutei coloris, terram olente, caule quadriangulo, modico, tenui, flore ocimi. invenitur in saxosis. radix eius in aqua mulsa X II pondere et alvum et bilem et pituitam exinanit; semen somnia tumultuosa facit una drachma in vino potum. et capnos trun⟨c⟩a detrahit bilem.", "st": "26.36"}, {"sp": "N", "t": "Polypodi, quam nostri f⟨e⟩liculam vocant, similis felici, radix in usu, pilosa, coloris intus herbacei, crassitudine digiti minimi, acetabulis cavernosa ceu polyporum cirri, subdulcis, in petris nascens aut sub arboribus vetustis. exprimitur sucus aqua madefactae, et ipsa minute concisa inspergitur oleri vel betae vel malvae vel salsamento aut cum pulticula coquitur ad alvum vel in febri le⟨n⟩iter solvendam. detrahit bilem et pituitam, stomachum offendit. aridae farina indita naribus polypum consumit. florem et semen non fert.", "st": "26.37"}, {"sp": "N", "t": "Scamonium quoque dissolutione stomachi bilem detrahit, alvum solvit, praeterquam si adiciantur aloes drachmae II obolis eius II. est autem sucus herbae ab radice ramosae, pinguibus foliis, triangulis, albis, radice crassa, madida, nausiosa. nascitur pingui et albo solo. radix circa canis ortum excavatur, ut in ipsam confluat sucus, qui sole siccatus digeritur in pastillos. siccatur et ipsa vel cortex. laudatur natione Colophonium, Mysium, Prienense, specie autem nitidum et quam simillimum taurino glutini, fungosum tenuissimis fistulis, cito liquescens, virus redolens, cumminosum, linguae tactu lactescens, quam levissimum, cum diluatur, albescens. hoc evenit et adulterine, quod fit ervi farina et tithymalli marini suco fere in Iudaea. quod etiam strangulat sumptum. deprehenditur gustu, tithymallus enim linguam excalefacit. usus bimo; nec ante nec postea utile. dedere et per se ex aqua vel mulsa et sale quaternis obolis, sed utilissime cum aloe ita, ut incipiente purgatione mulsum bibatur. fit et decoctum radicis in aceto ad crassitudinem mellis, quo leprae inlinuntur et caput inunguitur in dolore cum oleo.", "st": "26.38"}, {"sp": "N", "t": "Tithymallum nostri herbam lactariam vocant, alii lactucam caprinam, narrantque lacte eius inscripto corpore, cum inaruerit, si cinis inspergatur, apparere litteras, et ita quidam adulteras adloqui maluere quam codicillis. genera eius multa. primus cognominatur characias, qui et masculus existimatur, ramis digitali crassitudine, rubris, sucosis, v aut VI, cubitali longitudine, a radice foliis paene oleae, in cacuminibus coma iunci. nascitur in asperis maritimis, legitur semen autumno cum coma, siccatum sole tunditur et reponitur. sucus vero incipiente pomorum lanugine defractis ramis excipitur farina ervi aut fici⟨s⟩, ut cum ⟨i⟩is arescat. quinas autem guttas singulis excipi satis est, traduntque totiens purgari hydropicos fico sumpta, quot guttas e⟨a⟩ lactis exceperit. sucus cum colligitur, ne attingat oculos, cavendum est. fit et e foliis tunsis priore minus efficax. fit et decoctum e ramis. est et semen in usu cum melle decoctum ad catapotia solvendae alvi gratia. semen et dentium cavis cera includitur. colluuntur et radicis decocto e vino aut oleo. inlinunt et lichenas suco bibuntque eum, ut purget vomitione et alvo soluta, alias stomacho inutilem. trahit pituitam sale addito in potu, bilem aphronitro, si per alvum purgari libeat, in posca, si vomitione, in passo aut aqua mulsa. media potio III obolis datur. ficos a cibo sumpsisse melius est. fauces urit leniter, est enim tam ferventis naturae, ut per se extra corpori inpositu⟨s⟩ pusulas ignium modo faciat et pro caustico in usu sit. —", "st": "26.39"}, {"sp": "N", "t": "Alterum genus tithymalli myrtiten vocant, alii car⟨y⟩iten, foliis myrti acutis et pungentibus, sed m⟨a⟩ioribus, et ipsum in asperis nascens. colliguntur comae eius hordeo turgescente siccataeque in umbra diebus VIIII in sole inarescunt. fructus non pariter maturescit, sed pars anno sequente, et nux vocatur. inde cognomen Graeci dedere. demetitur cum messium maturitate lavaturque, deinde siccatur et datur cum papaveris nigri II partibus ita, ut sit &gt;totum acetabuli modus. minus hic vomito⟨r⟩ius quam superior, ceteri item. aliqui sic et folium eius dedere, nucem vero ipsam in mulso aut passo vel sesima. trahit pituitam et bilem per alvum, oris ulcera sanat. ad nomas oris folium cum melle estur.—", "st": "26.40"}, {"sp": "N", "t": "Tertium genus tithymalli paralium vocatur sive tithymallis folio rotundo, caule palmum alto, ramis rubentibus, semine albo, quod colligitur incipiente uva et siccatum teritur sumiturque acetabuli mensura ad purgationes.—", "st": "26.41"}, {"sp": "N", "t": "Quartum genus helioscopion appellant, foliis porcillacae, ramulis stantibus a radice IIII aut v rubentibus, semipedali altitudine, suci plenis. hoc circa oppida nascitur, semine albo, columbis gratissimo. nomen accepit, quoniam capita cum sole circumagit. trahit bilem per inferna in oxymelite dimidio acetabulo. ceteri usus qui characiae.—", "st": "26.42"}, {"sp": "N", "t": "Quintum cyparittian vocant propter foliorum similitudinem, caule gemino aut triplici, nascente⟨m⟩ in campestribus. eadem vis quae helioscopio aut characiae.—", "st": "26.43"}, {"sp": "N", "t": "Sextum platyphyllon vocant, alii corymbiten, alii amygdaliten a similitudine. nec ullius latiora sunt folia. pisces necat. alvum solvit radice vel foliis vel suco in mulso aut aqua mulsa drachmis IIII. detrahit privatim aquas.—", "st": "26.44"}, {"sp": "N", "t": "Septimum dendroides cognominant, alii cobion, alii leptophyllon, in petris nascens, comosissimum ex omnibus, maximis cauliculis rubentibus et semine copiosissimum, eiusdem effectus cuius characian.", "st": "26.45"}, {"sp": "N", "t": "Apios ischas sive raphanos agria, iuncos II aut III spargit in terra rubentes, foliis rutae. radix cepae, sed amplior, quare quidam raphanum silvestrem vocant. intus habet mammam candidam, extra cortices nigros. nascitur in montosis asperis, aliquando et herbosis. effoditur vere tusaque in fictili mergitur, deiectoque quod supernatat reliquus sucus purgat utraque parte sesquiobolo in aqua mulsa. sic et hydropicis datur acetabuli mensura. inspergitur et aridae radicis farina potioni. aiunt superiorem partem eius vomitione biles extrahere, inferiorem per alvum in aqua.", "st": "26.46"}, {"sp": "N", "t": "Tormina discutit quodcumque panaces, Vettonica praeterquam a cruditate, peucedani sucus et inflationes, ructus gignens, acori radix, daucum vel si lactucae modo sumatur. ladanum Cyprium potum interaneorum vitiis occurrit, Gentianae farina ex aqua tepida fabae magnitudine, plantago mane sumpta II lingulis et tertia papaveris in vini cyathis IIII non veteris. datur et in somnum euntibus addito nitro vel polenta, si multo post cibum detur. colo infunditur hemina suci vel in febri.", "st": "26.47"}, {"sp": "N", "t": "Agaricum potum obolis III in vini veteris cyatho uno lieni medetur, e panace omnium generum radix in mulso, sed Teucria praecipue pota arida et decocta, quantum manus capiat, in aceti heminis III ad heminam. inlinitur eadem ex aceto aut, si tolerari non possit, ex fico vel aqua. Polemonia bibitur ex vino, Vettonica drachma in oxymelitis cyathis III, aristolochia ut contra serpentes. argemonia VII diebus in cibo sumpta lienem consumere dicitur, agaricum in aceto mulso obolis II. nymphaeae Heracliae radix in vino pota et ipsa consumit. cissanthemus drachma bis die sumpta in vini albi cyathis II per dies XL lienem dicitur paulatim emittere per urinam. prodest et hysopum cum fico decoctum, lonchitidisz radix decocta prius quam semen demittat, peucedani quoque radix et lieni et renibus. lien s⟨uco⟩ acori poto consumitur, praecordiis et ilibus utilissimae radices; … clymeni semen potum diebus xxx pondere denarii in vino albo, Vettonicae farina ex melle et aceto scillite pota, radix lonchitidis in aqua. Teucrium inlinitur, item scordium cum cera, agaricum cum farina e feno Graeco.", "st": "26.48"}, {"sp": "N", "t": "Vesicae malis contraque calculos, gravissimis cruciatibus, ut diximus, auxilio est Polemonia ex vino pota, item agaricum, plantago foliis vel radice potis ex passo, Vettonica ut in iocinere diximus, item rami⟨c⟩i pota atque inlita, eadem ad strangurias efficacissima. quidam ad calculos Vettonicam et verbenacam et mil⟨i⟩folium aequis portionibus ex aqua pro singulari remedio bibere suadent. strangurias discuti et dictamno certum est, item quinquefolio decocto ad tertias in vino. hoc et enterocelicis dari atque inlini utilissimum est. xiphi quoque radix superior urinam ciet, infantibus enterocelicis datur ex aqua et inlinitur. vesicae vitiis peucedani sucus, infantium rami⟨c⟩i et umbilicis eminentibus psyllion inlinitur. urinam cient anagallides, acori radicis decoctum vel ipsa trita potaque et omnia vesicae vitia de⟨pellit,⟩ calculos et herba et radix cotyledonis itemque genitalium inflammationem omnem pari pondere et caulis et seminis et murrae. ebulum teneris cum foliis tritum ex vino potum calculos pellit, inpositum testes sanat. erigeron quoque cum farina turis et vino dulci testium inflammationes sanat. symphyti radix inlita enterocelas cohibet, genitalium nomas hypocisthis alba. Artemisia quoque datur contra calculos ex vino dulci et ad stranguriam, dolores vesicae sedat ex vino radix nymphaeae Heracliae.", "st": "26.49"}, {"sp": "N", "t": "Eadem vis crethmo ab Hippocrate admodum laudata⟨e⟩. est autem inter eas quae eduntur silvestrium herbarum; hanc certe apud Callimachum adponit rustica illa Hecale. species quae elatae hortensiae. caulis unus palmum altus; semen fervens, odoratum ceu libanotidis, rotundum; siccatum rumpitur. habet intus nucleum candidum, quem aliqui cac⟨h⟩rym vocant. folia pinguia albicant veluti olivae, crassiora et salsa gustu; radices digiti crassitudine III aut IIII. nascitur in maritimis petrosis. estur crud⟨a⟩ coct⟨a⟩ve cum olere, odorati saporis et iucundi. servatur etiam in muria. praecipue ⟨ei⟩ usus ad strangurias folio vel caule vel radice ex vino. colorem quoque corporis gratiorem facit, verum largior inflationes. alvum solvit decocto, urinam et a renibus umorem trahit, sicut alcimae siccae farina, e vino pota stranguriae efficacius addito dauco, lieni quoque utilis. adversus serpentes bibitur. iumentis quoque in pituita aut stranguria hordeo inspersa succurrit.", "st": "26.50"}, {"sp": "N", "t": "Anthyllion est lenti simillima, quae in vino pota vesicas vitiis liberat, sanguinem sistit. altera anthyllis, chamaepi⟨t⟩y⟨i⟩ similis, flore purpureo, odore gravi, radice intubi, vel magis medetur…", "st": "26.51"}, {"sp": "N", "t": "Cepaea, similis porcilacae, nigriore radice, sed inutili, nascens in litoribus harenosis, gustu amara, in vino cum asparagi radice vesicae plurimum prodest.", "st": "26.52"}, {"sp": "N", "t": "eadem praestat hypericon—alii chamaepityn, alii corissum appellant—, oleraceo frutice, tenui, cubitali, rubente, folio rutae, odore acri, semine in siliqua nigro, maturescente cum hordeo. natura semini spissandi. alvum sistit, urinam ciet, vesicae cum vino bibitur.", "st": "26.53"}, {"sp": "N", "t": "est aliud hypericon, quod aliqui caro⟨n⟩ appellant, folio tamaricis —et sub ea nascitur—, sed pinguioribus foliis et minu⟨ti⟩s, rubentibus, odoratum, palmo altius, suave, leniter acutum. vis semini excalfactoria, et ldeo inflammationem facit, sed stomacho non inutile, praecipuum ad stranguriam, si exulcerata non sit vesica. medetur et pleuriticis ex vino potum,", "st": "26.54"}, {"sp": "N", "t": "vesicae autem callithrix trita simul ⟨cum⟩ cumino et data ex vino albo, verbenacaque cum foliis decocta ad tertias vel radix eius e mulso calido calculos eicit; item perpressa, quae Arreti et in Illyrico nascitur, in aqua decocta ex III heminis ad unam pota, trifolium ex vino sumptum et chrysanthemum primum. anthemis quoque calculos eicit, parvis a radice foliis quinis, caulibus longis II, fore roseo, radices tritae per se… cei, laver crudum.", "st": "26.55"}, {"sp": "N", "t": "silaus nascitur glariosis et perennibus rivis, cubitalis apii similitudine. coquitur ut olus acidum, magna utilitate vesicae. quae si scabiem sentiat, panacis radice sanatur, aliter inutilis vesicis.—Calculos pellit malum erraticum radicis libra in congio decocta ad dimidias—inde heminae sumuntur per triduum, relicum ex vino —et urtica marina et daucum et plantaginis semen ex vino", "st": "26.56"}, {"sp": "N", "t": "et herba Fulviana trita ex vino. et haec nomen inventoris habet, nota tractantibus.", "st": "26.57"}, {"sp": "N", "t": "urinas ciet scordion, testium tumores sedat hyoscyamum, genitalibus medetur pencedani sucus, ex melle semen, stranguriae agaricum obolis III in vini veteris cyatho uno, trifolii radix drachmis II in vino, dauci una drachma vel seminis.", "st": "26.58"}, {"sp": "N", "t": "Ischiadici semine et foliis erythrodani tritis sanantur, panace poto et infricato, Polemonia, aristolochiae decocto folii. agarico quidem et nervus, qui platys appellatur, et umerorum dolor sanatur obolis III in vini veteris cyatho uno poto. quinquefolium⟨i⟩schiadicis et bibitur et inponitur, item scamoni⟨a⟩ decocta et cum hordei farina. semen hyperici utriusque bibitur ex vino.", "st": "26.58"}, {"sp": "N", "t": "Sedis vitia et adtritus celerrime sanat plantago, condylomata quinquefolium, sed ea in cal⟨l⟩um iam conversa cyclamini radix ex aceto. anagallidum caerulea procidentiam sedis retro agit, e diverso rubens proritat. cotyledon condylomata et haemorrhoidas mire curat, testium tumores acori radix decocta in vino tritaque inlita. intertrigines negat fieri Cato absinthium Ponticum secum habentibus.", "st": "26.58"}, {"sp": "N", "t": "alii adiciunt et puleium, quod ieiunus quis legerit: si post se alliget, inguinis dolores prohibet aut sedat coeptos.", "st": "26.58"}, {"sp": "N", "t": "inguinalis, quam quidam argemonion vocant, passim in vepribus nascens, ut prosit, in manu tantum habenda est.", "st": "26.59"}, {"sp": "N", "t": "Panos sanat panaces ex melle, plantago cum sale, quinquefolium, persoll⟨at⟩ae radix ut in strumis, item damasonium, verbascum cum sua radice tusum, vino aspersum folioque involutum et ita in cinere calefactum, ut inponatur calidum. experti adfirmavere plurimum referre, si virgo inponat nuda ieiuna ieiuno et manu supina tangens dicat: Negat Apollo pestem posse crescere cui nuda virgo restinguat atque ita retrorsa manu ter dicat totiensque despuant ambo. medetur et radix mandragorae ex aqua, radicis scamoniae decoctum cum melle, sideritis cum adipe vetere contusa, marruvium cum axungia vetere, vel Chrysippios cum ficis pinguibus. et haec ab inventore habet nomen.", "st": "26.60"}, {"sp": "N", "t": "Venerem in totum adimit, ut diximus, nymphaea Heraclia, eadem semel pota in XL dies, insomnia quoque veneris a ieiuno pota et in cibo sumpta. inlita quoque radix genitalibus inhibet non solum venerem, sed et affluentiam geniturae; ob id corpus alere vocemque dicitur. adpetentiam veneris facit radix e xiphio superior data potui in vino, item quam cremnon agrion appellant, orm⟨i⟩nos agrios cum polenta contritus.", "st": "26.61"}, {"sp": "N", "t": "Sed inter pauca mirabilis est orchis herba sive serapi⟨a⟩s, foliis porri, caule palmeo, flore purpureo, gemina radice testiculis simili, ita ut maior sive, ut aliqui dicunt, tenuior ex aqua pota excitet libidinem, minor sive mollior e lacte caprino inhibeat. quidam folio scillae esse dicunt leviore ac minore, caule spinoso. radices sanant oris ulcera, thoracis pituitas, alvum sistunt e vino potae.", "st": "26.62"}, {"sp": "N", "t": "Concitatricem vim habet⟨e⟩t satyrion. duo eius genera: longioribus foliis quam oleae, caule IIII digitorum, flore purpureo, radice gemina ad formam hominis testium, alternis annis intumescente ac residente. altera satyrios orchis cognominatur et femina esse credita est. distinguitur internodiis et ramosiore frutice, radice fascini. nascitur fere iuxta mare. haec tumores et vitia partium earum cum polenta inlita sedat vel per se trita. superioris radix in lacte ovis colonicae data nervos intendit, eadem ex aqua remittit.", "st": "26.62"}, {"sp": "N", "t": "Graeci satyrion foliis lilii rubris, minoribus et III non amplius e terra exeuntibus tradunt, caule levi, cubitali, nudo, radice gemina, cuius inferior pars et maior mares gignat, superior ac minor feminas. et aliud genus satyrii erythr⟨ai⟩con appellant, semine viticis maiore, levi, duro, radicis cortice rufo; intus album includi sapore subdulce, fere in montuosis inveniri. venerem, etiam si omnino manu teneatur radix, stimulari, adeo si bibatur in vino austero; arietibus quoque et hircis segnioribus in potu dari, et a Sarmat⟨i⟩a equis ob adsiduum laborem pigrioribus in coitu, quod vitium prosedamum vocant. restinguit vim eius aqua mulsa aut lactuca sumpta. in totum quidem Graeci, cum concitationem hanc volunt significare, satyrion appellant, sic et crataegin cognominantes et thelygonon et arrhe⟨no⟩gonon, quarum semen testi⟨b⟩us simile est. tithymalli quoque ramorum medullam habentes ad venerem proniores fieri dicuntur. prodigiosa sunt quae circa hoc tradit Theophrastus, auctor alioqui gravis, septuageno coitu durasse libidinem contactu herbae, cuius nomen genusque non posuit. —", "st": "26.63"}, {"sp": "N", "t": "Sideritis adalligata varices minuit et sine dolore praestat.", "st": "26.64"}, {"sp": "N", "t": "Podagrae morbus rarior solebat esse non modo patrum avorumque memoria, verum etiam nostra, peregrinus et ipse, nam si Italiae fuisset antiquitus, Latinum nomen invenisset. insanabilis non est credendus, quippe quoniam et in multis sponte desiit et in pluribus cura. medentur radices panacis cum uva passa, sucus hyoscyami cum farina vel semen, scordion ex aceto, Hiberis uti dictum est, verbenaca cum axungia trita, cyclamini radix, cuius decoctum et pernionibus. podagras refrigerat radix e xiphio, semen e psyllio, cicuta cum lithargyro aut axungia, aizoum in primo impetu podagrae rubentis, hoc est calidae. utrilibet vero convenit erigeron cum axungia, plantaginis folia trita addito sale modico, argemonia tusa ex melle. medetur et verbenaca inlita aut si pedes macerentur in aqua, in qua decocta sit,", "st": "26.64"}, {"sp": "N", "t": "et lappago, similis anagallidi, nisi esset ramosior ac pluribus foliis, gravis odoris. quae talis est, mollugo vocatur; similis, sed asperioribus foliis asperugo. superioris et sucus pondere X̶ I in vini II cyathis cotidie sumitur. —", "st": "26.65"}, {"sp": "N", "t": "Praecipue vero liberat eo malo ph⟨y⟩cos thalassion, id est fucus marinus, lactucae similis, qui conchyliis substernitur, non podagrae modo, sed omnibus articulorum morbis inpositus, priusquam arefiat. tria autem genera eius: latum et alterum longius, quadamtenus rubens, tertium crispis foliis, quo in Creta vestes tingunt, omnia eiusdem usus. Nicander ea et adversus serpentes in vino dedit. salutare est et semen eius herbae, quam psyllion appellavimus, madefactum aqua admixtis in heminam seminis resinae Colophoniae coclearibus II, turis uno. laudantur et mandragorae folia cum polenta tunsa.", "st": "26.66"}, {"sp": "N", "t": "Talis vero tumentibus limus aquaticus cum oleo subactus mire prodest, articulis sucus e centaurio minore. idem nervis utilissimus, item centauris. Vettonica nervis discurrentibus per scapulas, umeris, spinae, lumbis pota ut in iocinere, articulis quinquefolium inposit⟨um⟩, mandragorae folia cum polenta vel radix recens tusa cum cucumere silvestri vel decocta in aqua, digitorum in pedibus rimis polypodii radix, articulis sucus hyoscyami cum axungia, amomon suco decocto, item centunculus decocta vel muscus recens ex aqua obligatus, donec inarescat, item lappae boariae radix e vino pota. —Cyclaminos decocta in aqua perniunculos curat omniaque alia frigoris vitia, perniunculos et cotydelon cum axungia, folia ex batrachio, epithymi sucus. clavos pedum extrahit ladanum cum castoreo, verbenaca ex vino.", "st": "26.66"}, {"sp": "N", "t": "Nunc peractis malis, quae membratim sentiuntur, dicemus de ⟨i⟩is, quae totis corporibus grassantur. remedia autem haec communia invenio ⟨apu⟩t a⟨uc⟩to⟨r⟩es potanda: dodecatheum, de qua diximus, deinde panacis omnium generum radices, peculiariter longinquis morbis, et semen interaneorum vitiis, ad omnes vero dolores corporis sucum e scordio, item Vettonicae, quae pota colorem plumbeum corporis privatim emendat, gratiorem reducit.", "st": "26.67"}, {"sp": "N", "t": "Geranion aliqui myrrin, alii myrtidan appellant. similis est cicutae, minutioribus foliis et caule brevior, rotunda, saporis et odoris iucundi. nostri sic eam tradunt, Graeci foliis paulo candidioribus quam malvae, caulibus tenuibus, pilosis ramosam ex intervallis, binum palmorum; e⟨sse⟩ in his folia, inter quae in cacuminibus capitula sint gruum. alterum genus foliis anemones, divisuris longioribus, radice mali modo rotunda, dulci, reficientibus se ab imbecillitate utilissima, et fere talis vera est. bibitur contra phthisis drachma in cyathis vini III bis die, item contra inflationes, et cruda idem praestat. sucus radicis auribus medetur, opisthotonis semen drachmis IIII cum pipere et murra potum. phthisis sanat et plantaginis sucus, si bibatur, et ipsa decocta in cibo; e sale et oleo a somno matutino refrigerat. eadem datur iis, quos atrophos vocant, interpositis diebus, Vettonica vero phthisicis ecligmate cum melle, fabae magnitudine, agaricum potum obolis II in passo, vel daucum cum centaurio maiore in vino. phagedaenis, quod nomen sine modo esurientium est et alias ulcerum, tithymalli medentur cum sesamis sumpti.", "st": "26.68"}, {"sp": "N", "t": "Inter mala universi corporis vigiliae sunt plerisque. harum remedio monstratur panaces, clymenos, aristolochia odore et peruncto capite, aizoum sive sedum, si involutum panno nigro ignorantis pulvino subiciatur, et onotheras sive onear, hilaritatem adferens in vino, amygdalae folio, flore roseo, fruticosa, longa radice et, cum siccata est, vinum olente. haec in potu data feras quoque mitigat. cruditates, quae nausiam faciunt, digeruntur Vettonica pota; eadem a cena concoctionem facit in oxymelitis cyathis III drachmae pondere et crapulam discutit, item agaricum post cibum in aqua calida potum.—Paralysin Vettonica sanare dicitur, item Hiberis ut dictum est. eadem et torpentibus membris prodest, item argemonia omniaque, quae secari periclitentur, discutiendo.", "st": "26.69"}, {"sp": "N", "t": "Comitiales sanantur panacis, quam Heraclion diximus, radice pota cum coagulo vituli marini ita, ut sint panacis III partes, plantag⟨ine⟩ pota, Vettonica in oxymelitis drachma vel agarico obolis III, foli⟨is⟩ quinquefolii ex aqua. sanat et archezostis, sed anno pota. sanat et baccaris radix arida in pulverem contrita cyathis III cum coriandri uno in aqua calida, et centunculus trita in aceto aut melle aut in aqua calida, verbenaca ex vino pota, hysopi bacae ternae contritae in aqua potae diebus XVI, peucedanum cum coagulo vituli marini aequis portionibus potum, quinquefolii contrita folia ex vino et sumpta diebus XXX, Vettonicae farina pondere X iII cum aceti scillini cyatho, mellis Attici uncia, scamonium obolis II cum castorei drachmis IIII.", "st": "26.70"}, {"sp": "N", "t": "Febres frigidas leviores facit agaricum potum in calida aqua, tertianas sideritis cum ole⟨o⟩, item ladanum, quod in segetibus nascitur, contusum, plantago ex aqua mulsa II horis ante accessionem pota binis drachmis vel sucus radicis madefactae vel tusae vel ipsa radix trita in aqua ferro calfacta. quidam ternas radices in III cyathis aquae dedere. eadem in quartanis quaterna fecerunt. buglosso inarescente, si quis medullam e caule eximat dicatque, ad quem liberandum febri id faciat, et alliget ei VII folia ante accessionem, aiunt febri liberari; item Vettonicae... drachmam in aquae mulsae cyathis III vel agaricum, maxime in ⟨i⟩is febribus, quae cum horrore veniant. quinquefolii folia quidam terna tertianis dedere, quaterna quartanis, plura ceteris; alii omnibus III obolos cum pipere ex aqua mulsa. verbenaca quidem et iumentorum febribuss in vino medetur, sed in tertianis a tertio geniculo incisa, quartanis a quarto. bibitur et semen hyperici utriusque in quartanis et horroribus, Vettonicae farina, quae omnes horrores coercet, item panaces, adeo excalefactoria natura, ut per nivem ituris bibere id perunguique eo praecipiant. et aristolochia perfrictionibus resistit.", "st": "26.71"}, {"sp": "N", "t": "Phreneticos somnus sanat, qui contingit peucedano ex aceto capiti infuso, anagallidum suco. e diverso lethargicos excitare labor est; hoc praestant Euphorbeum ex aceto naribus tactis, peucedani sucus. contra insanias Vettonica bibitur. carbunculos rumpit panaces, sanat Vettonicae farina ex aqua aut brassica cum ture, frequenti potu calidae, vel e carbone in conspectu restincto favilla digito sublata et inlita, vel plantago tusa, tithymallus characi⟨a⟩s.", "st": "26.72"}, {"sp": "N", "t": "Hydropicos sanat panac⟨e⟩s, plantago in cibo, cum prius panem siccum comederint sine potu, Vettonica drachmis II in II cyathis vini aut mulsi, vel agaricum vel semen lonchitidis II lingulis ex aqua potum, psyllion ex vino, anagallidum sucus, cotyledonis radix e mulso, ebuli recentis radix excussa tantum nec colluta, quod II digiti conprehendant, ex vini veteris caldi hemina, trifolii radix drachmis II in vino, tithymallum platyphyllon cognomine, semen hyperici, quod caros appellatur, acte, quam esse ebulum putant quidam, radice contrita in vini cyathis III, si febris absit, vel semine ex vino nigro, item verbenaca fasciculo manus plenae in aqua decocta ad dimidias. praecipue tamen chamaeactes sucus aptissimus creditur.— Eruptiones pituitae emendant plantago, cyclamini radix e melle, ebuli folia trita e vetere vino; inposita etiam boam sanant, id est rubentes papulas, pruriginem sucus strychni inlitus.", "st": "26.73"}, {"sp": "N", "t": "Igni sacro medenturn aizoum, folia trita cicutae, mandragorae radix; secatur in asses ut cucumis, primumque super mustum suspenditur, mox in fumo, dein t⟨er⟩itur e vino aut aceto. prodest et vino myrteo fovere, mentae sextans vivi sulpuris uncia ex aceto simul trita, fuligo ex aceto. ignis sacri plura sunt genera, inter quae medium hominem ambiens, qui zoster vocatur, et enecat, si cinxit. medetur plantago cum creta Cimolia et peristereos per se, radix persollatae; aliis, quae serpunt, cotyledonis radix cum mulso, aizoum, sucus e linozosti ex aceto.", "st": "26.74"}, {"sp": "N", "t": "Radix polypodi inlita luxatis medetur, doloremque et tumores tollunt semen psyllii, folia plantaginis trita, sale modice addito, verbasci semen ex vino decoctum contritum, cicuta cum axungia. folia ephemeri tuberibus tumoribusque inlinuntur, quae etiamtum discuti possunt.", "st": "26.75"}, {"sp": "N", "t": "Morbum regium in oculis praecipue mirari est, tenuitatem etiam densitatemque tunicularum felle subeunte. Hippocrates a septimo die in febri mortiferum signum esse dicit. nos scimus vixisse aliquos etiam ab hac desperatione. fit vero et citra febres expugnaturque centaurio maiore ut diximus poto, Vettonica, agarici obolis III ex vini veteris cyatho, item verbenacae folia obolis III ex vini calidi hemina quadriduo. sed celerrime quinquefolii sucus medetur III cyathis potus. cyclamini radix drachmis III bibitur in loco calido et a perfrictionibus tuto—sudores enim felleos movet—, folia tussilaginis ex aqua, semen linozostis utriusque inspersum potioni vel cum absinthio aut cicere decoctum, hysopi bacae cum aqua potae, lichen herba, si, cum sumitur, cetero olere abstineatur, polythrix in vino data, struthion in mulso.", "st": "26.76"}, {"sp": "N", "t": "Passim et in quacumque parte, sed maxime incommoda nascuntur qui furunculi vocantur, mortiferum aliquando malum consectis corporibus. remedio sunt pycnocomi folia trita cum polenta, si nondum caput fecerint. discutiunt et folia ephedri inlita.", "st": "26.77"}, {"sp": "N", "t": "Fistulae quoque in omni parte serpunt medicorum vitio male sectis corporibus. auxilio est centaurium minus collyriis cum melle decocto additis, plantaginis sucus infusus, quinquefolium cum sale et melle, ladanum cum castoreo, cotyledon cum medulla cervina calefacta et inposita; verbasci radicis medulla collyrii tenuitate in fistulam additur vel aristolochiae radix vel sucus tithymalli.", "st": "26.78"}, {"sp": "N", "t": "Collectiones inflammationesque sanant argemoniae folia inlita, duritias et collectiones omnes verbenaca vel quinquefolium decoctum in aceto, verbasci folia vel radix, hysopum e vino inpositum, acori radix decocto eius foventibus, aizoum, item quae contusa sint duritiasque et sinus corporis illecebra. omnia infixa corpori extrahunt folia tussilaginis, daucum, semen leontopodii tritum in aqua cum polenta. suppurationibus inponuntur pycnocomi folia trita cum polenta vel semen, item orchis. vitia, quae sint in ossibus, satyrii radice inposita efficacissime sanari dicuntur, nomae et collectiones omnes fuco maris, priusquam inarescat. et alcimae radix collectiones discutit.", "st": "26.79"}, {"sp": "N", "t": "Ambusta sanantur plantagine, arctio ita ut cicatrix fallat —folia eius in aqua decocta contrita inlinuntur—, radice cyclamini, aizoo, herba ipsa hyperici, quod corissum appellavimus.", "st": "26.80"}, {"sp": "N", "t": "Nervis et articulis convenit plantago trita cum sale, argemonia tusa ex melle. peucedani suco perunguntur spastici, tetanici, nervorum duritiae aegilopis suco; doloribus ⟨e⟩rigeron ex aceto inlinitur, epithymum. spasticis et opisthotonicis perungui semine hyperici, quod caros vocatur, idemque bibere prodest. phrynion dicitur etiam abscisos sanare nervos, si confestim inponatur trita vel mansa. spasticis, tremulis, opisthotonicis alcimae radix bibitur ex aqua mulsa. sic et rigores excalfacit.", "st": "26.81"}, {"sp": "N", "t": "Sanguinis profluvia sistit herbae Paeoniae semen rubrum —eadem et in radice vis—, clymenus vero, sive ore sanguis reiciatur sive naribus sive alvo fluat sive feminarum utero, item Lysimachia pota vel inlita vel naribus indita, item plantaginis semen, quinquefolium potum et inlitum, cicutae semen in nares, si inde fluat, tritum ex aqua inditum, aizoum, astragali radix. sistit et ⟨i⟩sch⟨a⟩emon et Achillia.", "st": "26.82"}, {"sp": "N", "t": "Equisaetum, hippuris Graecis dicta et in pratis vituperata nobis—est autem pilus terrae equinae saetae similis—, lienes cursorum extinguit decocta fictili novo ad tertias quantum vas capiat et per triduum heminis pota; unctis esculentis ex ante diem unum interdicitur. Graecorum varia circa hanc opinio: alii pinus foliis similem, nigricantem eodem nomine appellant, vim eius admirabilem tradentes, sanguinis profluvia vel tacto tantum ea homine sisti; alii hippurin, alii ephedron, alii anabasim vocant, traduitque iuxta arbores nasci et scandente⟨m⟩ eas dependere comis iunceis multis, nigris, ut ex equorum cauda, geniculatis ramulis, folia habere pauca, tenuia, exigua, semen rotundum, simile coriandro, radice lignosa, nasci in arbustis maxume. vis eius spissare corpora. sucus sanguinem e naribus fluentem inclusus sistit, item alvum. medetur dysintericis in vino dulci potus cyathis III, urinam ciet, tussim, orthopnoeam sanat, item rupta et quae serpunt. intestinis et vesicae folia bibuntur, enterocelen cohibet. faciunt et aliam hippurim brevioribus et mollioribus comis candidioribusque, perquam utilem ischiadicis et vulneribus ex aceto inposita⟨m⟩ propter sistendum sanguinem. —Et nymphaea trita plagis inponitur. peucedanum cum semine cupressi bibitur, si sanguis per os redditus est fluxitve ab infernis. sideritis tantam vim habet, ut quamvis recenti gladiatoris vulneri inligata sanguinem claudat, quod facit et ferulae cinis vel carbo, fungus vero etiam efficacius, qui secundum radicem eius nascitur.", "st": "26.83"}, {"sp": "N", "t": "per nares autem fluenti et cicutae semen tritum ex aqua additumque efficax habetur, item stephanomelis ex aqua. Vettonicae farina e lacte caprino pota sistit ex ubere fluentem plantagoque contusa. eiusdem sucus vomentibus sanguinem datur. ad erraticum autem radix persollatae cum axungia vetere inlita probatur;", "st": "26.84"}, {"sp": "N", "t": "ruptis convulsisque, ex alto deiectis centaurium maius, Gentianae radix trita vel decocta vel sucus, Vettonica et hoc amplius a vocis aut lateris contentionibus panaces, scordium, aristolochia pota, agaricum, i⟨d⟩em contusis et eversis potum II obolis in mulsi cyathis III aut, si febris sit, in aqua mulsa, verbascum, cuius flos similis auro est, acori radix, aizoum omne, sed maioris sucus efficacissime, item symphyti ius vel radicis decoctum, daucos cruda, erysithales—flore luteo, foliis acanthi —e vino, item chamaerops et in sorbitione irio vel plantago omnibus modis, item …", "st": "26.85"}, {"sp": "N", "t": "Phthiriasi Sulla dictator consumptus est, nascunturque in sanguine ipso hominis animalia exesura corpus. resistitur uvae taminiae suco aut veratri cum oleo perunctis corporibus; taminia quidem in aceto decocta etiam vestes eo taedio liberat.", "st": "26.86"}, {"sp": "N", "t": "Ulcera multorum sunt generum ac multis modis curantur. panacis omnium generum radix ex vino calido inlinitur manantibus. sicca⟨t⟩ privatim quam Chironiam diximus; cum melle trita tubera aperit ulceribusque, quae serpunt, deploratis auxilio est cum aeris flore vino temperata omnibus modis, vel semine vel flore vel radice. eadem cum polenta vetustis volneribus prodest, Heraclion quoque siderion, Apollinaris, psyllium, tragacantha. scordotis cum melle purgat; farina eius carnis excrescentes per se inspersa consumit. Polemonia ulcera, quae cacoëthe vocant, sanat; centaurium maius inspersum vel inlitum, item minoris coma decocta vel trita vetera quoque ulcera purgat et persanat. folliculi clymeni recentibus plagis inponuntur. inlinitur autem Gentiana ulceribus, quae serpunt, radice tusa vel decocta in aqua ad mellis crassitudinem vel suco, volneribus ex ea factum Lycium. Lysimachia recentibus plagis medetur, plantago omnium generum ulceribus, peculiariter senum et infantium. igni emollita melior et cum cerato crassa ulcerum labra purgat, nomas sistit; tritam suis foliis integere oportet. suppurationes, collectiones, sinus ulcerum chelidonia quoque siccantur, volnera adeo, ut etiam pro spodio utantur; eadem iam desperatis cum axungia inponitur. dictamnum pota sagittas pellit et alia tela extrahit inlita—bibitur ex aquae cyatho foliorum obolo—, proxime pseudodictamnum; utraque et suppurationes discutit. aristolochia quoque putria ulcera exest, sordida purgat cum melle vermesque extrahit, item clavos in ulcere natos et infixa corpori omnia, praecipue sagittas et ossa fracta cum resina, cava vero ulcera explet per se et cum iride, recentia vulnera ex aceto; vetera ulcera verbenaca, quinquefolium cum sale et melle. radices persollatae volneribus ferro inlatis recentibus inponuntur, folia veteribus; cum axungia utr⟨i⟩mque et suo folio operitur damasonium, ut in struma, folia verbasci ex aceto ant vino. peristereos ad omnia genera vel callosorum putrescentiumque ulcerum facit. manantia nymphaeae Heracliae radix sanat, item cyclamini radix vel per se vel ex aceto vel cum melle; eadem et contra steatomata efficax. sic et ad ulcera manantia hysopum, item peucedanum; e⟨i⟩ ad recentia volnera vis tanta est, ut squamam ossibus extrahat. praestant hoc et anagallides cohibentque quas vocant nomas et rheumatismos, utiles et recentibus plagis, sed praecipue senum corpori, cum cerato apostemata et ulcera taetra folia mandragorae recentia, radix volnera cum melle aut oleo, cicuta cum siligine mixta mero, aizoum herpetas quoque ac nomas ac putrescentia, sicut erigeron verminosa, recentia autem volnera astragali radix et vetera ulcera, quae purgat hypocisthis utraque. leontopodii semen tritum in aqua et cum polenta inlitum spicula sagittarum extrahit, item pycnocomi semen. tithymallus characias suco gangraenas, phagedaenas, putria vel decocto ramorum cum polenta et oleo, orchis radices hoc amplius et cacoëthe cum melle, siccae et recentes per se vulnera, onothera effer⟨a⟩ntia sese ulcera sanat. Scythae ul⟨c⟩era Scythica curant. ad carcinomata argemonia ex melle efficacissima est. ulceribus praesanatis asphodeli radix decocta ut diximus, trita cum polenta et inlita, quibuscumque vero Apollinaris, astragali radix in pulverem trita umidis ulceribus prodest, item callithrix decocta in aqua, privatim vero iis, quae calciamento facta sint, verbenaca nec non et Lysimachia contrita ac nymphaea arida infriata. polythrix inveteratis iisdem utilior est. —", "st": "26.87"}, {"sp": "N", "t": "Polycnemon cunilae bubulae similis est, semine pulei, surculosa, multis geniculis, corymbo [odorata ] acri et dulci odore, ferro factis conmanducata inponitur, quinto die solvitur. symphyton ad cicatricem celerrime perducit, item sideritis; haec inponitur ex melle. verbasci semine ac foliis ex vino decoctis ac tritis omnia infixa corpori extrahuntur, item mandragorae foliis cum polenta, cyclamini radicibus cum melle. trixaginis folia in oleo contrita iis maxime adhibentur ulceribus, quae serpunt, et al⟨ci⟩ma in melle trita, Vettonica ad carcinomata et malandrias veteres addito sale.", "st": "26.88"}, {"sp": "N", "t": "Verrucas tollit argemonia ex aceto vel batrachii radix, quae et ungues scabros aufert, linozostidis utriusque folia vel sucus inlitus. tithymalli omnes genera verrucarum omnia, item pterygia, varos tollunt; cicatrices cum elegantia ad colorem reducit ladanum.—", "st": "26.89"}, {"sp": "N", "t": "Artemisiam et elelisphacum alligatas qui habeat viator negatur lassitudinem sentire.—", "st": "26.89"}, {"sp": "N", "t": "Muliebribus morbis medetur maxime in universum Paeoniae herbae semen nigrum ex aqua mulsa; eadem et in radice vis. menses ciet panacis semen cum absinthio, menses et sudores scordotis potu et inlitu. Vettonica drachma in vini cyathis III bibitur contra omnia volvarum vitia aut quae a partu fiunt. menses nimios sistit Achillia adposita et decoctum eius insidentibus. mammis inponitur hyoscyami semen ex vino, locis radix in cataplasmate, mammis et chelidonia. secundas morantes vel partus emortuos radices panacis adpositae extrahunt. ipsum panac⟨e⟩s e vino potum volvas purgat adpositumque cum melle. Polemonia pota ex vino secundas pellit, nidore corrigit volvas. centauri minoris sucus potu fotuque menses ciet, item maioris radix in volvae doloribus isdem modis prodest, derasa vero et adposita extrahit partus emortuos. plantago adponitur in lana in dolore volvae, in strangulatu bibitur. sed praecipua dictamno vis est: menses ciet, partus emortuos vel traverses eicit—bibitur ex aqua foliorum obolo—, adeo ad haec efficax, u⟨t⟩ ne in cubiculum quidem praegnantium inferatur, nec potu tantum, sed et inlitu et suffitu valet; proxime pseudodictamnum, sed menses ciet cum mero decoctum denarii pondere. plurimis tamen modis aristolochia prodest, nam et menses et secundas ciet et emortuos partus extrahit, murra et pipere additis pota vel subdita; volvas quoque procidentes inhibet fotu vel suffitu vel subiectu, maxime tenuis. strangulatum ab his mensumque difficultatem agaricum obolis III in vini veteris cyatho potum emendat, peristereos adposita in adipe suillo recenti, antirrhinon cum rosaceo et melle. item adposita nymphaeae Thessalae radix dolori medetur, in vino nigro pota profluvia inhibet; e diverso ciet cyclamini radix pota et adposita et vesicae insidentium decocto medetur. secundas pota cissanthemos pellit, volvam sanat. e xiphio radix superior menses ciet drachma ex aceto pota. peucedanum strangulatus volvae nidore ustum recreat, menses albos praecipue psyllion drachma in cyathis III aquae, semen mandragorae potum volvam purgat, menses ciet sucus adpositus et emortuos partus. nimia rursus proluvia sistit semen cum vivo sulphure, contra ⟨e⟩a ciet batrachium potu vel cibo, ardens alias, ut diximus, cruda, sed cocta commendatur sale et oleo et cumino. daucum et menses et secundas potu facillime pellit, ladanum suffitu corrigit volvas, dolori earum exulceratisque inponitur. emortua scamonium pellit potum vel adpositum. menses ciet hypericum utrumque adpositum, ante alia vero, ut Hippocrati videtur, crethmos e vino semine vel radicis cortice, trahit et secund⟨a⟩s, succurrit et strangulationibus ex aqua pota; item radix e geranio peculiariter secundis inflationibusque volvarum conveniens. purgat hippuris pota et adposita volvas, polygonus pota. menses ciet et alc⟨i⟩mae radix, folia plantaginis pellunt, item agaricum ex aqua mulsa. Artemisia volvae medetur trita, ex oleo irino aut cum fico aut cum murra adposita; eiusdem radix pota in tantum purgat, ut partus enectos extrahat. menses et secundas ciet ramorum decoctum insidentibus, item folia pota drachma. ad eadem omnia prosunt vel inposita ventri imo cum farina hordeacia. acoron quoque utile est interioribus feminarum morbis et conyza utraque et crethmos. et anthyllides duae vulvis utilissimae torminibusque et secundarum morae in vino potae. callithrix fotu locis medetur, albugines in capite tollit, capillos inficit oleo trita. geranion in vino albo potum, hypocisthis in rubro profluvium sistunt. hysopum suffocationes laxat. radix verbenacae pota ex aqua ad omnia in partu aut ex partu mala praestantissima est. peucedano quidam miscent in vino nigro semen cupressi contritum. nam semen psyllii defervefactum in aqua, cum intepuit, epiphoras omnes uteri lenit. symphyton tritum in vino nigro evocat me⟨n⟩ses. partus accelerat scordotis pota drachma suci in aquae mulsae cyathis IIII. dictamni folia praeclare dantur ex aqua; constat unius oboli pondere, vel si mortui sint in utero infantes, protinus reddi sine vexatione puerperae. similiter prodest pseudodictamnum, sed tardius, cyclaminos adalligata, cissanthemos pota, item Vettonicae farina ex aqua mulsa.", "st": "26.90"}, {"sp": "N", "t": "Arsenogonon et thelygonon herbae sunt habentes uvas floribus oleae similes, pallidioris tamen, semen album papaveris modo. thelygoni potu feminam concipi narrant; arsenogonon ab ea semine oleae nec alio distat; huius potu mares generari, si credimus. alii utramque ocimo simil⟨em⟩ tradunt, arsenogoni autem semen geminum esse testibus simile.", "st": "26.91"}, {"sp": "N", "t": "Mammarum vitiis aizoum, quod digitillum appellavimus, unice medetur. ⟨e⟩rigeron ex passo mammas uberiores facit, sonc⟨i⟩ cum farre coct⟨i i⟩us. quae vero mastos vocatur, inlita pilos mammarum partu nascent⟨es⟩ aufert; testas in facie aliaque cutis vitia emendat Gentiana, nymphaea Heraclia inlita, cyclamini radix maculas omnes. cacaliae grana mixta cerae liquidae extendunt cutem in facie erugantque. vitia omnia acori radix emendat.", "st": "26.92"}, {"sp": "N", "t": "Capillum lyci⟨u⟩m ⟨su⟩co flavum facit, denigrat hypericum, quod et coris⟨s⟩um vocatur, item ophr⟨y⟩s herba, denticulato oleri similis, foliis II. nigritiam dat et Polemonia in oleo decocta. psilotrum nos quidem in muliebribus medicamentis tractamus, verum iam et viris est in usu. efficacissimum autem habetur archezostis, item tithymalli, suco vel in sole cum oleo inlito crebro vel evolsis pilis. —Quadripedum scabiem sanat hysopum ex oleo, suum anginas peculiariter sideritis.—Verum et reliqua genera herbarum reddamus.", "st": "26.93"}, {"sp": "HDR", "t": "Liber XXVII", "st": "27"}, {"sp": "N", "t": "Crescit profecto apud me certe tractatu ipso admiratio antiquitatis, quantoque maior copia herbarum dicenda restat, tanto magis adorare priscorum in inveniendo curam, in tradendo benignitatem subit. nec dubie superata hoc modo posset videri etiam rerum naturae ipsius munificentia, si humani operis esset inventio. nunc vero deorum fuisse eam apparet aut certe divinam, etiam cum homo inveniret, eandemque omnium parent⟨e⟩m et genuisse haec et ostendisse, nullo vitae miraculo maiore, si verum fateri volumus. Scythicam herbam a Maeotis paludibus et Euphorbeam e monte Atlante ultraque Herculis columnas e⟨x⟩ ipso rerum naturae defectu, parte alia Britannicam ex oceani insulis extra terras positis, itemque Aethiopidem ab exusto sideribus axe, alias praeterea aliunde ultro citroque humanae saluti in toto orbe portari, inmensa Romanae pacis maiestate non homines modo diversis inter se terris gentibusque, verum etiam mont⟨e⟩s et excedentia in nubes iuga partusque eorum et herbas quoque invicem ostentante! aeternum, quaeso, deorum sit munus istud! adeo Romanos velut alteram lucem dedisse rebus humanis videntur.", "st": "27.1"}, {"sp": "N", "t": "Sed antiquorum curam diligentiamque quis possit satis venerari? constat omnium venenorum ocissimum esse aconitum et tactis quoque genitalibus feminini sexus animalium eodem die inferre mortem. hoc fuit vnenum, quo interemptas dormientes a Calpurnio Bestia uxores M. Caelius accusator obiecit. hinc illa atrox peroratio eius in digitum. ortum fabulae narravere e spumis Cerberi canis extrahente ab inferis Hercule ideoque apud Heracleam Ponticam, ubi monstratur is ad inferos aditus, gigni. hoc quoque tamen in usus humanae salutis vertere scorpionum ictibus adversari experiendo datum in vino calido. ea est natura, ut hominem occidat, nisi invenerit quod in homine perimat. cum eo solo conluctatur veluti praesentius invento, [sola haec pugna est, cum venenum in visceribus reperit] mirumque, exitialia per se ambo cum sint, duo venena in homine conmoriuntur, ut homo supersit. immo vero etiam ferarum remedia antiqui prodiderunt demonstrando, quomodo venenata quoque ipsa sanarentur. torpescunt scorpiones aconiti tactu stupentque pallentes et vinci se confitentur. auxiliatur⟨i⟩is helleborum album tactu resolvente, ceditque aconitum duobus malis, suo et omnium. quae si quis ulla forte ab homine excogitari potuisse credit, ingrate deorum munera intellegit. tangunt cares aconito necantque gustatu earum pantheras, nisi hoc fieret, repleturas illos situs. ob id quidam pardalianches appellavere. at illas statim liberari morte excrementorum hominis gustu demonstratu⟨m⟩. quod certe casu repertum quis dubitet et, quotiens fiat, etiam nunc ut novum nasc, quoniam feris ratio et usus inter se tradi non possit?", "st": "27.2"}, {"sp": "N", "t": "hic ergo casus, hic est ille qui pluruma in vita invenit deus —hoc habet nomen per quem intellegitur eadem et parens rerum omnium et magistra—, utraque coniectura pari, sive ista cotidie feras invenire sive semper scire iudicemus. pudendumque rursus omnia animalia, quae sint salutaria ipsis, nosse praeter hominem. sed maiores oculorum quoque medicamentis aconitum misceri saluberrime promulgavere aperta professione, ne malum quidem ullum esse sine aliquo bono. fas ergo nobis erit, qui nulla diximus venena, monstrare quale sit aconitum, vel deprehendendi gratia. folia habet cyclamini aut cucumeris, non plura IIII, ab radice, leniter hirsuta, radicem modicam, cammaro similem marino; quare quidam cammaron appellavere, alii thelyphonon ex qua diximus causa. cauda radicis incurvatur paulum scorpionum modo, quare et scorpion aliqui vocavere. nec defuere qui myoctonon appellare mallent, quoniam procul et e longinquo odore mures necat. nascitur in nudis cautibus, quas aconas nominant, et ideo aconitum aliqui dixere, nullo iuxta, ne pulvere quidem, nutriente. hanc aliqui rationed nominis adtulere; alii, quoniam vis eadem esset in morte, quae cotibus in ferri acie deterenda, statimque admota velocitas sentiretur.", "st": "27.2"}, {"sp": "N", "t": "Aethiopis folia habet ⟨p⟩hl⟨o⟩mo similia, magna ac multa et hirsuta, ab radice, caulem quadriangulum, scabrum, similem arctio, multis concavum alis, semen ervo simile, candidum, geminum, radices numerosas, longas, plenas, molles, glutinosas gustu. siccae nigrescunt indurescuntque, ut cornua videri possint. praeter Aethiopiam nascuntur et in Ida monte Troadis et in Messenia. colliguntur autumno, siccantur in sole aliquot diebus, ne situm sentiant. medentur volvis pota⟨e⟩ in vino albo, ischiadicis, pleuriticis, faucibus scabris decoctae potui dantur. sed quae ex Aethiopia venit, eximie atque ilico prodest. —", "st": "27.3"}, {"sp": "N", "t": "A⟨g⟩eraton ferulacea est, duorum palmorum altitudine, origano similis, flore bullis aureis. huius ustae nidor urinam ciet volvasque purgat, tanto magis insidentibus. causa nominis [non haec, sed] quoniam diutissime non marcescit. —", "st": "27.4"}, {"sp": "N", "t": "Aloe scillae similitudinem habet, maior et pinguioribus foliis, ex obliquo striata. caulis eius tener est, rubens medius, non dissimilis antherici, radice una, ceu palo in terram demissa; ipsa gravis odore, gustu amara. laudatissima ex India adfertur, sed nascitur et in Asia, non tamen ea to utuntur nisi ad volnera recentibus foliis, mirifice enim conglutina⟨n⟩t suco. ob id in turbinibus cadorum eam serunt ut aizoum maius. quidam et caulem ante maturitatem seminis incidunt suci gratia, aliqui et folia. invenitur et per se lacrima adhaerens; ergo pavimentandum ubi sata sit censent, ut lacrima non absorbeatur. fuere qui traderent in Iudaea super Hierosolyma metallicam eius naturam, sed nulla magis inproba est, neque alia nigrior est aut umidior. erit ergo optima pinguis ac nitida, rufi coloris, friabilis et iocineris modo coacta, facile liquescens; inprobanda nigra et dura, harenosa, quaeque gustu intellegitur, cummi adulterata et acacia. natura eius spissare, densare et leniter calfacere; usus multi, sed principalis alvum solvere, cum paene sola medicamentorum, quae id praestant, confirmet etiam stomachum, adeo non infestet ulla vi contraria. bibitur drachma, ad stomachi vero dissolutionem in II cyathis aquae tepidae vel frigidae coclearis mensura bis terve in die ex intervallis, ut res exigit, purgationis autem causa plurimum III drachmis, efficacior, si pota ea sumatur cibus. capillum fluentem continet cum vino austero capite contra pilum peruncto. dolorem capitis sedat temporibus et fronti inposita ex aceto et rosaceo dilutiorque infusa. oculorum vitia omnia sanari ea convenit, privatim prurigines et scab⟨rit⟩iem genarum, item insignita ac livida inlita cum melle, maxime Pontico, tonsillas, gingivas et omnia oris ulcera, sanguinis excreationes, si modicae sint, drachma ex aqua, si minus, ex aceto pota. vulnerum quoque sanguinem et undecumque fluentem sistit per se vel ex aceto. alias etiam est vulneribus utilissima ad cicatricem perducens. eadem inspergitur exulceratis genitalibus virorum, condylomatis rimisque sedis, alias ex vino, alias ex passo, alias sicca per se, ut exigat mitiganda curatio aut coercenda. haemorrhoidum quoque abundantiam leniter sistit. dysinteriae infunditur et, si difficilius concoquantur cibi, bibitur a cena modico intervallo et in regio morbo III obolis ex aqua; devorantur et pilulae cum melle decocto aut resina terebinthina ad purganda interiora. digitorum pterygia tollit. oculorum medicamentis lavatur, ut quod sit harenosissimum subsidat, aut torretur in testa pinnaque subinde versatur, ut possit aequaliter torreri.—", "st": "27.5"}, {"sp": "N", "t": "Alcea folia habet similia verbenacae, quae aristereon cognominatur, caules II aut IIII, foliorum plenos, florem rosae, radices albas cum plurimum VI, cubitales, obliquas. nascitur in pingui solo nec sicco. usus radicis ex vino vel aqua dysintericis, alvo citae, ⟨ad⟩ rupta, convulsa.—", "st": "27.6"}, {"sp": "N", "t": "Alypon cauliculus est, molli capite, non dissimile betae, acre gustu ac lentum mordensque vehementer et accendens. alvum solvit in aqua mulsa addito sale modico. minima potio II drachmarum, media IIII, maxima VI, eximi⟨a⟩ purgatione quibus datur e gallinaceo⟨iu⟩re. —", "st": "27.7"}, {"sp": "N", "t": "Alsine, quam quidam myosoton appellant, nascitur in lucis, unde et alsine dicta est. incipit a media hieme, arescit aestate media. cum prorepit, musculorum aures imitatur foliis. sed aliam docebimus esse quae iustius myosotis vocetur. haec eadem erat quae hel⟨x⟩ine, nisi minor minusque hirsuta esset. nascitur in hortis et maxime parietibus. cum teritur, odorem cucumeris reddit. usus eius ad collectiones inflammationesque, ite⟨m⟩ eadem omnia quae hel⟨x⟩ine⟨s⟩, sed infirmius. epiphoris peculiariter inponitur, item verendis ulceribusque cum farina hordeacia. sucus eius auribus infunditur. —", "st": "27.8"}, {"sp": "N", "t": "Androsaces herba est alba, amara, sine foliis, folliculos in cirris habens et in his semen. nascitur in maritimis S⟨y⟩riae. maxime datur hydropicis drachmis II tusa aut decocta in aqua vel aceto vel vino; vehementer enim urinas ciet. datur et podagricis inliniturque. idem effectus et seminis. —", "st": "27.9"}, {"sp": "N", "t": "Androsaemon sive, ut alii appellavere, ascyron non absimile est hyperico, de qua diximus, cauliculis maioribus densioribusque et magis rubentibus. folia alba, rutae figura, semen papaveris nigri. comae tritae sanguineo suco manant; odor est resin⟨o⟩sus. gignitur in vineis, fere medio autumno effoditur suspenditurque. usus ad purgandam alvum tusae cum semine potaeque matutino vel a cena II drachmis in aqua mulsa vel vino vel aqua pura, potionis totius sextario. trahit bilem, prodest ischiadi maxime, sed poster⟨o⟩ die capparis radicem resinae permixtam devorare oportet drachmae pondere iterumque quadridui intervallo eadem facere, a purgatione autem ipsa robustiores vinum bibere, infirmiores aquam. inponitur et podagris et ambustis, et volneribus cohibens sanguinem. —", "st": "27.10"}, {"sp": "N", "t": "Ambrosia vagi nominis et circa alias herbas fluctuati unam habet certam, densam, ramosam, tenuem, III fere palmorum, tertia parte radice breviore, foliis rutae circa imum caulem. in ramulis semen est uvis dependentibus, odore vinoso, qua de causa botrys a quibusdam vocatur, ab aliis Artemisia. Coronantur illa Cappadoces. usus eius ad ea, quae discuti opus sit.—", "st": "27.11"}, {"sp": "N", "t": "Anonim quidam ononida malunt vocare, ramosam, as similem faeno Graeco, nisi fruticosior hirsutiorque esset. odore iucunda, post ver spinosa. estur etiam muria condita, recens vero margines ulcerum erodit. radix decoquitur in posca dolori dentium. eadem cum melle pota calculos pellit. comitialibus datur in oxymelite decocta ad dimidias. —", "st": "27.12"}, {"sp": "N", "t": "Anagyros, quam aliqui aco⟨p⟩on vocant, fruticosa est, gravis odore, flore oleris, semen in corniculis non brevibus gignit, simile renibus, quod durescit per messes. folia collectionibus inponuntur difficulterque parientibus adalligantur ita, ut a partu statim auferantur. quod si emortuus haereat et secundae mensesque morentur, drachma bibuntur in passo folia. sic et suspiriosis dantur et in vino vetere ad phalangiorum morsus. radix discutiendis concoquendisque adhibetur, semen commanducatum vomitiones facit.—", "st": "27.13"}, {"sp": "N", "t": "Anonymos non inveniendo nomen invenit. adfertur e Scythia, celebrata Hicesio, non parvae auctoritatis medico, item Aristogitoni in volneribus praeclara, ex aqua tusa inposita, pota vero mammis praecordiisve percussis, item sanguinem excreantibus. putavere et bibendam volneratis. fabulosa arbitror quae adiciuntur, recentem eam, si uratur, in ferrum aut aes feruminari.—", "st": "27.14"}, {"sp": "N", "t": "Aparinen aliqui ompha⟨l⟩ocarpon, alii philanthropon vocant, ramosam, hirsutam, quinis senisve in orbem circa ramos foliis per intervalla. semen rotundum, durum, concavum, subdulce. nascitur in frumentario agro aut hortis pratisve, asperitate etiam vestium tenaci. efficax contra serpentes semine poto ex vino drachma et contra phalangia. sanguinis abundantiam ex volneribus reprimunt folia inposita, sucus auribus infunditur. —", "st": "27.15"}, {"sp": "N", "t": "Arction aliqui potius arcturum vocant. similis est verbasco foliis, nisi quod hirsutiora sunt, caule longo, molli, semine cumini. nascitur in petrosis radice tenera, alba, dulci, qu⟨a⟩e decoquitur in vino ad dentium dolorem, ut ore ita contineatur. decoctum bibitur propter ischiada et stranguriam. ex vino ambustis inponitur et pernionibus; foventur eadem cum radice semine trito in vino. —", "st": "27.16"}, {"sp": "N", "t": "Asplenon sunt qui hemion⟨i⟩on vocant, foliis trientalibus, multis, radice limosa, cavernosa sicut felicis, candida hirsuta. nec caulem nee florem nec semen habet. nascitur in petris parietibusque opacis, umidis, laudatissima in Creta. huius foliorum in aceto decocto per dies XXX poto lienem absumi aiunt; et illinuntur autem eadem. sedant et singultus. feminis non danda, quoniam sterilitatem facit. —", "st": "27.17"}, {"sp": "N", "t": "Asclepias folia hederae habet, ramos longos, radices numerosas, tenues, odoratas, floris virus grave, semen securiclatum. nascitur in montibus. radices torminibus medentur et contra serpentium ictus non solum potu, sed et inlitu. —", "st": "27.18"}, {"sp": "N", "t": "Aster ab aliquis bubonion appellatur, quoniam inguinum praesentaneum remedium est. cauliculus foliis oblongis II aut III, in cacumine capitula stellae modo radiata. bibitur et adversus serpentes. sed ad inguinum medicinam sinistra manu decerpi iubent et iuxta cinctus alligari. prodest et coxendicis dolori adalligata. —", "st": "27.19"}, {"sp": "N", "t": "Ascyron et ascyroides similia sunt inter se et hyperico, sed maiores habet ramos quod ascyroides vocatur, ferulaceos, ⟨c⟩oma rubentes, capitulis parvis, luteis. semen in caliculis pusillum, nigrum, resinosum. comae tritae velut cruentant, qua de causa quidam hanc androsaemon vocavere. usus seminis ad ischiadicos poti II drachmis in hydromelitis sextario. alvum solvit, bilem detrahit. inlinitur et ambustis. —", "st": "27.20"}, {"sp": "N", "t": "Aphaca tenuia admodum folia habet, pusilla. altior lenticula et siliquas maiores fert, in quibus terna aut quaterna semina sunt, nigriora et minora lenticula. nascitur in arvis. natura ad spissandum efficacior quam lenti; reliquos usus eosdem habet. stomachi alvique fluctiones sistit semen decoctum. —", "st": "27.21"}, {"sp": "N", "t": "Alcibium qualis esset herba, non repperi apud auctores, sed radicem eius et folia trita ad serpentis morsum inponi et bibi, folia quantum manus capiat trita cum vini meri cyathis III aut radicem drachmarum III pondere cum vini eadem mensura.—", "st": "27.22"}, {"sp": "N", "t": "Alectoros lophos, quae apud nos crista dicitur, folia habet similia gallinacei cristae plura, caulem tenuem, semen nigrum in siliquis. utilis tussientibus cocta cum faba fresa, melle addito et caligini oculorum. solidum semen coicitur in oculum nec turbat, sed in se caliginem contrahit; mutat colorem et ex nigro albicare incipit et intumescit ac per se exit. —", "st": "27.23"}, {"sp": "N", "t": "Alum nos vocamus, Graeci symphyton petraeum, simile cunilae bubulae, foliis parvis, ramis III aut IIII a radice, cacuminibus thymi, surculosum, odoratum, gustu dulce, saliva ciens, radice longa, rutila. nascitur in petris, ideo petraeum cognominatum, utilissimum lateribus, renibus, torminibus, pectori, pulmonibus, sanguinem reicientibus, faucibus asperis. bibitur radix trita et in vino decocta, et aliquando superlinitur. quin et commanducata sitim sedat praecipueque pulmonem refrigerat. luxatis quoque inponitur et contusis, lenit interanea. alvum sistit cocta in cinere detractisque folliculis trita cum piperis granis VIIII et ex aqua pota. volneribus sanandis tanta praestantia est, ut carnes quoque, dum cocuntur, conglutinet addita, unde et Graeci nomen inposuere. ossibus quoque fractis medetur,", "st": "27.24"}, {"sp": "N", "t": "alga rufa scorpionum ictibus.—", "st": "27.25"}, {"sp": "N", "t": "Actaea gravi foliorum odore, caulibus asperis, geniculatis, semine nigro ut hederae, bacis mollibus, nascitur in opacis et asperis aquosisque. datur acetabulo pleno interioribus feminarum morbis. —", "st": "27.26"}, {"sp": "N", "t": "Ampelos agria vocatur herba foliis duris, cineracei coloris, qualem in satis diximus, viticulis longis, callosis, rubentibus qualiter flos quam Iovis flammam appellamus. in u⟨v⟩olis fert semen simile Punici mali acinis. radix eius decocta in aquae cyathis ternis, additis vini Coi cyathis II, alvum solvit leniter ideoque hydropicis datur. uvolae vitia cutis in facie mulierum emendant. ischiadicos quoque uti hac herba prodest tusa cum foliis et inlita cum suco suo.", "st": "27.27"}, {"sp": "N", "t": "Absinthii genera plura sunt: Santonicum appellatur e Galliae civitate, Ponticum e Ponto, ubi pecora pinguescunt illo et ob id sine felle reperiuntur, neque aliud praestantius, multoque Italicum amarius, sed medulla Pontici dulcis. de usu eius convenit, herbae facillimae atque inter paucas utilissimae, praeterea sacris populi Romani celebratae peculiariter, siquidem Latinarum feriis quadrigae certant in Capitolio victorque absinthium bibit, credo, sanitatem praemio dari honorifice arbitratis maioribus. stomachum corroborat, et ob hoc sapor eius in vina transfertur, ut diximus. bibitur et decoctum aqua ac postea nocte et die refrigeratum sub diu; decoci VI drachmis foliorum cum ramis suis in caelestis aquae sextariis III oportet, nec non salem addi vetustissim⟨i⟩ usus est. bibitur et madefacti dilutum; ita enim appelletur hoc genus. diluti ratio ut, quisquis fuerit modus aquae, tegatur per triduum. tritum raro in usu est, sicut et sucus expressi. exprimitur autem, cum primum semen turgescit, madefactum aqua triduo recens aut siccum VII diebus, dein coctum in aēneo vaso ad tertias x heminis in aquae sextariis XLV iterumque percolatum, herba electa, coquitur ad crassitudinem mellis, qualiter e⟨x⟩ minore centaurio quaeritur sucus. sed hic [absinthii] inutilis stomacho capitique est, cum sit ille decoct⟨u⟩s saluberrimus. namque adstringit stomachum bilemque detrahit, urinam ciet, alvum emollit et in dolore sanat, ventris animalia pellit, malaciam stomachi et inflationes discutit cum sile et nardo Gallico, aceti exiguo addito, fastidia absterget, concoctiones adiuvat, cruditates detrahit cum ruta et pipere et sale. antiqui purgationis causa dabant cum marinae aquae veteris sextario seminis VI drachmas cum III salis, mellis cyatho; efficacius purgat duplicate sale. diligenter autem teri debet propter difficultatem. quidam et in polenta dedere supra dictum pondus, addito puleio, alii pueris [folia] in fico sicca, ut amaritudinem fallerent. thoracem purgat cum iride sumptum. in regio morbo crudum bibitur cum apio aut adianto. adversus inflationes calidum paulatim sorbetur ex aqua, iocineris causa cum Gallico nardo, lienis cum aceto aut pulte aut fico sumitur. adversatur fungis ex aceto, item visco, cicutae ex vino et muris aranei morsibus, draconi marino, scorpionibus. oculorum claritati multum confert, epip]horis cum passo inponitur, suggillatis cum melle. aures decoct⟨i⟩ eius vapor suffitu sanat aut, si manent sanie, cum melle tritum. urinam ac menses cient III IIIIve ramuli cum Gallici nardi radice una, cyathis aquae VI, menses privatim cum melle sumptum et in vellere adpositum. anginae subvenit cum melle et nitro. epinyctidas ex aqua sanat, volnera recentia prius quam aqua tangantur inpositum, praeterea capitis ulcera. peculiariter ilibus inponitur cum Cypria cera aut cum fico. sanat et pruritus. non est dandum in febri. nausiam maris arcet in navigationibus potum, inguinum tumorem in ventrali habitum. somnos adlicit olfactum aut inscio sub capite positum. vestibus insertum tineas arcet. culices ex oleo perunctis abigit et fumo, si uratur. atramentum librarium ex diluto eius temperatum litteras a musculis tuetur. capillum denigrat absinthii cinis unguento rosaceoque permixtus. —", "st": "27.28"}, {"sp": "N", "t": "Est et absinthium marinum, quod quidam seriphum vocant, probatissimum in Taposiri Aegypti. huius ramum Isiaci praeferre sollemne habent. angustius priore minusque amarum, stomacho inimicum, alvum mollit pellitque animalia interaneorum. bibitur cum oleo et sale aut in farinae trimestris sorbitione dilutum. coquitur quantum manus capiat in aquae sextario ad dimidias.", "st": "27.29"}, {"sp": "N", "t": "Balloten alio nomine porrum nigrum Graeci vocant, herbam fruticosam angulosis caulibus, nigris, hirsutis, foliis vestientibus maioribus quam porri et nigrioribus, graveolentibus. vis eius efficax adversus canis morsus ex sale foliis tritis inpositae, item ad condylomata coctis cinere in folio oleris. purgat et sordida ulcera cum melle. —", "st": "27.30"}, {"sp": "N", "t": "Botrys fruticosa herba est luteis ramulis. semen circa totos nascitur, folia cichorio similia. invenitur in torrentium ripis. medetur orthopnoicis. hoc Cappadoces ambrosiam vocant, alii Artemisiam.—", "st": "27.31"}, {"sp": "N", "t": "Brabilla spissandi vim habet cotonei mali modo, nec amplius de ea tradunt auctores. —", "st": "27.32"}, {"sp": "N", "t": "Bryon marinum herba sine dubitatione est lactucae foliis similis, rugosa velut contracta, sine caule ab una radice exeuntibus foliis. nascitur in scopulis maxime testisque terra conprehensis. praecipua siccandi spissandique vis ⟨e⟩i et collectiones inflammationesque omnes inhibendi, praecipue podagrae et quicquid refrigerari opus sit. —", "st": "27.33"}, {"sp": "N", "t": "Buple⟨u⟩ri semen ad ictus serpentium dari reperio foverique plagas decocta ea herba adiectis foliis mori aut origani.", "st": "27.34"}, {"sp": "N", "t": "Catanancen Thessalam herbam, qualis sit, describi a nobis supervacuum est, cum sit usus eius ad amatoria tantum. illud non ab re est dixisse ad detegendas magicas vanitates, electam ad hunc usum coniectura, quoniam arescens contraheret se ad speciem unguium milui exanimati. eadem ex casa et cemos silebitur nobis.—", "st": "27.35"}, {"sp": "N", "t": "Cal⟨yx⟩ duorum generum est. una similis aro nascitur in arationibus, colligitur ante quam inarescat. usus eosdem habet quos ar⟨i⟩s, a⟨t⟩ bibitur radix quoque huius ad exinaniendas alvos mensesque mulierum, item caules cum foliis in leguminibus decocti sanant tenesmon.", "st": "27.36"}, {"sp": "N", "t": "alterum genus eius quidam anchusam vocant, alii r⟨h⟩inoc⟨l⟩iam. folia lactucae longiora, plumosa, radice rubra, quae ignes sacros cum flore polentae sanat inposita, iocineris autem vitia in vino albo pota. —", "st": "27.37"}, {"sp": "N", "t": "Circaea trychno sativo similis est, flore nigro, pusillo, parvo semine milii nascente in quibusdam corniculis, radice semipedali, triplici fere aut quadruplici, alba, odorata, gustus calidi. nascitur in apricis saxis. diluitur in vino bibiturque ad dolorem vulvae et vitia —macerari oportet in sextariis III quadrantem radicis tusae nocte et die—et trahit eadem potio⟨n⟩e secundas, semine lac [minuit ] in vino aut mulsa aqua poto. —", "st": "27.38"}, {"sp": "N", "t": "Cirsion cauliculus est tener II cubitorum, triangulo similis, foliis spinosis circumdatus. spinae molles sunt; folia bovis linguae similia, minora, subcandida, in cacumine capitula purpurea, quae solvuntur in lanugines. hanc herbam radicemve eius adalligatam dolores varicum sanare tradunt. —", "st": "27.39"}, {"sp": "N", "t": "Crataegonon spicae tritici simile est, multis calamis ex una radice emicantibus multorumque geniculorum, in opacis, semine milii, vehementer aspero gustu, quod si bibant ex vino ante cenam III obolis in cyathis aquae totidem mulier ac vir ante conceptum diebus XL, virilis sexus partum futurum aiunt. et alia est crataegonos, quae thelygonos vocetur; differentia intellegitur lenitate gustus. sunt qui florem crataegoni bibentes mulierum intra XL diem concipere tradant. eadem sanant ulcera vetera nigra cum melle et explent sinus ulcerum et atropha carnosiora faciunt, purulenta expurgant; panos discutiunt, podagras collectionesque omnes leniunt, peculiariter mammarum. Theophrastus arboris genus intellegi voluit crataegon sive crataegona, quam Itali aquifolium vocant. —", "st": "27.40"}, {"sp": "N", "t": "Crocodileon chamaeleonis herbae nigrae figuram habet, radice longa, aequaliter crassa, odoris asperi. nascitur in sabuletis. pota sanguinem per nares pellit copiosum crassumque; itaet lienes consumere dicitur. —", "st": "27.41"}, {"sp": "N", "t": "Cynos⟨o⟩rc⟨h⟩im aliqui orchim vocant, foliis oleae, mollibus, ternis per semipedem longitudinis in terra stratis, radice bulbosa, oblonga, duplici ordine, superiore quae durior est, inferiore quae mollior. eduntur, ut bulbi coctae, in vineis fere inventae. ex his radicibus si maiorem edant viri, mares generari dicunt, si minorem feminae, alterum sexum. in Thessalia molliorem in lacte caprino viri bibunt ad stimulandos coitus, duriorem vero ad inhibendos. adversantur alter⟨a⟩ alteri.—", "st": "27.42"}, {"sp": "N", "t": "Chrysolachanum in pineto lactucae simile nascitur. sanat nervos incisos, si confestim inponatur. et alibi genus chrysolachani traditur, flore aureo, foliis oleris. coctum estur ut olus molle. haec herba adalligata morbum regium habentibus ita, ut spectari ab his possit, sanare id malum traditur. de chrysolachano nec satis dici scio nec plura reperio. namque et hoc vitio laboravere proximi utique herbarii nostri, quod ipsis notas veluti vulgares strictim et nominibus tantum indicavere, tamquam coagulo terrae alvum sisti, stranguriam dissolvi, si bibatur ex aqua aut vino,", "st": "27.43"}, {"sp": "N", "t": "cuculli folia trita cum aceto serpentium ictibus et scorpionum mederi. quidam hanc alio nomine strumum appellant, alii Graece str⟨y⟩c⟨h⟩num. acinos habet nigros; ex his cyathus suci cum mulsi II medetur lumbis, item capitis dolori cum rosaceo infusus, ipsa struma⟨e⟩ inlita.—", "st": "27.44"}, {"sp": "N", "t": "Peculiaris est Alpinis maxime fluminibus conferva appellata a conferuminando, spongea aquarum dulcium verius quam muscus aut herba, villosae densitatis atque fistulosae. curatum ea scio omnibus fere ossibus confractis prolapsum ex arbore alta putatorem, circumdata universo corpori, aquam suam adspergentibus, quotiens inaresceret, raroque nec nisi deficientem herbam mutationis causa resolventibus, convaluisse vix credibili celeritate. —", "st": "27.45"}, {"sp": "N", "t": "Cocco Cnidio color cocci, magnitudo grano piperis maior, vis ardens; itaque in pane devoratur, ne adurat gulam transitu. vis praesentanea contra cicutam, sistit alvum.", "st": "27.46"}, {"sp": "N", "t": "Dipsacos folia habet lactucae bullasque spinosas in dorsi medio, caulem II cubitorum iisdem spinis horridum, genicula eius binis foliis amplectentibus concavo alarum sinu, in quo subsistit ros salsus. in cacumine capitula sunt echinata spinis. nascitur in aquosis. sanat rimas sedis, item fistulas decocta in vino radice usque, dum sit crassitudo cerae, ut possit in fistulas collyrium mitti, item verrucas omnium generum. quidam et alarum, quas supra diximus, sucum inlinunt ⟨i⟩is. —", "st": "27.47"}, {"sp": "N", "t": "Dryopteris felici similis in arboribus nascitur, tenui foliorum subdulcium incisura, radice hirsuta. vis ei caustica, et ideo psilotrum est radix tusa, inlinitur enim usque, dum sudores evocet, iterum et tertium ita, ne sudor abluatur.—", "st": "27.48"}, {"sp": "N", "t": "Dra⟨b⟩e phono similis herba est, cauliculis tenuibus, cubitalibus, circumdatis utrimque foliis pollicari amplitudine, qualia oxymyrsines, sed candidioribus mollioribusque, flore candido sabuci. edunt cauliculos decoctos, semine vero eius pro pipere utuntur.", "st": "27.49"}, {"sp": "N", "t": "Elatine folia habet casiae, pusilla, pilosa, rotunda, semipedalibus ramulis quinis senisque, a radice statim foliosis. nascitur in segete, acerba gustu et ideo oculorum fluctionibus efficax foliis cum polenta tritis et inpositis, subdito linteolo. eadem cum lini semine cocta sorbitionis usu dysinteria liberat. —", "st": "27.50"}, {"sp": "N", "t": "Empetros, quam nostri ealcifragam vocant, nascitur in montibus maritimis, fere in saxo. quae propius maria fuit, salsa est potaque trahit bilem ac pituitas; quae longius magisque terrena, amarior sentitur. trahit aquam; sumitur autem in iure aliquo aut in hydromelite. vetustate vires perdit, recens urinas ciet decoctum in aqua vel tritum calculosque frangit. qui fidem promisso huic quaerunt, adfirmant lapillos, qui subfervefiant, una rumpi. —", "st": "27.51"}, {"sp": "N", "t": "Epicactis ab aliis elleborine vocatur, parva herba, exiguis foliis, iocineris vitiis utilissima et contra venena pota.—", "st": "27.52"}, {"sp": "N", "t": "Epimedion caulis est non magnus, hederae foliis denis atque duodenis, numquam florens, radice tenui, nigra, gravi odore ac… in umidis nascitur. et huic spissandi refrigerandique natura, feminis cavenda. folia in vino trita virginum mammas cohibent.—", "st": "27.53"}, {"sp": "N", "t": "Enneaphyllon longa folia novena habet, causticae naturae. inponitur lana circumdatum, ne urat latius—continuo pusulas excitat—, lumborum doloribus et coxendicum utilissimum.", "st": "27.54"}, {"sp": "N", "t": "F⟨e⟩licis duo genera nec florem habent nec semen. pteri⟨m⟩ vocant Graeci, alii blachnon, cuius ex una radice conplures exeunt f⟨e⟩lices bina etiam cubita excedentes longitudine, non graves odore; hanc marem existimant. alterum genus th⟨e⟩lypterim Graeci vocant, alii nymphaea⟨m⟩ pterim; est autem singularis atque non fruticosa, brevior molliorque et densior, foliis ad radicem canaliculata. utriusque radice sues pinguescunt. folia utriusque lateribus pinnata, unde nomen Graeci inposuere. radices utriusque longae in. oblicum, nigrae, praecipue cum inaruere; siccari autem eas sole oportet. nascuntur ubique, sed maxime frigido solo. effodi debent vergiliis occidentibus. usus radicis in trimatu tantum, neque ante nec postea. pellunt interaneorum animalia, ex his t⟨a⟩enias cum melle, cetera ex vino dulci triduo potae, utraque stomacho inutilissima. alvum solvit primo bilem trahens, mox aquam, melius t⟨a⟩enias cum scamonii pari pondere. radix eius pondere II obolorum ex aqua post unius diei abstinentiam bibitur, melle praegustato contra rheumatismos. neutra danda mulieribus, quoniam gravidis abortum, ceteris sterilitatem facit. farina earum ulceribus taetris inspergitur, iumentorum quoque in cervicibus. folia cimicem necant, serpentem non recipiunt; ideo substerni utile est in locis suspectis, usta etiam fugant nidore. fecere medici huius quoque herbae discrimen: optima Macedonica est, secunda Cassiopica.—", "st": "27.55"}, {"sp": "N", "t": "Femur bubulum appellatur herba, nervis et ipsa utilis recens in aceto ac sale trita.", "st": "27.56"}, {"sp": "N", "t": "Gale⟨o⟩psis aut, ut alii, galeobdolon vel gallon caulem et folia habet urticae leviora et quae gravem odorem trita reddant, flore purpureo. nascitur circa saepes ac semitas ubique. folia caulesque duritias et carcinomata ex aceto trita et inposita, item strumas, panos, parotidas discutiunt. ex usu est et decoctae suco fovere. putrescentia quoque et gauigraenas sanat cum sale.—", "st": "27.57"}, {"sp": "N", "t": "Glaux antiquitus eugalacton vocabatur, cytiso et lenticulae foliis similis; aversa candidiora. rami in terra serpunt quini seni, admodum tenues, a radice. flosculi purpurei exeunt. invenitur iuxta mare. coquitur in sorbitione similaginis ad excitandam ubertatem lactis; eam qui hauserint, balineis uti convenit.", "st": "27.58"}, {"sp": "N", "t": "Glaucion in Syria et Parthia nascitur, humilis herba, densis foliis fere papaveris, minoribus tamen sordidioribusque, odoris taetri, gustus amari cum adstrictione. granum habet crocei coloris. hoc in olla fictili luto circumlit⟨a⟩ in clibanis calfaciunt, deinde exempto sucum exprimunt eiusdem nominis. usus et suci et foliorum, si terantur, adversus epiphoras, quae universo impetu cadant. hinc temperatur collyrium, quod medici dia glauci⟨u⟩ vocant.—(lactis quoque ubertas intermissa restituitur; sumitur huius rei causa ex aqua). —", "st": "27.59"}, {"sp": "N", "t": "Glycyside, quam aliqui Paeoniam aut pentorobon vocant, caulem habet II palmorum, comitantibus II aut III, subrutilum, cute lauri, folia qualia isatis, pinguiora rotundioraque et minora, semen in siliquis, aliud grano rubente, aliud nigro. duo autem genera sunt: femina existimatur cuius radicibus ceu balani longiores circiter VIII aut VI adhaerent. mas plures non habet, quoniam una radice nixus est palmi altitudine, candida, quae gustu adstringit. feminae folia murram redolent et densiora sunt. nascuntur in silvis. tradunt nocte effodiendas, quonian interdiu periculosum sit pico Martio inpetum in oculos faciente; radix vero cum effodiatur, periculum esse, ne sedes procidat, magna vanitate ad ostentationem rei fictum arbitror. usus in iis diversus. rubra grana rubentes menses sistunt XV fere pota in vino nigro. nigra grana vulvis medentur ex passo aut vino totidem pota. radix omnes ventris dolores sedat in vino alvumque purgat, sanat opisthotonum, morbum regium, renes, vesicam, arteriam autem et stomachum decocta in vino, alvumque sistit. estur etiamin alimentis, sed in medendo IIII drachmae satis sunt. grana nigra auxiliantur et suppressionibus nocturnis in vino pota quo dictum est numero, stomachicis vero et rosionibus et esse ea et inlinere prodest. suppurationes quoque discutiuntur, recentes nigro semine, veteres rubro. utrumque auxiliatur a serpente percussis et pueris contra calculos incipientes stranguria. —", "st": "27.60"}, {"sp": "N", "t": "Gnaphalium aliqui chamaezelon vocant, cuius foliis albis mollibusque pro tomento utuntur; sane et similia sunt. datur in vino austero ad dysinteriam, ventris solutiones mensesque mulierum sistit. infunditur autem tenesmo. inlinitur et putrescentibus ulcerum.—", "st": "27.61"}, {"sp": "N", "t": "Gallidragam vocat Xenocrates leucacantho similem, palustrem et spinosam, caule ferulaceo, alto, cui summo capite inhaereat simile ovo. in hoc crescente aestate vermiculos nasci tradit, quos pyxide conditos adalligari cum pane bracchio ab ea parte, qua dens doleat, mireque ilico dolorem tolli. valere non diutius anno et ita, si terrain non adtigerint.", "st": "27.62"}, {"sp": "N", "t": "Holcus in saxis nascitur siccis. aristas habet in cacumine, tenui culmo, quale hordeum restibile. haec circa caput alligata vel circa lacertum educit e corpore aristas. quidam ob id aristida vocant.—", "st": "27.63"}, {"sp": "N", "t": "Hyoseris intubo similis, sed minor et tactu asperior, vulneribus contusa praeclare medetur. —", "st": "27.64"}, {"sp": "N", "t": "Holosteon sine duritia est herba, ex adverso appellata a Graecis sicut fel dulce, radice tenuis usque in capillamenti speciem, longitudine IIII digitorum, ceu gramen foliis angustis, adstringens gustu. nascitur in collibus terrenis. usus eius ad vulsa, rupta in vino potae. volnera quoque conglutinat, nam et carnes, dum cocuntur, addita. —", "st": "27.65"}, {"sp": "N", "t": "Hippophaeston nascitur in spinis, ex quibus fiunt aënae fulloniae, sine cauliculo, sine flore, capitulis tantum inanibus et foliis parvis, multis, herbacei coloris. radicula⟨e⟩ alba⟨e⟩, molles. sucus earum exprimitur aestate ad solvendam alvum in obolis, maxime in comitialibus morbis et tremulis, hydropicis, contra vertigines, orthopnoeas, paralysis incipientes. —", "st": "27.66"}, {"sp": "N", "t": "Hypoglossa folia habet figura silvestris myrti, co⟨ma⟩ spinosa, et in his ceu linguas folio parvo exeunte de foliis. capitis dolores corona ex⟨i⟩is inposita minuit.—", "st": "27.67"}, {"sp": "N", "t": "Hypec⟨o⟩on in segetibus nascitur, foliis rutae. natura eius eadem quae papaveris suco.", "st": "27.68"}, {"sp": "N", "t": "Idaeae herbae folia sunt quae oxymyrsines. adh⟨a⟩erent ⟨i⟩is velut pampini, in quibus flos. ipsa alvum mensesque et omnem abundantiam sanguinis sistit spissandi cohibendique natura. —", "st": "27.69"}, {"sp": "N", "t": "Isopyron aliqui phaselion vocant, quoniam folium, quod est aneso simile, in passeoli pampinos torquetur. capitula sunt in summo ca⟨ul⟩e tenuia, plena seminis melanthi, contra tussim et cetera pectoris vitia cum melle aut aqua mulsa, item iocineri utilissim⟨i⟩.", "st": "27.70"}, {"sp": "N", "t": "Lathyris folia habet multa lactucae similia, tenuiora, germina multa, in quibus semen tuniculis continetur, ut capparis, quae cum inaruere, eximuntur grana piperis magnitudine, candida, dulcia, facilia purgatu. haec vicena in aqua pura aut mulsa pota hydropicos sanant; trahunt et bilem. qui vehementius purgari volunt, cum folliculis ipsis sumunt ea, nam stomachum laedunt; itaque inventum est ut cum pisce aut iure gallinacei sumerentur.—", "st": "27.71"}, {"sp": "N", "t": "Leontopetalon alii rapadion vocant, folio brassicae, caule semipedali. alae nu⟨m⟩er⟨o⟩sa⟨e⟩, semen in cacumine in siliqiis ciceris modo, radix rapo similis, grandis, nigra. nascitur in arvis. radix adversatur omni⟨b⟩us serpentium generibus ex vino pota, nec alia res celerius proficit. datur et ischiadicis. —", "st": "27.72"}, {"sp": "N", "t": "Lycapsos longioribus quam lactucae foliis crassioribusque, caul⟨i⟩ long⟨o⟩ hirsutis adgnatis, multis, cubitalibus, flore parvo, purpureo; nascitur in campestribus. inlinitur cum farina hordeacea igni sacro; sudores in febribus movet suco aquae calidae admixto. —", "st": "27.73"}, {"sp": "N", "t": "Inter omnes herbas lithospermo mihil est mirabilius. aliqui exonychon vocant, alii διὸς πυρόν, alii ἡρακλέους. herba quincuncialis fere, foliis duplo maioribus quam rutae, ramulis surculosis, crassitudine iunci. gerit iuxta folia singulas veluti barbulas et in earum cacuminibus lapillos candore et rotunditate margaritarum, magnitudine ciceris, duritia vero lapidea. ipsi, qua pediculis adhaereant, cavernulas habent et intus semen. nascitur et in Italia, sed laudatissimum in Creta, nec quicquam inter herbas maiore equidem miraculo aspexi. tantus est decor velut aurificum arte alternis inter folia candicantibus margaritis, tam exquisita difficultas lapidis ex herba nascentis. iacere atque humi serpere auctores tradunt; ego volsam, non haerentem vidi. his lapillis drachmae pondere potis in vino albo calculos frangi pellique constat et stranguriam discuti. neque in alia herbarum fides est certior, ad quam medicinam nata sit, talis autem eius species, ut etiam sine auctore visu statim nosci possit.—", "st": "27.74"}, {"sp": "N", "t": "Lapis vulgaris iuxta flumina fert muscum siccum, canum. hic fricatur altero lapide addita hominis saliva; illo lapide tangitur inpetigo. qui tangit, dicit:", "st": "27.75"}, {"sp": "N", "t": "φεύγετε κανθαρίδες, λύκος ἄγριος αἷμα διώκει.", "st": "27.75"}, {"sp": "N", "t": "Limeum herba appellatur a Gallis, qua sagittas in venatu tingunt medicamento, quod venenum cervarium vocant. ex hac in III modios salivati additur quantum in unam sagittam addi solet; ita offa demittitur boum faucibus in morbis. alligari postea ad praesepia oportet, donec purgentur—insanire enim solent—; si sudor insequ⟨e⟩tur, aqua frigida perfundi. —", "st": "27.76"}, {"sp": "N", "t": "Leuce Mercuriali similis nomen ex causa accepit, per medium folium candida linea transcurrente, quare mesoleucon quidam vocant. sucus eius fistulas sanat, ipsa contrita carcinomata. fortassis eadem sit quae leucas appellatur, contra marina omnia venena efficax. speciem eius auctores non tradunt nec aliud quam silvestrem latioribus foliis esse, efficaciorem hanc semine acriore.—", "st": "27.77"}, {"sp": "N", "t": "Leucographis qualis esset, scriptum non repperi, quod eo magis miror, quoniam utilis proditur sanguinem excreantibus III obolis cum croco, item coeliacis, trita ex aqua et adposita profluvio feminarum, oculorum quoque medicamentis et explendis ulceribus, quae fiant in teneris partibus.", "st": "27.78"}, {"sp": "N", "t": "Medion folia habet iridis sativae, caulem tripedalem et in eo florem grandem, purpureum, rotundum, semine minuto, radicem semipedalem. in saxis opacis nascitur. radix drachmis II cum melle menses feminarum sistit ecligmate per aliquot dies sumpto. semen quoque in vino contra abundantiam feminarum datur. —", "st": "27.79"}, {"sp": "N", "t": "Myosota sive myosotis levis herba, caulibus pluribus ab una radice, aliquatenus rubentibus, concavis ab imo, foliis angustis, oblongis, dorso acuto, nigris, per intervalla adsidue geminatis, tenuibus cauliculis ex alis prodeuntibus, flore caeruleo. radix digitali crassitudine multis capillamentis fimbriata. vis ei septica et exulceratrix, ideoque aegilopas sanat. tradunt Aegypti, mensis, quem Thoti vocant, die XXVIII fere in Augustum mensem incurrente si quis huius herbae suco inungatur mane, priusquam loquatur, non lippiturum eo anno. —", "st": "27.80"}, {"sp": "N", "t": "Myagros herba ferulacea est, foliis similis rubiae, tripedanea. semen oleosum, quod et fit ex eo. medetur oris ulceribus perunctis hoc suco.", "st": "27.81"}, {"sp": "N", "t": "Herba, quae vocatur nyma, III foliis longis, intubaceis, inlita cicatrices ad colorem reducit.—", "st": "27.82"}, {"sp": "N", "t": "Natrix vocatur herba, cuius radix evulsa virus hirci redolet. hac in Piceno feminis abigunt quos mira persuasione Fatuos vocant; ego species lymphantium hoc modo animorum esse crediderim, quae tali medicamento iuventur.", "st": "27.83"}, {"sp": "N", "t": "Odontitis inter feni genera est, cauliculis densis ab eadem radice, geniculatis, triangulis, nigris. in geniculis folia parva habet, longiora tamen quam polygonum, semen in alis hordeo simile, florem purpureum, pusillum. nascitur in pratis. decoctum cauliculorum eius in vino austero quantum manus capiat dentium dolori medetur ita, ut contineatur ore. —", "st": "27.84"}, {"sp": "N", "t": "Othonna in Syria nascitur, similis erucae perforatis crebro foliis, flore croci; quare quidam anemonen vocaverunt. sucus eius oculorum medicamentis convenit; mordet enim leniter et calefacit adstringitque siccando, purgat cicatrices et nubeculas et quicquid obstet. quidam tradunt lavari atque ita siccatam digeri in pastillos. —", "st": "27.85"}, {"sp": "N", "t": "Onosma longa folia habet fere ad III digitos, in terra iacentia ad similitudinem anchusae, … si⟨m⟩i⟨l⟩is si⟨v⟩e caule si⟨v⟩e flore sive semine. praegnas, si edit eam aut supergradiatur, abortum facere dicitur.—", "st": "27.86"}, {"sp": "N", "t": "Onopradon cum ederunt, asini crepitus reddere dicuntur. trahit urinas et menses, alvum sistit, suppurationes et collectiones discutit. —", "st": "27.87"}, {"sp": "N", "t": "Os⟨y⟩ris ramulos fert nigros, tenues, lentos et in his folia nigra ceu lini semenque in ramulis nigrum initio, dein colore mutato rubescens. smegmata mulieribus faciunt ex⟨i⟩is. radicum decoctum potu sanat arquatos. eaedem, priusquam maturescat semen, concisae et sole siccatae alvum sistunt; post maturitatem vero collectae et in sorbitione decoctae rheumatismis ventris medentur et per se tritae ex aqua caelesti bibuntur. —", "st": "27.88"}, {"sp": "N", "t": "Oxys folia terna habet. datur ad stomachum dissolutum. edunt et qui enterocelen habent.", "st": "27.89"}, {"sp": "N", "t": "polyanthemum, quam quidam batrachion appellant, caustica vi exulcerat, cicatrices et ad colorem reducit, eademque vitiligines concorporat. —", "st": "27.90"}, {"sp": "N", "t": "Polygonum Graeci vocant quam nos sanguinariam. non attollitur a terra foliis rutae similis gramini. sucus eius infusus naribus supprimit sanguinem et potus cum vino cuiuslibet partis profluvium excreationesque cruentas inhibet. qui plura genera polygoni faciunt, hanc marem intellegi volunt appellarique a multitudine seminis aut densitate fruticis, alii po⟨ly⟩gon⟨at⟩on a frequentia geniculorum, alii ⟨t⟩halatt⟨i⟩ada, alii carcinothron, alii clema, multi myrtopetalum. nec non inveniuntur qui hanc feminam esse dicant, marem autem maiorem minusque nigram et geniculis densiorem, semine sub omnibus foliis turgescente. quocumque haec modo se habent, vis earum est spissare ac refrigerare. semine alvum solvunt, largius sumpto urinam cient, rheumatismos cohibent, qui si non fuere, non prosunt. stomachi fervori folia inponuntur, vesicae dolori inlinuntur et ignibus sacris. sucus et auribus purulentis instillatur et oculorum dolori. per se datur et in febribus ante accessiones II cyathis, in tertianis quartanisque praecipue, item cholericis, dysintericis et in solutione stomachi. tertium genus orion vocant, in montibus nascens, harundini tenerae simile, uno caule, densis geniculis et in se infarctis, foliis autem piceae, radicis supervacuae, inefficacius quam superiora, peculiare ischiadicis. quartum genus silvestre appellatur, paene arboris frutice, radice lignosa, stirpe cedri rubicunda, ramis ⟨s⟩parti binum palmorum, nigris geniculorum ternis quaternisque articulis. huic quoque spissandi natura; sapor mali cotonei. decoquitur in aqua ad tertias aut aridi farina inspergitur et oris ulceribus et adtritis partibus. propter gingivarum vero vitia ipsa commanducatur. nomas sistit omniaque, quae serpunt aut difficilem cicatricem habent, privatim vero sanat a nive facta ulcera. herbarii et ad anginas utuntur illa et in capitis dolore coronam ex ea inponunt et contra epiphoras collo circumdant; in tertianis quidem sinistra manu evulsam adalligant, adeo contra profluvia sanguinis, nec ullam magis aridam quam polygonum servant.", "st": "27.91"}, {"sp": "N", "t": "Pancratium aliqui scillam pusillam appellare malunt, foliis albi lilii longioribus crassioribusque, radice bulbi magni, colore rufo. alvum solvit suco cum farina ervi sumpto, ulcera purgat. hydropicis, splenicis cum melle datur. alii decocunt eam, donec aqua dulcis fiat, eaque effusa radicem terentes digerunt in pastillos sole siccatos et postea utuntur ad capitis ulcera et cetera, quae repurganda sint, item ad tussim, quantum III digitis adprehenderint in vino dantes, et ad lateris dolores aut peripneumonicis ecligmate. dant et propter ischiada in vino bibendam et propter tormina mensesque ciendos.—", "st": "27.92"}, {"sp": "N", "t": "Peplis, quam aliqui sycen, alii meconion, alii mecona aphrode vocant, ex una radice tenui fruticat foliis rutae paulo latioribus. sem⟨e⟩n e⟨st⟩ sub foliis, rotund⟨um⟩, minus candido papaver⟨e⟩. inter vites fere colligitur messibus siccaturque cum fructu suo, subiectis in quae excidat. hoc poto alvus solvitur, bilis ac pituita detrahitur. media potio est acetabuli mensura in aquae mulsae heminis III. et cibis inspergitur obsoniisque ad molliendam alvum.—", "st": "27.93"}, {"sp": "N", "t": "Periclymenon fruticat et ipsa ex intervallo II folia habens subcandida, mollia, in cacumine autem semen inter folia durum et quod difficile vellatur. nascitur in arvis ac saepibus ⟨cir⟩cumvolvens se adminiculis quibuscumque. semen eius in umbra siccatum tunditur et in pastillos digeritur; hi resoluti dantur in vini albi cyathis ternis tricenis diebus ad lienem, eumque urina cruentata aut per alvum absumit, quod intellegitur a decimo statim die. urinam cient et folia decocta, quae et orthopnoicis prosunt. partum quoque adiuvant secundasque pellunt pota simili modo. —", "st": "27.94"}, {"sp": "N", "t": "Pelecino⟨n⟩ in segetibus diximus nasci, fruticosam cauliculis, foliis ciceris. semen in siliquis fert corniculorum modo aduncis ternis quaternisve, quale git novimus, amarum, stomacho utile. additur in antidota.—", "st": "27.95"}, {"sp": "N", "t": "Polygala palmu⟨m⟩ altitudine inp⟨l⟩et, in caule summo foliis lenticulae, gustu adstricto. quae pota la⟨c⟩tis abundantiam facit. —", "st": "27.96"}, {"sp": "N", "t": "Poterion aut, ut alii vocant, p⟨h⟩rynion vel neuras large fruticat, spinis retorrida, lanugine spissa, foliis parvis, rotundis, ramulis longis, mollibus, lentis, tenuibus, flore longo, herbacei colors. seminis nullus usus; es⟨t⟩ gustu acuto et odorato. invenitur in aquosis collibus. radices habet II aut III binum cubitorum in altitudinem, nervosas, candidas, firmas. circumfoditur autumno et praecisa r⟨ad⟩ice dat sucum cummi similem. radix mira vulneribus sanandis traditur praecipueque nervis vel praecisis inlita. decoctum quoque eius cum melle potum dissolutiones nervorum et infirmitates et incisuras iuvat.—", "st": "27.97"}, {"sp": "N", "t": "Phalangitis a quibusdam phalangion vocatur, ab aliis leucanthemum vel, ut in quibusdam exemplaribus invenio, leucacantha. ramuli sunt ei numquam pauciores II, in diversa tendentes, flos candidus, lilio rubro similis, semen nigr⟨um⟩, lat⟨um⟩, ad lenticulae dimidiae figuram multo tenui⟨u⟩s, radice tenui, herbacei coloris. huius folio vel flore vel semine auxiliantur contra scorpionum phalangiorumque et serpentium ictus, item contra tormina. —", "st": "27.98"}, {"sp": "N", "t": "Phyteuma quale sit, describere supervacuum habeo, cum sit usus eius tantum ad amatoria.—", "st": "27.99"}, {"sp": "N", "t": "Phyllon a Graecis vocatur herba in saxosis montibus. femina magis herbacei coloris, caule tenui, radice parva. semen papaveri rotundo simile. haec sui sexus facit partus, mares autem ⟨m⟩as, semine tantum differens, quod est incipientis olivae. utrumque bibitur in vino.—", "st": "27.100"}, {"sp": "N", "t": "P⟨h⟩e⟨l⟩landrion nascitur in palustribus folio apii. bibitur semen eius propter calculos et vesicae incommoda.—", "st": "27.101"}, {"sp": "N", "t": "Phaleri⟨s⟩ thyrsum habet longum, tenuem ceu calamum, in summo flore⟨m⟩ inclinatum, semen simile sesamae. et hoc calculos frangit potum ex vino vel aceto vel cum melle et lacte; idem et vitia vesicae sanat.—", "st": "27.102"}, {"sp": "N", "t": "Polyrrhizon folia habet myrti, radices multas. hae tusae dantur e vino contra serpentes, prosunt et quadripedibus. —", "st": "27.103"}, {"sp": "N", "t": "Proserpinaca herba vulgaris est, eximii adversus scorpiones remedii. eadem contrita, addita muria e m⟨e⟩nis et oleo, anginam eximie curari tradunt, praeterea et quantalibet lassitudine recreari defessos, etiam cum obmutuerint, si subiciatur linguae; si devoretur, vomitionem sequi salutarem.", "st": "27.104"}, {"sp": "N", "t": "Rhecoma adfertur ex⟨i⟩is quae supra Pontum sunt regionibus. radix costo nigro similis, minor et rufior paulo, sine odore, calfaciens gustu et adstringens. eadem trita vini colorem reddit ad crocum inclinantem. inlita collectiones inflammationesque sedat, vulnera sanat, epiphoras oculorum sedat ex passo, insignita cum melle et alia liventia ex aceto. farina eius inspergitur contra caco ëthe et sanguinem reicientibus drachmae pondere in aqua, dysintericis autem et coeliacis, si febri careant, in vino, sin aliter, ex aqua. facilius teritur nocte antecedente madefacta. datur et decoctum eius bibendum duplici mensura ad rupta, convolsa, contusis, ex sublimi devolutis. si pectoris sint dolores, additur piperis aliquid et murrae; si dissolutio stomachi, ex frigida aqua sumitur; sic et in tussi vetere ac purulentis excreationibus, item hepaticis, splenicis, ischiadicis. a⟨t⟩ renium vitia, suspiria, orthopnoeas, arteriae scabritias sanat ex passo III obolis potis trita aut decoctum eius. lichenas quoque ex aceto inposita purgat. bibitur contra inflationes et perfrictiones, febres frigidas, singultus, tormina, herpetas, capitis gravitates, melancholicas vertigines, lassitudinum dolores et convolsiones. —", "st": "27.105"}, {"sp": "N", "t": "Circa Ariminum nota est herba quam resedam vocant. discutit collectiones inflammationesque omnes. qui curant ea, addunt haec verba: Reseda, morb⟨o⟩s reseda; scisne, scisne, quis hic pullus egerit radices? nec caput nec pedes habeat. haec ter dicunt totiensque despuunt.", "st": "27.106"}, {"sp": "N", "t": "Stoechas in insulis tantum eiusdem nominis gignitur, odorata herba, coma hysopi, amara gustu. menses ciet potu, pectoris dolores levat. antidotis quoque miscetur. —", "st": "27.107"}, {"sp": "N", "t": "Solanum Graeci στρύχνον vocant, ut tradit Cornelius Celsus. huic vis reprimendi refrigerandique.—", "st": "27.108"}, {"sp": "N", "t": "Smyrnion caulem habet apii, folia latiora et maxime circa stolones multos, quorum a sinu exiliunt, pinguia et ad terram infracta, odore medicato cum quadam acrimonia iucund⟨o⟩, colore in luteum languescente, capitibus caulium orbiculatis ut apii, semine rotundo nigroqu⟨e⟩; arescit incipiente aestate. radix quoque odorata, gustu acri mordet, sucosa, mollis. cortex eius foris niger, intus pallidus. odor murrae habet qualitatem, unde et nomen. nascitur et in saxosis collibus et in terrenis. usus eius calfacere, extenuare. urinam et menses cient folia et radix et semen. alvum sistit. radix collectiones et suppurationes non veteres, item duritias discutit inlita, prodest et contra phalangia ac serpentes admixto cachry aut polio aut melissophyllo in vino pota, sed particulatim, quoniam universitate vomitiones movet; qua de causa aliquando cum ruta datur. medetur tussi et orthopnoeae semen vel radix, item thoracis aut lienis aut renium aut vesicae vitiis, radix autem ruptis, convolsis. partus quoque adiuvat et secundas pellit. datur et ischiadicis cum crethmo in vino. sudores ciet et ructus, ideo inflationem stomachi discutit. vulnera ad cicatricem perducit. exprimitur et sucus radici utilis feminis et thoracis praecordiorumque desideriis, calfacit enim et concoquit et purgat. semen peculiariter hydropicis datur potu⟨i⟩, quibus et sucus inlinitur. et in malagmate cortice arido et ad obsonia utuntur cum mulso et oleo et garo, maxime in elixis carnibus.—Sinon concoctiones facit, sapore simillima piperi. eadem in dolore stomachi efficax.", "st": "27.109"}, {"sp": "N", "t": "Telephion porcilacae similis est et caule et foliis. rami a radice septeni octonique fruticant foliis crassis, carnosis. nascitur in cultis et maxime inter vites. inlinitur lentigini et, cum inaruit, deteritur. inlinitur et vitiligini ternis fere mensibus senis horis noctis aut diei et ut postea farina hordeacia inlinatur. medetur et vulneribus et fistulis.—", "st": "27.110"}, {"sp": "N", "t": "Trichomanes adianto simil⟨e⟩ est, exilius modo nigriusque, foliis lenticulae, densis, ⟨p⟩ar⟨v⟩is, adversis inter se. decoctum eius strangurias sanat in vino albo potum addito cumino rustico, l⟨i⟩en⟨ne⟩m. cohibet capillos fluentes aut, si effluxerint, reparat alopeciasque densat tritum in oleo et inlitum. sternumenta quoque gustatu movet. —", "st": "27.111"}, {"sp": "N", "t": "Thali⟨c⟩trum folia coriandri habet, pinguiora paulo, caulem papaveris. nascitur ubique, praecipue campestribus. medentur ulceribus folia cum melle.—", "st": "27.112"}, {"sp": "N", "t": "Th⟨l⟩aspi duorum generum est: angustis foliis, digitali latitudine et longitudine, in terram versis, in cacumine divisis, cauliculo semipedali non sine ramis, … peltarum specie semine incluso, lenticulae effigie, nisi quod infringitur, unde nomen. flos albicat. nascitur in semitis et saepibus. semen asperi gustus bilem et pituitam utrimque extrahit; modus sumendi acetabuli mensura. prodest et ischiadicis infusum. ⟨poti⟩one sanguinem trah⟨i⟩t, menses quoque ciet, sed partus necat. alterum thlaspi aliqui Persicon nap⟨y⟩ vocant, latis foliis, radicibus magnis, et ipsum utile ischiadicorum infusioni. prodest et inguinibus utrumque. praecipitur, ut qui colligat dicat, sumere se contra inguina et contra omnes collectiones et contra vulnera, una manu tollat.—", "st": "27.113"}, {"sp": "N", "t": "Trachinia herba qualis sit, non traditur. credo falsum et promissum Democriti portentosum ess⟨e⟩, adalligatam triduo absumere lienes.—", "st": "27.114"}, {"sp": "N", "t": "Tragonis sive tragion nascitur in Cretae tantum insulae maritimis, iunipiro similis et semine et folio et ramis. sucus eius lacteus in cummim spissatus vel semen in potione… spicula e corpore eicit; tunditur recens et cum vino inlinitur aut siccae farina cum melle. eadem lactis abundantiam facit mammisque unice medetur. —", "st": "27.115"}, {"sp": "N", "t": "Est et alia herba tragos, quam aliqui scorpion vocant, semipedem alta, fruticosa, sine foliis, pusillis racemis rubentibus grani tritici, acuto ⟨c⟩acumine, et ipsa in maritimis nascens. huius ra⟨ce⟩morum X et XII cacumina trita ex vino pota coeliacis, dysintericis, sanguinem excreantibus mensumque abundantiae auxiliantur.—", "st": "27.116"}, {"sp": "N", "t": "Est et tragopogon, quem alii come⟨n⟩ vocant, caule parvo, foliis croci, radice longa, dulci, super caulem calice lato, nigro. nascitur in asperis manditurque, sine usu.", "st": "27.117"}, {"sp": "N", "t": "Et de herbis quidem memoria digna hactenus accepimus aut comperimus. in fine earum admonere non ab re iudicamus, alias aliis virium aetates esse. longissimo tempore durat elaterium, ut diximus, chamaeleon niger XL annis, centaurium non ultra XII, peucedanum et aristolochia a⟨d⟩VI, vitis silvestris anno, in umbra ⟨si⟩ serventur. et animalium quidem exterorum nullum aliud radices a nobis dictas adtingit excepta sphondyle, quae omnes persequitur. genus id serpentis est.", "st": "27.118"}, {"sp": "N", "t": "Ne illud quidem dubitatur, omnium radicum vim effectusque minui, si fructus prius ematurescant, item seminum ante radice propter sucum incisa. resolvitur autem omnium vis consuetudine, et desinunt prodesse, cum opus est, quae cottidie in usu fuere, aeque quam nocere. omnes vero herbae vehementiores effectu viribusque sunt in frigidis et in aquiloniis, item siccis.", "st": "27.119"}, {"sp": "N", "t": "Sunt et gentium differentiae non mediocres, sicut accipimus de taeniis lumbricisque, inesse Aegypti, Arabiae, Syriae, Ciliciae populis, e diverso ⟨T⟩hreciae, Phrygiae omnino non innasci. minus id mirum quam quod in confinio Atticae et Boeotiae Thebanis innascuntur, cum absint Atheniensibus. quae contemplatio aufert nos ad ipsorum animalium naturas ingenitasque iis vel certiores morborum omnium medicinas. rursus enim⟨cu⟩m re⟨ru⟩m parens nullum animal ad hoc tantum, ut pasceretur aut alia satiaret, nasci voluit artesque salutares inseruit et visceribus, quippe cum surdis etiam rebus insereret, tum vero illa animae auxilia praestantissima ex alia anima esse voluit, contemplatione ante cuncta mirabili.", "st": "27.120"}, {"sp": "HDR", "t": "Liber XXVIII", "st": "28"}, {"sp": "N", "t": "Dictae erant naturae omnium rerum inter caelum ac terram nascentium, restabantque quae ex ipsa tellure fodiuntur, si non herbarum ac fruticum tractata remedia auferrent traversos ex ipsis animalibus, quae sanantur, reperta maiore medicina. quid ergo? dixerimus herbas et florum imagines ac pleraque inventu rara ac difficilia, iidem tacebimus, quid in ipso homine prosit homini, ceteraque genera remediorum inter nos viventia, cum praesertim nisi carenti doloribus morbisque vita ipsa poena fiat? minime vero, omnemque insumemus operam, licet fastidii periculum urgeat, quando ita decretum est, minorem gratiae quam utilitatium vitae respectum habere. quin immo externa quoque et barbaros etiam ritus indagabimus. fides tantum auctores appellet, quamquam et ipsi consensu prope iudicii ista eligere laboravimus potiusque curae rerum quam copiae institimus. illud admonuisse perquam necessarium est dictas iam a nobis naturas animalium et quae cuiusque essent inventa—neque enim minus profuere medicinas reperiendo quam prosunt praebendo—, nune quae in ipsis auxilientur indicari, neque illic in totum omissa; itaque haec esse quidem alia, illis tamen conexa.", "st": "28.1"}, {"sp": "N", "t": "Incipiemus autem ab homine ipsum sibi exquirente, inmensa statim difficultate obvia. sanguinem quoque gladiatorum bibunt, ut viventibus po⟨c⟩ulis, comitiales [morbi], quod spectare facientes in eadem harena feras quoque horror est. at, Hercule, illi ex homine ipso sorbere efficacissimum putant calidum spirantemque et v⟨iv⟩am ipsam anrimam ex osculo vulnerum, cum plagis om⟨nino⟩ ne ferarum quidem admoveri ora mos sit humanus. alii medullas crurum quaerunt et cerebrum infantium. nec pauci apud Graecos singulorum viscerum membrorumque etiam sapores dixere, omnia persecuti ad resigmina unguium, quasi vero sanitas videri possit feram ex homine fieri morboque dignum in ipsa medicina, egregia, Hercules, frustratione, si non prosit. aspici humana exta nefas habetur: quid mandi? quis ista invenit, Ost⟨h⟩ane? tecum enim res erit, eversor iuris humani monstrorumque artifex, qui primus ea condidisti, credo, ne tui vita oblivisceretur. quis invenit singula membra humana mandere? qua coniectura inductus? quam potest medicina ista originem habuisse? quis veneficia innocentiora fecit quam remedia? esto, barbari externique ritus invenerant: etiamne Graeci suas fecere has art⟨e⟩s? extant commentationes Democriti ad aliud noxii hominis ex capite ossa plus prodesse, ad alia amici et hospitis. iam vero vi interempti dente gingivas in dolore scariphari Apollonius efficacissimum scripsit, Meletos oculorum suffusiones felle hominis sanari, Artemon calvaria interfecti neque cremati propinavit aquam e fonte noctu comitialibus morbis. ex eadem suspendio interempti catapotia fecit contra canis rabiosi morsus Antaeus. atque etiam quadrupedes homine sanavere, contra inflationes bou perforatis cornibus inserentes ossa humana, ubi homo occisus esset aut crematus, siliginem, quae pernoctasset, suum morbis dando. procul a nobis nostrisque litteris absint ista. nos auxilia dicemus, non piacula, sicubi lactis puerperarum usus mederi poterit, sicubi saliva tactusve corporis, ceteraque similia. vitamin quidem non adeo expetendam censemus, ut quoquo modo trahenda sit. quisquis es, talis aeque moriere, tamquam obscaenus vixeris aut nefandus. quapropter hoc primum quisque in remediis animi sui habeat, ex omnibus bonis, quae homini tribuit natura, nullum melius esse tempestiva morte, idque in ea optimum, quod illam sibi quisque praestare possit.", "st": "28.2"}, {"sp": "N", "t": "Ex homine remediorum primum maximae quaestionis et semper incertae est, polleantne aliquid verba et incantamenta carminum. quod si verum est, homini acceptum fieri oportere conveniat, sed viritim sapientissimi cuiusque respuit fides, in universum vero omnibus horis credit vita nec sentit. quippe victimas caedi sine precatione non videtur referre aut deos rite consuli. praeterea alia sunt verba inpetritis, alia depulsoriis, alia commen⟨d⟩ationis, videmusque certis precationibus obsecrasse summos magistratus et, ne quod verborum praetereatur aut praeposterum dicatur, de scripto praeire aliquem rursusque alium custodem dari qui adtendat, alium vero praeponi qui favere linguis iubeat, tibicinem canere, ne quid aliud exaudiatur, utraque memoria insigni, quotiens ipsae dirae obstrepentes nocuerint quotiensve precatio erraverit; sic repente extis adimi capita vel corda aut geminari victima stante. durat inmenso exemplo Deciorum patris filiique, quo se devovere, carmen; extat Tucciae Vestalis incesti⟨d⟩eprecatio, qua usa aquam in cribro tulit anno urbis DXVIIII. boario vero in foro Graecum Graecamque defossos aut aliarum gentium, cum quibus tum res esset, etiam nostra aetas vidit. cuius sacri precationem, qua solet praeire XVvirum collegii magister, si quis legat, profecto vim carminum fateatur, omnia ea adprobantibus DCCCXXX annorum eventibus. Vestales nostras hodie credimus nondum egressa urbe mancipia fugitiva retinere in loco precatione, cum, si semel recipiatur ea ratio, et deos preces aliquas exaudire aut ullis moveri verbis, confitendum sit de tota coniectatione.", "st": "28.3"}, {"sp": "N", "t": "Prisci quidem nostri perpetuo talia credidere, difficillimumque ex his, etiam fulmina elici, ut suo loco docuimus.", "st": "28.3"}, {"sp": "N", "t": "L. Piso primo annalium auctor est, Tullum Hostilium regem ex Numae libris eodem, quo illum, sacrificio Iovem caelo devocare conatum, quoniam parum rite quaedam fecisset, fulmine ictum, multi vero magnarum rerum fata et ostenta verbis permutari. cum in Tarpeio fodientes delubro fundamenta caput humanum invenissent, missis ob id ad se legatis Etruriae celeberrimus vates Olenus Calenus, praeclarum id fortunatumque cernens, interrogatione in suam gentem transferre temptavit, scipione determinata prius templi imagine in solo ante se: Hoc ergo dicitis, Romani? hie templum lovis optimi maximi futurum est, hic caput invenimus? constantissima annalium adfirmatione, transiturum fuisse fatum in Etruriam, ni praemoniti a filio vatis legati respondissent: Non plane hic, sed Romae inventum caput dicimus. iterum id accidisse tradunt, cum in fastigium eiusdem delubri praeparatae quadrigae fictiles in fornace crevissent, iterum simili modo retentum augurium.", "st": "28.4"}, {"sp": "N", "t": "Haec satis sint, exemplis ut appareat, ostentorum vires et in nostra potestate esse ac, prout quaeque accepta sint, ita valere. in augurum certe disciplina constat neque diras neque ulla auspicia pertinere ad eos, qui quamque rem ingredientes observare se ea negaverint, quo munere divinae indulgentiae maius nullum est. quid? non et legum ipsaruin in duodecim tabulis verba sunt: qui fruges excantass⟨i⟩t, et alibi: qui malum carmen incantassit? Verrius Flaccus auctores ponit, quibus credat in obpugnationibus ante omnia solitum a Romanis sacerdotibus evocari deum, cuius in tutela id oppidum esset, promittique illi eundem aut ampliorem apud Romanos cultum. et durat in pontificum disciplina id sacrum, constatque ideo occultatum, in cuius dei tutela Roma esset, ne qui hostium simili modo agerent. defigi quidem diris precationibus nemo non metuit. huc pertinet ovorum, quae exorbuerit quisque, calices coclearumque protinus frangi aut isdem coclearibus perforari. hinc Theocriti apud Graecos, Catulli apud nos. proximeque Vergilii incantamentorum amatoria imitatio. multi figlinarum opera rumpi credunt tali modo, non pauci etiam serpentes, ipsas recanere et hunc unum illis esse intellectum, contrahique Marsorum cantu etiam in nocturna quiete. iam parietes incendiorum deprecationibus conscribuntur. neque est facile dictu, externa verba atque ineffabilia abrogent fidem validius ⟨a⟩n Latina e⟨t⟩ inopinata, quae inridicula videri cogit animus semper aliquid inmensum exspectans ac dignum deo movendo, immo vero quod numini imperet. dixit Homerus profluvium sanguinis vulnerato femine Ulixen inhibuisse carmine, Theophrastus ischiadicos sanari, Cato prodidit luxatis membris carmen auxiliare, M. Varro podagris. Caesarem dictatorem post unum ancipitem vehiculi casum ferunt semper, ut primum consedisset, id quod plerosque nunc facere scimus, carmine ter repetito securitatem itinerum aucupari solitum.", "st": "28.4"}, {"sp": "N", "t": "Libet hanc partem singulorum quoque conscientia coarguere. cur enim primum anni incipientis diem laetis precationibus invicem faustum ominalmur? cur publicis lustris etiam nomina victimas ducentium prospera legimus? cur effascinationibus adoratione peculiari occurrimus, alii Graecam Nemesin invocantes, cuius ob id Romae simulacrum in Capitolio est, quamvis Latinum nomen non sit? cur ad mentionem defunctorum testamur, memoriam eorum a nobis non sollicitari? cur inpares numeros ad omnia vehementiores credimus, idque in febribus dierumn observatione intellegitur? cur ad primitias pomorum haec vetera esse dicimus, alia nova optamus? cur sternuentes salutamus? quod etiam Tiberium Caesarem, tristissimum, ut constat, hominum, in vehiculo exegisse tradunt, et aliqui nominec quoque consalutare religiosius putant? quin et absentes tinnitu aurium praesentire sermones de se receptum est. Attalus adfirmat, scorpione viso si quis dicat duo, cohiberi nec vibrare ictus. et quoniam scorpio admonuit, in Africa nemo destinat aliquid nisi praefatus Africam, in ceteris vero gentibus deos ante obtestatus, ut velint. nam si mensa adsit, anulum ponere translatitium videmus, quoniam etiam mutas religiones pollere manifestum est. alius saliva post aurem digito relata sollicitudinem animi propitiat. pollices, cum faveamus, premere etiam proverbio iubemur. in adorando dextram ad osculum referimus totumque corpus circumagimus, quod in laevum fecisse Galliae religiosius credunt. fulgetras poppysmis adorare consensus gentium est. incendia inter epulas nominata aquis sub mensam profusis abominamur. recedente aliquo ab epulis simul verri solum aut bibente conviva mensam vel repositorium tolli inauspicatissimum iudicatur. Servi Sulpicii principis viri commentatio est quamobrem mensa linquenda non sit, nondum enim plures quam convivae numerabantur. nam sternumento revocari ferculum mensamve, si non postea gustetur aliquid, inter diras habetur. … aut omnino inane esse? haec instituere illi, qui omnibus negotiis horisque interesse credebant deos et ideo placatos etiam vitiis nostris reliquerunt. quin et repente conticescere convivium adnotatum, set non nisi in pari praesentium numero, isque famae labor est ad quemcumque eorum pertinens. cibus etiam e manu prolapsus reddebatur utique per mensas, vetabantque munditiarum causa deflare, et sunt condita auguria, quid loquenti cogitantive id acciderit, inter execratissima, si pontifici accidat dicis causa epulanti. in mensa utique id reponi adolerique ad Larem piatio est. medicamenta, priusquam adhibeantur, in mensa forte deposita negant prodesse. ungues resecari nundinis Romanis tacenti atque a digito indice multorum pe⟨rs⟩u⟨as⟩i⟨o⟩ne religiosum est, capillum vero contra defluvia ac dolores capitis XVII luna atque XXVIIII. pagana lege in plerisque Italiae praediis cavetur, ne mulieres per itinera ambulantes torqueant fusos aut omnino detectos ferant, quoniam adversetur id omnium spei, praecipue frugum. M. Servilius Nonianus princeps civitatis non pridem in metu lippitudinis, priusquam ipse eam nominaret aliusve ei praediceret, duabus litteris Graecis PA chartam inscriptam circumligatam lino subnectebat collo, Mucianus ter consul eadem observatione viventem muscam in linteolo albo, his remediis carere ipsos lippitudine praedicantes. carmina quidem extant contra grandines contraque morborum genera contraque ambusta, quaedam etiam experta, sed prodendo obstat ingens verecundia in tanta animorum varietate. quapropter de iis ut cuique libitum fuerit opinetur.", "st": "28.5"}, {"sp": "N", "t": "Hominum monstrificas naturas et veneficos aspectus diximus in portentis gentium et multas animalium proprietates, quae repeti supervacuum est. quorundam hominum tota corpora prosunt, ut ex⟨i⟩is familiis, quae sunt terrori serpentibus, tactu ipso levant percussos suctuve modo, quorum e genere sunt Psylli Marsique et qui Ophiogenes vocantur in insula Cypro, ex qua familia legatus Euagon nomine a consulibus Romae in dolium serpentium coniectus experimenti causa circummulcentibus linguis miraculum praebuit. signum eius familiae est, si modo adhuc durat, vernis temporibus odoris virus. atque eorum sudor quoque medebatur, non modo saliva. nam in insula Nili Tentyri nascentes tanto sunt crocodilis terrori, ut vocem quoque eorum fugiant, horum omniumn generum ins⟨it⟩a repugnantia interventum quoque mederi constat, sicuti adgravari vulnera introitu eorum, qui umquam fuerint serpentium canisve dente laesi. iidem gallinarum incubitus, pecorum fetus abortu vitiant; tantum remanet virus ex accepto semel malo, ut venefici fiant venena passi. remedio est ablui prius manus eorum aquaque illa eos, quibus medearis, inspergi. rursus a scorpione aliquando percussi numquam postea a crabronibus, vespis apibusve feriuntur. minus miretur hoc qui sciat, vestem a tineis non attingi, quae fuerit in funere, serpentes aegre praeterquam laeva manu extrahi.", "st": "28.6"}, {"sp": "N", "t": "e Pythagorae inventis non temere fallere, inpositivorum nominum inparem vocalium numerum clauditates oculive orbitatem ac similes casus dextris adsignare partibus, parem laevis. ferunt difficiles partus statim solvi, cum quis tectum, in quo sit gravida, transmiserit lapide vel missili ex⟨i⟩is, qui III animalia singulis ictibus interfecerint, hominem, aprum, ursum. probabilius id facit hasta velitaris evulsa corpori hominis, si terrain non attigerit; eosdem enim inlata effectus habet. sic et sagittas corpori eductas, si terrain non attigerint, subiectas cubantibus amatorium esse Orpheus et Archelaus scribunt, quin et comitialem morbu⟨m⟩ sanari cibo e care ferae occisae eodem ferro, quo homo interfectus sit. quorundam partes medicae sunt, sicuti diximus de Pyrrhi regis pollice, et Elide solebat ostendi Pelopis os ⟨u⟩lnamqu⟨e⟩⟨e⟩am eburneam adfirmabant.—(Naevos in facie tondere religiosum habent etiam nunc multi).—", "st": "28.6"}, {"sp": "N", "t": "Omninum vero in primis ieiunam salivam contra serpentes praesidio esse docuimus, sed et alios efficaces eius usus recognoscat vita. despuimus comitiales morbos, hoc est contagia regerimus. simili modo et fascinationes repercutimus dextraeque clauditatis occursum. veniam quoque a deis spei alicuius audacioris petimus in sinum spuendo, et iam eadem ratione terna despuere precatione in omni medicina mos est atque ita effectus adiuvare, incipientes furunculos ter praesignare ieiuna saliva. mirum dicimus, sed experimento facile: si quem paeniteat ictus eminus comminusve inlati et statim expuat in mediam manum qua percussit, levatur ilico in percusso culpa. hoc saepe delumbata quadrupede adprobatur statim a tali remedio correcto animalis ingressu. quidam vero adgravant ictus ante conatum simili modo saliva in manu⟨m⟩ ingesta. credamus ergo et lichenas leprasque ieiunae inlitu adsiduo arceri; item lippitudines matutina cottidie velut inunctione, carcinomata malo terrae subacto, cervicis dolores saliva ieiuni dextra manu ad dextrum poplitem relata, laeva ad sinistrum; si quod animal aurem intraverit et inspuatur, exire. inter amuleta est editae quemque urinae inspuere, similiter in calciamentum dextri pedis, priusquam induatur, item cum quis transeat locum, in quo aliquod periculum adierit. Marcion Zmyrnaeus, qui de simplicibus effectibus scripsit, rumpi scolopendras marinas sputo tradit, item rubetas aliasque ranas, Ofilius serpentes, si quis in hiatum earum expuat, Salpe torporem sedari quocumque membro stupente, si quis in sinum expuat aut si superiores palpebras saliva tangat.⟨c⟩ur no⟨n⟩et haec credamus rite fieri, extranei interventu aut, si dormiens spectetur infans, a nutrice terna adspui i⟨n⟩ os? quamquam religione ⟨e⟩um ⟨t⟩utatur et fascinus, imperatorum quoque, non solum infantium, custos, qui deus inter sacra Romana a Vestalibus colitur, et currus triumphantium, sub his pendens, defendit medicus invidiae, iubetque eosdem re⟨s⟩picere similis medicina linguae, ut sit exorata a tergo Fortuna gloriae carnifex.", "st": "28.7"}, {"sp": "N", "t": "Morsus hominis inter asperrimos quosque numeratur. medentur sordes ex auribus ac, ne quis miretur, et scorpionum ictibus serpentiumque statim inpositae, melius e percussi auribus. produnt ita et reduvias sanari, serpentium vero ictum contusi dentis humani farina.", "st": "28.8"}, {"sp": "N", "t": "Capillus puero qui primum decisus est, podagrae inpetus dicitur levare circumligatus; et in totum inpubium inpositu⟨s⟩, virorum quoque, capillus canis morsibus medetur ex aceto et capitum volneribus ex oleo aut vino; si credimus, ⟨e⟩ revulso cruci quartanis, conbustus utique capillus carcinomati. pueri qui primus ceciderit dens, ut terram non attingat, inclusus in armillam et adsidue in bracchio habitus muliebrium locorum dolores prohibet. —Pollex in pede praeligatus proximo digito tumores inguinum sedat, in manu dextera II medii lino leviter colligati destillationes atque lippitudines arcent. quin et eiectus lapillus calculoso alligatusque supra pubem levare ceteros dicitur ac iocineris etiam dolores et celeritatem partus facere; adi⟨c⟩it Gran⟨i⟩us efficaciorem ad hoc esse ferro exemptum. partus accelerat e⟨t⟩ m⟨a⟩s, ex quo quaeque conceperit, si cinctu suo soluto feminam cinxerit, dein solverit adiecta precatione, e⟨t c⟩inxisse eundem et soluturum, atque abierit.", "st": "28.9"}, {"sp": "N", "t": "Sanguine ipsius hominis ex quacumque parte emisso efficacissime anginam inlini tradunt Orpheus et Archelaus, item ora comitiali morbo conlapsorum, exurger ⟨e⟩ enim protinus; quidam, si pollices pedum pungantur eaeque guttae referantur in faciem, aut si virgo dextro pollice attingat, hac coniectura censentes virgines carnes edendas. —Aeschines Atheniensis excrementorum cinere anginis medebatur et tonsillis uvisque et carcinomatis. hoc medicamentum vocabat botryon.— Multa genera morborum primo coitu solvuntur primoque feminarum mense aut, si hoc non contigit, longinqua fiunt, maximeque comitiales. quin et a serpente, a scorpione percussos coitu levari produnt, verum feminas venere ea laedi.—Oculorum vitia fieri negant nec lippire eos, qui, cum pedes lavent, aqua inde ter oculos tangant.", "st": "28.10"}, {"sp": "N", "t": "Inmatura morte raptorum manu strumas, parotidas, guttura tactu sanari adfirmant, quidam vero cuiuscumque defuncti, dumtaxat sui sexus, laeva manu aversa. et ligno fulgure icto reiectis post terga manibus demorderi aliquid et ad dentem, qui doleat, admoveri remedio esse produnt. sunt qui praecipiant dentem suffiri dente hominis sui sexus et eum, qui caninus vocetur, insepulto exemptum adalligari. —Terram e calvaria psilotrum esse palpebrarum tradunt, herba vero, si qua ibi genita sit, commanducata dentes cadere, ulcera non serpere osse hominis circumscripta. alii e tribus puteis pari mensura aquas miscent et prolibant novo fictili, relicum dant in tertianis accessu febrium bibendum. iidem in quartanis fragmentum clavi a cruce involutum lana collo subnectunt aut spartum e cruce, liberatoque condunt caverna, quam sol non attingat.", "st": "28.11"}, {"sp": "N", "t": "Magorum haec commenta sunt, ut cotem, qua ferramenta saepe exacuta sint, subiectam ignari cervicalibus de veneficio deficientis evocare indicium, ut ipse dicat, quid sibi datum sit et ubi et quo tempore, auctorem tamen non nominare. fulmine utique percuss⟨um⟩ circumactum in vulnus hominem loqui protinus constat. inguinibus medentur aliqui liceum telae detractum alligantes novenis septenisve nodis, ad singulos nominantes viduam aliquam atque ita inguini adalligantes. liceo et clavum aliudve, quod quis calcaverit, alligatum ipsos iubent gerere, ne sit dolori vulnus. verrucas abolent a vicensima luna in limitibus supini ipsam intuentes ultra caput manibus porrectis et, quicquid adprehendere, eo fricantes. clavum corporis, cum cadit stella, si quis destringat, vel cito sanari aiunt, cardinibus ostiorum aceto adfusis lutum fronti inlitum capitis dolorem sedare, item laqueum suspendiosi circumdatum temporibus. si quid e pisce haeseritin faucibus, cadere demissis in aquam frigidam pedibus; si vero ex aliis ossibus, inpositis capiti ex eodem vase ossiculis; si panis haereat, ex eodem in utramque aurem addito pane.", "st": "28.12"}, {"sp": "N", "t": "Quin et sordes hominis in magnis fecere remediis quaestus gymni⟨ci⟩ Graecorum, quippe ea strigmenta molliunt, calfaciunt, discutiunt, conplent, sudore et oleo medicinam facientibus. volvis inflammatis contractisque admoventur; sic et menses cient, sedis inflammationes et condylomata leniunt, item nervorum dolores, luxata, articulorum nodos. efficaciora ad eadem strigmenta a balneis, et ideo miscentur suppuratoriis medicamentis. nam illa, quae sunt e ceromate permixta c⟨a⟩eno, articulos tantum molliunt, calfaciunt, discutiunt efficacius, sed ad cetera minus valent. excedit fidem inpudens cura, qua sordes virilitatis contra scorpionum ictus singularis remedii celeberrimi auctores clamant, rursus in feminis qua infantium alvo editas in utero ipso contra sterilitatem subdi censent; meconium vocant. immo etiam ipsos gymnasiorum rasere parieles, et illae quoque sordes excalfactoriam vim habere dicuntur; panos discutiunt, ulceribus senum puerorumque et desquamatis ambustisve inlinuntur.", "st": "28.13"}, {"sp": "N", "t": "Eo minus omitti convenit ab animo hominis pendentes medicinas. abstinere se cibo omni au potu, alias vino tantum aut carne, alias balneis, cumquid eorum postulet valetudo, in praesentissimis remediis habetur. his adnumeratur exercitatio, intentio vocis, ungui, fricari cum ratione; vehemens enim fricatio spissat, lenis mollit, multa adimit corpus, auget modica. in primis vero prodest ambulatio, gestatio et ea pluribus modis, equitatio stomacho et coxis utilissima, p⟨h⟩thisi navigatio, longis morbis locorum mutatio, item somno sibi mederi aut lectulo et rara vomitione. supini cubitus oculis conducunt, at proni tussibus, in latera adversus destillationes. Aristoteles et Fabianus plurimum somniari circa ver et autumnum tradunt, magisque supino cubitu, at prono nihil, Theophrastus celerius concoqui dextri lateris incubitu, difficilius a supinis. sol quoque, remediorum maximum, ab ipso sibi praestari potest, sicuti linteorum strigiliumque vehementia. perfundere caput calida ante balnearum vaporationem et postea frigida saluberrimum intellegitur; item praesumere cibis et interponere frigidam eiusdemque potu somnos antecedere et, si libeat, interrumpere. notandum nullum animal aliud calidos potus sequi, ideoque non esse naturales. mero ante somnos colluere ora propter halitus, frigida matutinis inpari numero ad cavendos dentium dolores, item posca oculos contra lippitudines certa experimenta sunt,", "st": "28.14"}, {"sp": "N", "t": "sicut totius corporis valetudini in varietate victus inobservata. Hippocrates tradit non prandentium celerius senescere exta; verum id remediis cecinit, non epulis, quippe multo utilissima est temperantia in cibis. L. Lucullus hanc de se praefecturam servo dederat, ultimoque probro manus in cibis triumphali seni deiciebatur vel in Capitolio epulanti, pudenda re servo suo facilius parere quam sibi.", "st": "28.14"}, {"sp": "N", "t": "Sternumenta pinna gravedinem emendant et si quis mu⟨l⟩ae nares, ut tradunt, osculo attingat, sternumenta et singultum. ad hoc Varro suadet palmam alterna manu scalpere; plerique anulum e sinistra in longissimum dextrae digitum transferre, in aquam ferventem manus mergere. Theophrastus senes laboriosius sternuere dicit.", "st": "28.15"}, {"sp": "N", "t": "Venerem damnavit Democritus, ut in qua homo alius exiliret ex homine. et, Hercules, raritas eius utilior. athletae tamen torpentes restituuntur venere, vox revocatur, cum e candida declinat in fuscam. medetur et lumborum dolori, oculorum hebetationi, mente captis ac melancholicis.", "st": "28.16"}, {"sp": "N", "t": "Adsidere gravidis vel, cum remedia alicui adhibeantur, digitis pectinatim inter se inplexis veneficium est, idque conpertum tradunt Alcmena Herculem pariente; peius, si circa unum ambove genua; item poplites alternis genibus inponi. ideo haec in consiliis ducum potestatiumve fieri vetuere maiores velut omnem actum inpedientia, vetuere vero et sacris votisve simili modo interesse; capita autem aperiri aspectu magistratuum non venerationis causa iussere, sed, ut Varro auctor est, valetudinis, quoniam firmiora consuetudine ea fierent.—Cum quid oculo inciderit, alterum conprimi prodest, cum aqua dextrae auriculae, sinistro pede exultari capite in dextrum umerum devexo, invicem e diversa aure; si tussim concitet saliva, in frontem ab alio adflari; si iaceat uva, verticem morsu alterius suspendi; in cervicium dolore poplites fricar⟨i⟩ aut cervicem in poplitum; pedes in humo deponi, si nervi in his cruribusve tendantur in lectulo, aut, si in laeva parte id accidat, sinistrae plantae pollicem dextra manu adprehendi, item e diverso; extremitates corporis velleribus perstringi contra horrores sanguinemve narium inmodicum, … lino vel papyro principia genitalium, femur medium ad cohibenda urinae profluvia; in stomachi solutione pedes pressari aut manus in ferventem aquam demitti.—Iam et sermoni parci multis de causis salutare est. triennio Maecenatem Melissum accepimus silentium sibi imperavisse a convolsione reddito sanguine. nam eversos scandentesque ac iacentes si quid ingruat contraque ictus spiritum cohibere singularis praesidii est, quod inventum esse animalis docuimus. —Clavum ferreum defigere in quo loco primum caput fixerit corruens morbo comitiali, absolutorium eius mali dicitur. contra renium aut lumborum, vesicae cruciatus in balnearum soliis pronos urinam reddere mitigatorium habetur.—Vulnera nodo Herculis praeligare mirum quantum ocior medicina est, atque etiam cottidiani cinctus tali nodo vim quandam habere utilem dicuntur, quippe cum Herculaneum prodiderit numerum quoque quaternarium Demetrius condito volumine et quare quaterni cyathi sextariive non essent potandi. contra lippitudines retro aures fricare prodest et lacrimosis oculis frontem.—Augurium ex homine ipso est non timendi mortem in aegritudine, quamdiu oculorum pupillae imaginem reddant.", "st": "28.17"}, {"sp": "N", "t": "Magna et urinae non ratio solum, sed etiam religio apud auctores invenitur digestae in genera, spadonum quoque ad fecunditatis veneficia. verum ex⟨i⟩is, quae referre fas sit, inpubium puerorum contra salivas aspidum, quas ptyadas vocant, quoniam venena in oculos hominum expuant, contra oculorum albugines, obscuritates, cicatrices, to argema, palpebras et cum ervi farina contra adustiones, contra aurium pura vermiculosque, si decoquatur ad dimidias partes cum porro capitato novo fictili. vaporatio quoque ea menses feminarum ciet. Salpe fovet illa cum … oculos firmitatis causa, inlinit sole usta cum ovi albo, efficacius struthocameli, binis horis. hac et atramenti liturae abluuntur. virilis podagris medetur argumento fullonum, quos ideo temptari eo morbo negant. veteri miscetur cinis ostreorum adversus eruptiones in corpore infantium et omnia ulcera manantia. ea exesis, ambustis, sedis vitiis, rhagadiis et scorpionum ictibus inlinitur. obstetricum nobilitas non alio suco efficacius curari pronuntiavit corporum pruritus, nitro addito ulcera capitum, porrigines, nomas, praecipue genitalium. sua cuique autem, quod fas sit dixisse, maxime prodest, confestim perfuso canis morsu, echinorumque spinis inhaerentibus et in spongea lanisve inposita, aut adversus rabidi canis morsus cinere ex ea subacto, contraque serpentium ictus. nam contra scolopendras mirum proditur vertice tacto urinae suae gutta liberari protinus laesos. —", "st": "28.18"}, {"sp": "N", "t": "Auguria valetudinis ex ea traduntur, si mane candida, dein rufa sit; illo modo concoquere, hoc concoxisse significatur. mala signa rubrae, pessima nigrae, mala bullantis. crassa, in qua quod subsidit album est, significat circa articulos aut viscera dolorem inminere; eadem viridis morbum viscerum, pallida bilis, rubens sanguinis. mala et in qua veluti furfures atque nubeculae apparent. diluta quoque alba vitiosa est, mortifera vero crassa gravi odore et in pueris tennis ac diluta.—Magi vetant eius causa contra solem lunamque nudari aut umbram cuiusquam ab ipso respergi. Hesiodus iuxta obstantia reddi suadet, ne deum aliquem nudatio offendat. Osthanes contra mala medicamenta omnia auxiliari promisit mnatutinis suam cuique instillatam in pedem.", "st": "28.19"}, {"sp": "N", "t": "Quae ex mulierum corporibus traduntur, ad portentorum miracula accedunt, ut sileamus divisa membratim scelera abortus, mensum piacula quaeque alia non obstetrices modo, verum etiam ipsae meretrices prodidere: capilli si crementur, odore serpentes fugari; eodem nidore vulvae morbo strangulatas respirare; cinere eo quidem, si in testa sint cremati vel cum spuma argenti, scabritias oculorum ac prurigines emendari, item verrucas et infantium ulcera, cum melle capitis quoque vulnera et omnium ulcerum sinus, addito melle ac ture panos, podagras, cum adipe suillo sacrum ignem, sanguinem sisti inlito, ite⟨m⟩ formicationes corporum.", "st": "28.20"}, {"sp": "N", "t": "De lactis usu convenit dulcissimum esse mollissimumque et in longa febr⟨i⟩ coeliacisque utilissimum, maxime eius, quae iam infantem removerit. et in malacia stomachi, in febribus, rosionibus efficacissimum experiuntur; item mammarum collectionibus cum ture, oculo ab ictu cruore suffuso et in dolore aut epiphora, si inmulgeatur, plurimum prodest, magisque cum melle et narcissi suco aut turis polline, superque in omni usu efficacius eius, quae marem enixa sit, multoque efficacissimum eius, quae geminos mares, et si vino ipsa cibisque acrioribus abstineat. mixto praeterea ovorum candido liquore madidaque lana frontibus inpositum fluctiones oculorum suspendit. ⟨eti⟩am si rana saliva sua oculum asperserit, praecipuum est remedium, et contra morsum eiusdem bibitur instillaturque. eum, qui simul matris filiaeque lacte inunctus sit, liberari omni oculorum metu in totam vitam adfirmant. aurium quoque vitiis medetur admixto modice oleo aut, si ab ictu doleant, anserino adipe tepefactum. si sit odor gravior, ut plerunmque fit longis vitiis, diluto melle lana includitur. et contra regium morbum in oculis relictum instillatur cum elaterio. peculiariter valet potum contra venena, quae data sint e marino lepore, bupresti⟨a⟩ut ⟨e⟩tiam, ut Aristoteles tradit, dorycni⟨o⟩, et contra insaniam, quae facta sit hyoscyami potu. podagris quoque iubent inlini cum cicuta, alii cum oesypo et adipe anserino, qualiter et vulvarum doloribus inponitur. alvum etiam sistit potu, ut Rabirius scribit, et menses ciet. eius vero, quae feminam enixa sit, ad vitia tantum in facie sananda praevalet. pulmonum quoque incommoda lacte mulieris sanantur; cui si admisceatur inpubis pueri urina et mel Atticum, omnia coclearium singulorum mensura, ⟨ve⟩rm⟨es⟩ quoque aurium eici invenio. eius, quae marem peper⟨er⟩it, lacte gustato canes rabiosos negant fieri.", "st": "28.21"}, {"sp": "N", "t": "Mulieris quoque salivam ieiunam potentem diiudicant cruentatis oculis et contra epiphoras, si ferventes anguli oculorum subinde madefiant, efficacius, si cibo vinoque se pridie ea abstinuerit. invenio et fascia mulieris alligato capite dolores minui.", "st": "28.22"}, {"sp": "N", "t": "post haec nullus est modus. iam primum abigi grandines turbinesque contra fulgura ipsa mense nudato; sic averti violentiam caeli, in navigando quidem tempestates etiam sine menstruis. ex ipsis vero mensibus, monstrificis alias, ut suo loco indicavimus, dira et infanda vaticinantur, e quibus dixisse non pudeat, si in defectus lunae solisve congruat⟨v⟩is illa, inremediabilem fieri, non segnius et in silente luna, coitusque tum maribus exitiales esse atque pestiferos, purpuram quoque eo tempore ab ⟨i⟩is pollui; tanto vim esse maiorem. quocumque autem alio menstruo si nudatae segetem ambiant, urucas et vermiculos scarabaeosque ac noxia alia decidere Metrodorus Scepsius in Cappadocia inventum prodit ob multitudinem cantharidum; ire ergo per media arva retectis super dunes vestibus. alibi servatur, ut nudis pedibus eant capillo cinctuque dissoluto. cavendum ne id oriente sole faciant, sementiva enim arescere, item novella tactu in perpetuum l⟨a⟩edi, rutam et⟨h⟩ederam, res medicatissimas, ilico mori. multa diximus de hac violentia, sed praeter illa certum est, apes tactis alvariis fugere; lina, cum coquantur, nigrescere; aciem in cultris tonsorum hebetari; aes contactu grave virus odoris accipere et aeruginem, magis si decrescente luna id accidat; equas, si sint gravidae, tactas abortum pati, quin et aspectu omnino, quamvis procul visas, si purgatio illa post virginitatem prima sit aut in virgine aetatis sponte manet. bitumen in Iudaea nascens sola hac vi superari filo vestis contactae docuimus. ne igni quidem vincitur, quo cuncta, cinisque etiam ille, si quis aspergat lavandis vestibus, purpuras mutat, florem coloribus adimit, ne ipsis quidem feminis malo suo inter se inmunibus: abortus facit inlitu aut si omnino praegnas supergradiatur. quae Lais et Elephantis inter se contraria prodidere de abortiv⟨o⟩ carbone e radice brassicae vel myrti vel tamaricis in eo sanguine extincto, itemque asinas tot annis non concipere, quot grana hordei contacta ederint, quaeque alia nuncupavere monstrifica aut inter ipsa pugnantia, cum haec fecunditatem fieri isdem modis, quibus sterilitatem illa, praenuntiaret, melius est non credere. Bithus Durrachinus hebetata aspectu specula recipere nitorem tradit isdem aversa rursus contuentibus, omnemque vim talem resolvi, si mullum piscem secum habeant; multi vero inesse etiam remedia tanto malo: podagris inlini, strumas et parotidas et panos, sacros ignes, furunculos, epiphoras tractatu mulierum earum leniri; Lais et Salpe canum rabiosorum morsus et tertianas quartanasque febres menstruo in lana arietis nigri argenteo bracchiali incluso, Diotimus Thebanus vel omnino vestis ita infectae portiuncula ac vel licio bracchiali inserto. Sotira obstetrix tertianis quartanisque efficacissimum dixit plantas aegri subterlini, multoque efficacius ab ipsa muliere et ignorantis; sic et comitiales excitari. Icatidas medicus quartanas finiri coitu, incipientibus dumtaxat menstruis, spopondit. inter omnes vero convenit, si aqua potusque formidetur a morsu canis, supposita tantum calici lacinia tali statim metum eum discuti, videlicet praevalente sympathia illa Graecorum, cum rabiem canum eius sanguinis gustatu incipere dixerimus. cinere eo iumentorum omni⟨a⟩ ulcera sanar certum est addita caminorum farina et cera, maculas autem e veste eas non nisi eiusdem urina ablui, cinerem per se rosaceo mixtum feminarum praecipue capitis dolores sedare inlitum fronti, asperrimamque vim profluvii eius esse per se annis virginitate resoluta. id quoque convenit, quo nihil equidem libentius crediderim, tactis omnino menstruo postibus inritas fieri Magorum artes, generis vanissimi, ut aestimare licet. ponam enim vel modestissimum e promissis eorum, ex homine siquidem resigmina unguium e pedibus manibusque cera permixta ita, ut dicatur tertianae, quartanae vel cotidianae febri remedium quaeri, ante solis ortum alienae ianuae adfigi iubent ad remedia in his morbis, quanta vanitate, si falsum est, quanta vero noxia, si transferunt morbos! innocentioires ex his omnium digitorum resigmina unguium ad cavernas formicarum abici iubent eamque, quae prima coeperit trahere, correptam subnecti collo; ita discuti morbum.", "st": "28.23"}, {"sp": "N", "t": "Haec sunt quae retulisse fas sit, ac pleraque ex⟨i⟩is non nisi honore dicto, reliqua intestabilia, infanda, ut festinet oratio ab homine fugere. in ceteris claritates animalium aut operum sequemur.", "st": "28.24"}, {"sp": "N", "t": "Elephanti sanguis, praecipue maris, fluctiones omnes, quas rheumatismos vocant, sistit. ramentis eboris cum melle Attico, ut aiunt, nubeculae in facie, scobe paronychia tolluntur. proboscidis tactu capitis dolor levatur, efficacius si et sternuat. dextra pars proboscidis cum Lemnia rubrica adalligata inpetus libidinum stimulat. sanguis et syntecticis prodest, iocurque comitialibus morbis.", "st": "28.24"}, {"sp": "N", "t": "Leonis adipes cum rosaceo cutem in facie custodiunt a vitiis candoremque; sanant et adusta nivibus articulorumque tumores. Magorum vanitas perunctis adipe eo faciliorem gratiam apud populos regesve promittit, praecipue tamen eo pingui, quod sit inter supercilia, ubi esse nullum potest. similia dentis, maxime a dextera parte, villique e rostro inferiore promissa sunt. fel aqua addita claritatem oculis inunctis facit et cum adipe eiusdem comitiales morbos discutit levi gustu et ut protinus qui sumpsere cursu id digerant. cor in cibo sumptum quartanis medetur; adips cum rosaceo cotidianis febribus. perunctos eo bestiae fugiunt; resistere etiam insidiis videtur.", "st": "28.25"}, {"sp": "N", "t": "Cameli cerebrum arefactum potumque ex aceto comitialibus morbis aiunt mederi, item fel cum melle potum, hoc et anginae; cauda arefacta solvi alvum, fimi cinere crispari capillum cam oleo. et dysintericis prodest inlitus cinis potusque, quantum III digitis capiatur, et comitialibus morbis. urinam fullonibus utilissimam esse tradunt, itemque ulceribus manantibus barbaros servare eam quinquennio et heminis pota ciere alvum; saetas e cauda contortas et sinistro bracchio alligatas quartanis mederi.", "st": "28.26"}, {"sp": "N", "t": "Hyaenam Magi ex omnibus animalibus in maxima admiratione posuerunt, utpote cui et ipsi magicas artes dederint vimque, qua alliciat ad se homines mentes alienans. permutationes sexus annua vice diximus ceteraque monstrifica naturae eius; nune persequemur quaecumque medicinis produntur. praecipue pantheris terrori esse traditur, ut ne conentur quidem resistere, et aliquid e corio eius habentem non adpeti, mirumque dictu, si pelles utriusque contrariae suspendantur, decidere pilos pantherae. cum fugiant venantem, declinare ad dexteram, ut praegressi hominis vestigia occupent; quod si successerit, alienari mentem ac vel ex equo hominem decidere; ⟨a⟩t si in laeva detorserit, deficientis argumentum esse celeremque capturam, facilius autem capi, si cinctus suos venator flagellumque inperitans equo septenis alligaverit nodis. mox, ut est sollers ambagibus vanitas Magorum, capi iubent geminorum signum transeunte luna singulosque prope pilos servari; capitis dolori inligatam cutem prodesse, quae fuerit in capite eius; lippitudini fel inlitum frontibus aut, ne omnino lippiatur, decoctum cum mellis Attici cyathis III et croci uncia inunctum; sic et caligines discuti et suffusiones; claritatem excitari melius inveterato medicamento, adservari autem in Cypria pyxide; eodem sanari argema, scabritias, excrescentia in oculis, item cicatrices, glaucomata vero iocineris recentis inassati sanie cum despumato melle inunctis. dentes eius dentium doloribus tactu prodesse vel alligatos⟨n⟩umeri ordine, umerorum et lacertorum doloribus; eiusdem dentes, sed e sinistra parte rostri, inligatos pecoris aut capri pelle stomachi cruciatibus; pulmones in cibo sumptos coeliacis vel ventriculi cinerem cum oleo inlitum; nervis medullas e dorso cum oleo vetere ac felle; febribus quartanis iocur degustatum ter ante accessiones; podagris spinae cinerem cum lingua et dextro pede vituli marini addito felle taurino, omnia pariter cocta atque inlita hyaenae pelle; in eodem morbo prodesse et fel cum lapide Assio; tremulis, spasticis, exilientibus et quibus cor palpitet aliquid ex corde coctum mandendum ita, ut reliquae partis cinis cum cerebro hyaenae inlinatur; pilos etiam auferri hac conpositione inlita vel per se felle, evulsis prius qua renasci non libeat; sic et palpebris inutiles tolli; lumborum doloribus carnes e lumbis edendas inlinendasque cum oleo; sterilitatem mulierum emendari oculo cum glyc⟨yr⟩r⟨h⟩iza et aneto sumpto in cibo, promisso intra triduum conceptu. contra nocturnos pavores umbrarumque terrorem unus e magnis dentibus lino alligatus succurrere narratur. suffiri furentes eodem et circumligari ante pectus suum cum adipe renium aut iocinere aut pelle praecipiunt. mulieri candida a pectore hyaenae caro et pili septe⟨ni⟩ et genitale cervi, si inligentur dorcadis pelle ⟨e⟩ collo suspensa, continere partus promittuntur; venerem stimulare genitalia ad sexus suos in melle sumpta, etiamsi viri mulierum coitus oderint; quin immo totius domus concordiam eodem genitali et articulo spinae cum adhaerente corio adservatis constare. hinc spinae articulum s⟨c⟩i⟨t⟩e nodum Atlantion vocant; est autem primus. in comitialium quoque remediis habent eum. adipe accenso serpentes fugari dicunt; maxilla comminuta in aneso et in cibo sumpta horrores sedari; eodem suffitu mulierum menses evocari. tantumque est vanitatis, ut, si ad bracchium alligetur superior⟨e⟩ dextra parte rostri dens, iaculantium ictus deerraturos negent. palato eiusdem arefacto et cum alumine Aegyptio calefacto ac ter in ore permutato faetores et ulcera oris emendari, eos vero, qui linguam in calciamento sub pede habeant, non latrari a canibus; sinistra parte cerebri naribus inlita morbos perniciosos mitigar⟨i⟩ sive hominum sive quadripedum; frontis corium fascinationibus resistere, cervicis carnes, sive mandantur sive arefactae bibantur, lumborum doloribus; nervis a dorso armisque suffiendos nervorum dolores; pilos rostri admotos mulierum labris amatorium esse; iocur in potu datum torminibus et calculis mederi. nam cor in cibo potuve sumptum omnibus doloribus corporum auxiliari, lienem lienibus, omentum ulcerum inflammationibus cum oleo, medullas doloribus spinae et nervorum lassitudini; renium nervos potos in vino cum ture fecunditatem restituere ademptam veneficio; vulvam cum mali Punici dulcis cortice in potu datam prodesse mulierum vulvae; adipe a lumbis suffiri parientes difficulter et statim parere; e dorso medullam adalligatam contra vanas species opitulari, spasticis genitale e maribus suffitu, item lippientibus, ruptis, et contra inflammationes a⟨d⟩versos pedes tactu, laevos dexteris partibus, dexteros laevis; sinistrum pedem superlatum parturienti letalem esse, dextro inlato facile eniti. membranam, quae fel continuerit, cardiacis potam in vino vel in cibo sumptam contra… succurrere; vesicam in vino potam contra urinae incontinentiam; quae autem in vesica inventa sit urina, additis oleo ac sesamis et melle ha⟨u⟩s⟨t⟩am prodesse ⟨sto⟩m⟨ach⟩i a⟨c⟩rimoni⟨ae⟩ veteri. costarum primam et octavam suffitu ruptis salutarem esse; ex spina vero parturientibus ossa; sanguinem cum polenta sumptum torminibus; eodem tactis postibus ubicumque Magorum infestari artes, non elici deos nec conloqui, sive lucernis sive p⟨e⟩lvi sive aqua sive pila sive quo alio genere temptetur; carnes si edantur, contra rabidi canis morsus efficaces esse, etiamnum iocur efficacius. carn⟨e⟩s vel ossa hominis, quae in ventriculo occisae inveniantur, suffitu podagricis auxiliari; si ungues inveniantur in⟨i⟩is, mortem alicuius capientium significari; excrementa sive ossa reddita, cum interematur, contra magicas insidias pollere; fimum, quod in intestinis inventum sit, arefactum ad dysintericos valere, potum inlitumque cum adipe anserino toto corpore opitulari laesis malo medicamento; a cane vero morsis adipem inlitum et corium substratum; rursus tali sinistri cinere decocto cum sanguine mustelae perunctos omnibus odio venire; idem fieri oculo decocto. super omnia est, quod extremam fistulam intestini contra ducum ac potestatium iniquitates commonstrant et ad successus petitionum iudiciorumque ac litium eventus, si omnino [tantum] aliquis secum habeat; eiusdem cavernam sinistro lacerto alligatam, si quis mulierem prospiciat, amatorium esse tam praesens, ut ilico sequatur; eiusdem loci pilorum cinerem ex oleo inlitum viris, qui sint probrosae mollitiae, severos, non modo pudicos, mores induere.", "st": "28.27"}, {"sp": "N", "t": "Proxime fabulosus est crocodilus, ingenio quoque ille, cui vita in aqua terraque communis. duo enim genera eorum. illius e dextra maxilla dentes adalligati dextro lacerto coitus, si credimus, stimulant; canini dentes febris statas arcent ture repleti—sunt enim cavi—ita ne diebus v ab aegro cernatur qui adalligaverit. idem pollere e ventre exemptos lapillos adversus febrium horrores venient⟨e⟩s tradunt. eadem de causa Aegypti perungunt adipe aegros suos. alter illi similis, multum infra magnitudine, in terra tantum odoratissimisque floribus vivit; ob id intestina eius diligenter exquiruntur iucundo nidore referta; crocodileam vocant, oculorum vitiis utilissimam cum porri suco inunctis et contra suffusiones vel caligines. inlita quoque ex oleo cyprino molestias in facie nascentes tollit, ex aqua vero morbos omnes, quorum natura serpit in facie, nitoremque reddit; lentigines tollit ac varos maculasque omnes. et contra comitiales morbos bibitur ex aceto mulso binis obolis. adposita menses ciet. optima quae candidissima et friabilis minimeque ponderosa, cum teratur inter digitos, fermentescens. lavatur ut cerussa. adulterant amylo aut Cimolia, sed maxime ⟨s⟩t⟨u⟩rnorum fimo qui captos oryza tantum pascunt. felle inunctis oculis ex melle contra suffusiones nihil utilius praedicant. intestinis et reliquo corpore eius suffiri vulva laborant⟨e⟩s salutare tradunt, item velleribus circumdari vapore eiusdem infectis. corii utriusque cinis ex aceto inlitus ⟨i⟩is partibus, quas secari opus sit, aut nidor cremati sensum omnem scalpelli aufert. sanguis utriusque claritatem visus inunctis excitat, cicatrices oculorum emendat. corpus ipsum excepto capite pedibusque elixum manditur ischiadicis tussimque veterem sanat, praecipue in pueris, item lumborum dolores. habent et adipem, quo tactus pilus defluit. h⟨i⟩c perunctos a crocodilis tuetur instillaturque morsibus. cor adnexum in lana ovis nigrae, cui nullus alius colos incursaverit, et primo partu genitae quartanas abigere dicitur.", "st": "28.28"}, {"sp": "N", "t": "Iungemus illis simillima et peregrina aeque animalia priusque chamaeleonem, peculiari volumine dignum existimatum Democrito ac per singula membra desecratum, non sine magna voluptate nostra cognitis proditisque mendaciis Graecae vanitatis. similis et magnitudine est supra dicto crocodile, spinae tantum acutiore curvatura et caudae amplitudine distans. nullum animal pavidius existimatur et ideo versicoloris esse mutationis. vis eius maxima contra accipitrum genus. detrahere enim supervolantem ad se traditur et voluntarium praebere lacerandum ceteris animalibus. caput eius et guttur, si roboreis lignis accendantur, imbrium et tonitruum concursus facere Democritus narrat, item iocur in tegulis ustum. reliqua ad veneficia pertinentia quae dicit, quamquam falsa existimantes, omittemus, praeterquam ubi inrisu coarguent⟨e⟩um: dextro oculo, si viventi eruatur, albugines oculorum cum lacte caprino tolli, lingua adalligata pericula puerperii; eundem salutarem esse parturientibus, si sit domi, si vero inferatur, perniciosissimum. linguam, si viventi exempta sit, ad iudiciorum eventus pollere, cor adversus quartanas inligatum lana nigra primae tonsurae. pedem e prioribus dextrum pelle hyaenae adalligatum sinistro bracchio contra latrocinia terroresque nocturnos pollere, item dextram mamillam contra formidines pavoresque; sinistrum vero pedem torreri in furno cum herba, quae aeque chamaeleon vocetur, additoque unguento pastillos eos in ligneum vas conditos praestare, si credimus, ne cernatur ab aliis qui ⟨i⟩d habeat. armum dextrum ad vincendos adversarios vel hostes valere, utique si abiectos eiusdem nervos calcaverit; sinistrum ver⟨o⟩ quibus monstris consecret, qualiter somnia quae velis ac quibus velis mittantur, pudet referre: omnia ea dextro pede resolvi, sicut sinistro latere lethargos, quos fecerit dexter. s⟨e⟩t capitis dolores insperso vino, in quo latus alterutrum maceratum sit, sanari; si feminis sinistri vel pedis cinere misceatur lac suillum, podagricos fieri inlitis pedibus. felle glaucomata et suffusiones corrigi prope creditur tridui inunctione, serpentes fugari ignibus instillato, mustelas contrahi in aquam coiecto, corpori vero inlito detrahi pilos. idem praestare narrat iocur cum ranae rubetae pulmone inlitum; praeterea iocinere amatoria dissolvi, melancholicos autem sanari, si ex corio chamaeleonis sucus herbae He⟨l⟩en⟨ia⟩e bibatur; intestina et fartum eorum, cum animal id nullo cibo vivat, simiarum urina una inlita inimicorum ianuae odium omnium hominum his conciliare; cauda flumina et aquarum impetus sisti, serpentes soporari; eadem medicata cedro et murra inligataque gemino ramo palmae percussam aquam discuti, ut quae intus sint omnia appareant; utinamque eo ramo contactus esset Democritus, quoniam ita loquacitates inmodicas promisit inhiberi. palamque est virum alias sagacem et vitae utilissimum nimio iuvandi mortales studio prolapsum.", "st": "28.29"}, {"sp": "N", "t": "Ex eadem similitudine est scincus—et quidam terrestrem crocodilum esse dixerunt—, candidior autem et tenuiore cute. praecipua tamen differentia dinoscitur a crocodilo, squamarum serie a cauda ad caput versa. maximus Indicus, deinde Arabicus. adferuntur salsi. rostrum eius et pedes in vino albo poti cupiditates veneris accendunt, utique cum satyrio et erucae semine singulis drachmis omnium ac piperis II admixtis ita pastilli singularum drachmarum bibantur. per se laterum carnes obolis binis cum murra et pipere pari modo potae efficaciores ad idem creduntur. prodest et contra sagittarum venena, ut Apelles tradit, ante posteaque sumptus. in antidota quoque nobilia additur. Sextius plus quam drachmae pondere in vini hemina potum perniciem adferre tradit, praeterea eiusdem decocti ius cum melle sumptum venlerem inhibere.", "st": "28.30"}, {"sp": "N", "t": "Est crocodilo cognatio quaedam amnis eiusdem geminique victus cum hippopotamio, repertore detrahendi sanguinis, ut diximus, plurimo autem super Saiticam praefecturam. huius corii cinis cum aqua inlitus panos sanat, adips frigidas febres, item fimum suffitu, dentes e parte laeva dolorem dentium scari⟨ph⟩atis gingivis. pellis eius e sinistra parte frontis ing⟨u⟩in⟨i⟩ adalligata venerem inhibet, eiusdem cinis alopecias explet. testiculi drachma ex aqua contra serpentes bibitur. sanguine pictores utuntur.", "st": "28.31"}, {"sp": "N", "t": "Peregrinae sunt ⟨et⟩ lynces, quae clarissime quadripedum omnium cernunt. ungues earum omnes cum corio exuri efficacissime in Carpatho insula tradunt. hoc cinere poto propudia virorum, eiusdem aspersu feminarum libidines inhiberi, item pruritus corporum, urina stillicidia vesicae. itaque eam protinus terra pedibus adgesta obruere traditur. eadem autem et iugulorum dolori monstratur in remedio. hactenus de externis.", "st": "28.32"}, {"sp": "N", "t": "Nunc praevertemur ad nostrum orbem, primumque communia animalium remedia atque eximia dicemus, sicuti e lactis usu. utilissimum cuique maternum. concipere nutrices exitiosum est; hi sunt enim infantes, qui colostrati appellantur, densato lacte in casei speciem. est autem colostra prima a partu spongea densitas lactis. maxime autem alit quodcumque humanum, mox caprinum, unde fortassis fabulae Iovem ita nutritum dixere. dulcissimum ab hominis camelinum, efficacissimum ex asinis. magnorum animalium et corporum facilius redditur. stomacho adcommodatissimum caprinum, quoniam fronde magis quam herba vescuntur, bubulum medicatius, ovillum dulcius et magis alit, stomacho minus utile, quoniam est pinguius. omne autem vernum aquatius aestivo et de novellis. probatissimum vero quod in ungue haeret nec defluit; innocentius decoctum, praecipue cum calculis marinis. alvus maxime solvitur bubulo, minus autem inflat quodcumque decoctum. usus lactis ad omnia intus exulcerata, maxime renes, vesicam, interanea, fauces, pulmones, foris pruritum cutis, eruptiones pituitae poti ab abstinentia nam ut in A⟨r⟩ca⟨d⟩ia bubulum biberent phthisici, syntectici, cache⟨c⟩tae, diximus in ratione herbarum. sunt inter exempla qui asininum bibendo liberati sint podagra ch⟨i⟩ragraque. medici speciem unam addidere lactis generibus, quod schiston appellavere. id fit hoc modo: fictili novo fervet, caprinum maxime, ramisque ficulneis recentibus miscetur additis totidem cyathis mulsi, quot sint heminae lactis. cum fervet, ne circumfundatur, praestat cyathus argenteus cum frigida aqua demissus ita, ne quid infundat. ablatum deinde igni refrigeratione dividitur et discedit serum a lacte. quidam et ipsum serum iam multo potentissimum decocunt ad tertias partes et sub diu refrigerant. bibitur autem efficacissime heminis per intervalla, sa⟨t⟩is diebus quinae; melius a potu gestari. datur comitialibus, melancholicis, paralyticis, in lepris, elephantiasi, articulariis morbis. infunditur quoque lac contra rosiones a mledicamentis factas et, si urat dysinteria, decoctum cum marinis lapillis aut cum tisana hordeacia. item ad intestinorum rosiones bubulum aut ovillum utilius. recens quoque dysintericis infunditur, ad colum autem crudum, item vulvae et propter serpentium ictus potisve pityocampis, bupresti, cantharidum aut salamandrae venenis, privatim bubulum ⟨i⟩is, qui Colchicum biberint ant cicutam aut dorycnium aut leporem marinum, sicut asininum contra gypsum et cerussam et sulpur et argentum vivum, item durae alvo in febri. gargarizatur quoque faucibus exulceratis. utilissime et bibitur ab imbecillitate vires recolligentibus, quos atrophos vocant, in febri etiam, quae careat dolore capitis. pueris ante cibum lactis asinini heminam dari aut si exitus cibi rosiones sentirent, antiqui in arcanis habuerunt, si hoc non esset, caprini. bubuli serum orthopnoicis prodest ante cetera addito nasturtio. inunguntur etiam oculi in lactis heminas additis sesamae drachmis IIII tritis in lippitudine. caprino lienes sanantur, post bidui inediam tertio die hedera pastis capris, per triduum poto sine alio cibo. lactis usus alias contrarius capitis doloribus, hepaticis, splenicis, nervorum vitio, febres habentibus, vertigini praeterquam purgationis gratia, gravedini, tussientibus, lippis. ⟨o⟩villum utilissimum tenesmo, dysinteriae; nec non phthisicis hoc et mulieris saluberrimum qui dicerent fuerunt.", "st": "28.33"}, {"sp": "N", "t": "De generibus caseorum diximus, cum de uberibus singulisque membris animalium diceremus. Sextius eosdem effectus equino quos bubulo tradit; hunc vocant hippacen. stomacho utiles qui non sunt salsi, id est recentes. veteres alvum sistunt corpusque minuunt, stomacho ⟨in⟩utiliores; et in totum salsa minuunt corpus, alunt mollia. caseus recens cum melle suggillata emendat, mollis alvum sistit, sedat tormina pastillis in vino austero decoctis rursusque in patina tostis cum melle. saprum vocant qui cum sale et sorbis siccis e vino tritus potusque medetur coeliacis. genitalium carbunculis caprinus tritus inpositus, item acidus cum oxymelite maculis in balineo inlitus oleo interlinitur.", "st": "28.34"}, {"sp": "N", "t": "E lacte fit et butyrum, barbararum gentium lautissimus cibus et qui divites a plebe discernat. plurimum e bubulo—et inde nomen—, pinguissimum ex ovibus fit et caprino, sed hieme calefacto lacte, aestate expresso tantum, crebro iactatu in longis vasis angusto foramine spiritum accipientibus sub ipso ore alias praeligato. additur paulum aquae, ut acescat. quod est maxime coactum, in summo fluitat; id exemptum addito sale oxygala appellant. relicum decocunt in ollis; ibi quod supernatat, butyrum est, oleosum natura. quo magis virus resipit, hoc praestantius iudicatur. pluribus conpositionibus miscetur inveteratum. natura eius adstringere, mollire, replere, purgare.", "st": "28.35"}, {"sp": "N", "t": "Oxygala fit et alio modo, acido lacte addito in recens, quod ve⟨l⟩in⟨t⟩ acescere, utilissimum stomacho. effectus dicemus suis locis.", "st": "28.36"}, {"sp": "N", "t": "Proxima in communibus adipi laus est, sed maxime suillo, apud antiquos etiam religiosius. certe novae nuptae intrantes etiam nun⟨c⟩ sollemne habent postes eo attingere. inveteratur duobus modis, cum sale aut sincerus; tanto fit utilior. axungiam Graeci etiam appellavere iam in voluminibus suis. neque est occulta virium causa, quoniam id animal herbarum radicibus vescitur; itaque etiam fimo innumeri usus. quam ob rem non de alia loquemur [sue]. multo efficacior e femina et quae non peper⟨er⟩it, multo vero praestantior in apris ess⟨e⟩⟨d⟩i⟨c⟩itur usus axungiae ad emollienda, excalfacienda, discutienda purgandaque. medicorum aliqui admixto anseris adipe taurorumque sebo et oesypo ad podagras uti iubent; si vero permane⟨a⟩t dolor, cum cera, myrto, resina, pice. sincera axungia medetur ambustis vel nive, pernionibus autem cum hordei cinere et galla pari modo. prodest et confricatis membris, itinerumque lassitudines et fatigationes levat. ad tussim veterem recens decoquitur quadrantis pondere in vini cyathis III addito melle. vetus etiam phthisis pilulis sumpta sanat, quae sine sale inveterata est. omnino enim non nisi ad ea, quae purganda sint aut quae non sint exulcerata, salsa recipitur. quidam quadrantes axungiae et mulsi in vini cyathis ternis decocunt contra phthisis, quarto quoque die picem liquidam in ovo sumi iubent. circumligatur et lateribus, pectori, scapulis eorum, qui phthisim sentiunt, tantaque est vis, ut genibus etiam adalligata redeat in os sapor eamque expuere videantur. e sue, quae non pepererit, aptissime utuntur, ad cutem mulieres, contra scabiem vero quivis admixto iumentorum sebo pro parte tertia et pice pariterque subfervefactis. sincera partus in abortun vergentes nutrit collyrii modo subdita. cicatrices concolores facit cerussa admixta vel argenti spuma, at cum sulpure unguium scrabritias emendat. medetur et capillo fluenti et ulceribus in capite mulierum cum gallae parte quarta et infumata pilis oculorum. datur et phthisicis unciatim cum vini veteris hemina decocta, donec III unciae e toto restent; aliqui et mellis exiguum adiciunt. panis inlinitur cum calce, item furunculis duritiaeque mammarum. rupta et convulsa et spasmata et luxata sanat, clavos et rimas callique vitia cum helleboro albo, parotidas admixta farina salsamentariae testae, quo genere proficit et ad strumas. pruritus et papulas in balineo perunctis tollit, alioque etiamnum modo podagricis prodest mixto oleo vetere, contrito una sarcophago lapide et quinquefolio tuso in vino vel cum calce aut cum cinere. fit et peculiare emplastrum LXXV X̶ ponderi c spumae argenteae mixtis, utilissime contra ulcerum inflammationes adipe verrino. et inungui putant utile, quaeque serpant inlinere cum resina. antiqui axibus vehiculorum perunguendis maxime ad faciliorem circumactum rotarum utebantur, unde nomen, sic quoque utili medicina cum illa ferrugine rotarum ad sedis vitia virilitatisque et per se axungia. medici antiqui maxime probabant renibus detractam exemptisque venis aqua caelesti fricabant crebro decoquebantque fictili novo saepius, tum demum adservantes. convenit salsam magis mollire, excalfacere, discutere, utilioremque esse vino lotam. Masurius palmam lupino adipi dedisse antiquos tradidit. ideo novas nuptas illo perunguere postes solitas, ne quid mali medicamenti inferretur.", "st": "28.37"}, {"sp": "N", "t": "Quae ratio adipis, eadem in ⟨i⟩is, quae ruminant, sebi est, aliis modis, non minoris potentiae. perficitur omne exemptis venis aqua marina vel salsa lotum, mox in pila tusum aspersa marina crebro; postea coquitur, donee odor omnis aboleatur, mox adsiduo sole ad candorem reducitur. a renibus autem omne laudatissimum est. si vero vetus revocetur ad curam, liquefieri prius iubent, mox frigida aqua lavari saepius, dein liquefacere adfuso vino quam odoratissimo. eodemque modo iterum ac saepius cocunt, donec virus evanescat. multi privatim sic taurorum leonumque ac pantherarum et camelorum pinguia curari iubent. usus dicetur suis locis.", "st": "28.38"}, {"sp": "N", "t": "Communis et medullarum est. omnes molliunt, explent, siccant, excalfaciunt. laudatissima e cervis, mox vitulina, dein hircina et caprina. curantur ante autumnum. recentes lotae siccataeque in umbra, per cribrum dein liquatae per lintea exprimuntur ac reponuntur in fictili locis frigidis.", "st": "28.39"}, {"sp": "N", "t": "Inter omnia autem communia animalium vel praestantissimum effectu fel est. vis eius excalfacere, mordere, scindere, extrahere, discutere. minorum animalium subtilius intellegitur et ideo ad oculorum medicamenta utilius existimatur. taurino praecipua potentia, etiam in aere pel⟨v⟩ibusque aureo colore ⟨ob⟩ducendis. omne autem curatur recens praeligato ore lino crasso, demissum in ferventem aquam semihora, mox siccatum sine sole atque in melle conditum. damnatur equinum tantum inter venena. ideo flamini sacrorum equum tangere non licet, cum Romae publicis sacris equus etiam immoletur.", "st": "28.40"}, {"sp": "N", "t": "Quin et sanguis eorum septicam vim habet; item equarum, praeterquam virginum, erodit, emarginat ulcera. taurinus quidem recens inter venena est excepta Aegira. ibi enim sacerdos Terrae vaticinatura sanguinem tauri bibit prius quam in specus descendat. tantum potest sympathia illa, de qua loquimur, ut aliquando religione aut loco fiat. Drusus tribunus plebei traditur caprinum bibisse, cum pallore et invidia veneni sibi dati insimulare Q. Caepionem inimicum vellet. hircorum sanguini tanta vis est, ut ferramentorum subtilitas non aliter acrius induretur, scabritia poliatur vehementius quam lima. non igitur et sanguis animalium inter communia dici potest, et ideo suis quisque dicetur effectibus.", "st": "28.41"}, {"sp": "N", "t": "Digeremus enim in mala singula usus primumque contra serpentes. exitio his esse cervos nemo ignorat ut, si quae sunt, extractas cavernis mandentes. nec vero ipsi spirantesque tantum adversantur, sed membratim quoque. fugari eas nidore cornus eorum, si uratur, dictum est; at e summo gutture ustis ossibus congregari dicuntur. pelles eiusdem animalis substratae securos praestant ab eo metu somnos, coagulum. ex aceto potum ab ictu; et si omnino tractatum sit, eo die non ferit serpens. testes quoque eius inveterati vel genitale vetus maris salutariter dantur in vino; item venter, quem centipellionem vocant. fugiunt et omnino dentem cervi habentes ant medulla perunctos sebove cervi aut vituli. summis autem remediis praefertur hinnulei coagulum matris utero execti, ut indicavimus. sanguine cervino, si una urantur dracontion et cunilago et anchusa lentisci ligno, contrahi serpentes tradunt, dissipari deinde, si sanguine detracto adiciatur pyrethrum. invenio apud auctores Graecos, animal cervo minus et pilo demum simile, quod ophion vocaretur, Sardiniam tantum ferre solitam. hoc interisse arbitror et ideo medicinas ex eo omitto. —", "st": "28.42"}, {"sp": "N", "t": "Apri quoque cerebrum contra eas laudatur cum sanguine, iocur etiam inveteratum cum ruta potum ex vino, item adips cum melle resinaque, simili modo verrinum iocur et fellis dumtaxat fibra X̶ IIII pondere vel cerebrum in vino potum.—Caprarum cornu vel pilis accensis fugari serpentes dicunt, cineremque e cornu potum vel inlitum contra ictus valere, item lactis haustus cum uva taminia vel urinae cum aceto scillite, caseum caprinum cum origano inpositum vel sebum cum cera. milia praeterea remediorum ex eo animali demonstrantur, sicut apparebit, quod equidem miror, cum febri negetur carere. amplior potentia feris eiusdem generis, quod numerosissimum esse diximus, alia vero et hircis. Democritus etiamnum effectus auget eius, qui singularis natus sit. fimo quoque caprarum in aceto decocto inlini ictus serpentium placet et recentis cinere in vino, atque in totum difficilius sese recolligentes a serpentium ictu in caprilibus optime convalescunt. qui efficacius volunt mederi, occisae caprae alvum dissectam cum fimo intus reperto inligant statim. alii carnem recentem haedorum cum pilo suffiunt eodelmque nidore fugant serpentes. utuntur et pelle eorum recent⟨i⟩, ad plagas et came et fimo equi in agro pasti, coagulo leporis ex aceto contraque scorpionem et murem araneum; aiunt non feriri leporis coagulo perunctos. a scorpione percussis fimum caprae efficacius aceto decoctum auxiliatur, lardum iusque decocti potum et⟨i⟩is, qui buprestim hauserint. quin etiam si quis asino in aurem percussum a scorpione se dicat, transire malum protinus tradunt, venenataque omnia accenso pulmone eius fugere. et fimo vituli suffiri percussos a scorpione prodest.", "st": "28.42"}, {"sp": "N", "t": "Canis rabiosi morsu facta volnera circumcidunt ad vivas usque partes quidam carnemque vituli admovent et ius ex eodem carnis decoctae dant potui aut axungiam cum calce tusam, hirci iocur, quo inposito ne temptari quidem aquae metu adfirmant. laudant et caprae fimum ex vino inlitum, melis et cuculi et hirundinis decoctum et potum. ad reliquos bestiarum morsus caprinum caseum siccum cum origano inponunt et bibi iubent, ad hominis morsus carnem bubulam coctam, efficacius vituli, si non ante quintum diem solvant.", "st": "28.43"}, {"sp": "N", "t": "Veneficiis rostrum lupi resistere inveteratum aiunt ob idque villarum portis praefigunt. hoc idem praestare et pellis e cervice solida manica existimatur, quippe tanta vis est animalis praeter ea, quae retulimus, ut vestigia eius calcata equis adferant torporem. —", "st": "28.44"}, {"sp": "N", "t": "Iis, qui argentum vivum biberint, lardum remedio est.—Asinino lacte poto venena restinguntur, peculiariter si hyoscyamum potum sit aut viscum aut cicuta aut lepus marinus aut opocarpatum aut cer⟨uss⟩a ant dorycnium et si coagulum alicui nocuerit, nam id quoque venenum est in prima lactis coagulatione. multos et alios usus eius dicemus, sed meminisse oportebit recenti utendum aut non multo postea tepefacto; nullum enim celerius evanescit. ossa quoque asini confracta et decocta contra leporis marini venenum dantur. omnia eadem onagris efficaciora. —De equiferis non scripserunt Graeci, quoniam terrae illae non gignebant, verum tamen fortiora omnia eadem quam in equis intellegi debent. lacte equino venena leporis marini et toxica expugnantur. nec uros aut bisontes habuerunt Graeci in experimentis, quamquam bove fero refertis Indiae silvis; ⟨p⟩r⟨o⟩ portione tamen eadem efficaciora omnia ex his credi par est. sic quoque lacte bubulo cuncta venena expugnari tradunt, maxime supra dicta et si ephemerum inpactum sit aut si cantharides datae; omnia vomitione egeri, sic et caprino iure cantharidas. contra ea vero, quae exulceratione enecant, sebum vitulinum vel bubulum auxiliatur. nam contra sanguisugas potas butyrum remedio est cum aceto ferro calefacto, quod et per se prodest contra venena, nam si oleum non sit, vicem eius repraesentat. multipedae morsus cum melle sanat. omasi quoque iure poto venena supra dicta expugnari putant, privatim vero aconita et cicutas, itemque vitulino sebo.— Caprinus caseus recens ⟨i⟩is, qui viscum biberint, lac contra cantharidas remedio est, contra ephemeri potum cum taminia uva. sanguis caprinus decoctus cum medulla contra toxica venena sumitur, haedinus contra reliqua, coagulum haedi contra viscum et chamaeleonem album sanguinemque taurinum, contra quem et leporis coagulum est ex aceto, contra pastinacam vero et omnium marinorum ictus vel morsus coagulum leporis vel haedi vel agni drachmae pondere ex vino. leporis coagulum et contra venena additur antidotis. papilio quoque lucernarum luminibus advolans inter mala medicamenta numeratur; huic contrarium est iocur caprinum, sicut fel veneficiis ex mustella rustica factis. hinc deinde praevertemur ad genera morborum.", "st": "28.45"}, {"sp": "N", "t": "Capilli defluvia ursinus adips admixto ladano et adianto continet alopeciasque emendat et raritatem superciliorum cum fungis lucernarum ac fuligine, quae est in rostris earum, porriginem cum vino. prodest ad hanc et cornus cervini cinis e vino utque non taedia animalium capillis increscant, item fel caprinum cum creta Cimolia et aceto sic, uti paulum capiti inarescant, item fel scrofinum, urina tauri. si vero vetus sit, furfures etiam adiecto sulpure emendat. cinere genitalis asini spissari capillum putant et a canitie vindicari, si rasis inlinatur plumboque tritus cum oleo, densari et asinini pulli ⟨illit⟩um urina; admiscent nardum fastidii gratia. alopecias felle taurino cum Aegyptio alumine tepefact⟨o⟩ inlinunt. ulcera capitis manantia urina tauri efficaciter sanat, item hominis vetus, si cyclaminum adiciatur et sulpur, efficacius tamen vitulinum fel, quo cum aceto calefacto et lendes tolluntur. sebum vitulinum capitis ulceribus cum sale tritum utilissimum. laudatur et vulpium adips, sed praecipue fel⟨i⟩um fimum cum sinapis pari modo inlitum, caprini cornus farina vel cinis, magisque hircini, addito nitro et ⟨t⟩amarici⟨s⟩ semine et butyro oleoque, prius capite raso; mire continent ita fluentem capillum, sicuti carnis cinere ex oleo inlita supercilia nigrescunt. lacte caprino lendes tolli tradunt, fimo cum melle alopecias expleri, item ungularum cinere cum pice. fluentem capillum continet leporinus cinis cum oleo myrteo.—Capitis dolorem sedat pota a⟨qua⟩, quae relicta est e bovis aut asini potu, et, si credimus, vulpis masculae genitale ci rcumligatum, cornus cervini cinis inlitus ex aceto aut rosaceo aut ex irino.—", "st": "28.46"}, {"sp": "N", "t": "Oculorum epiphoras bubulo sebo cum oleo cocto inlinunt; cervini cornus cinere scabritias ex eodem inungu⟨u⟩n⟨t⟩, mucrones autem ipsos efficaciores putant. lupi excrementis circumlini suffusiones prodest, cinere eorum cum Attico melle inungui obscuritates, item felle ursino, epinyctidas adipe apruno cum rosaceo. ungulae asininae cinis inunctus e suo lacte oculorum cicatrices et albugines tollit. medulla bubula e dextro crure priore trita cum fuligine pilis et palpebrarum vitiis angulorumque occurrit—calliblephari modo fuligo in hoc usu temperatur, optime e⟨l⟩lychnio papyraceo oleoque sesamino fuligine in novum vas pinnis detersa—, efficacissime tamen evolsos ibi pilos coercet. felle tauri cum ovi albo collyria fiunt, aquaque dissoluta inungunt per quadriduum. sebum vituli cum anseris adipe et ocimi suco genarum vitiis aptissimum est. eiusdem medullae cum pari pondere cerae et olei vel rosacei addito ovo duritiae genarum inlinuntur. caseo molli caprino inposito ex aqua calida epiphorae sedantur; si tumor sit, ex melle; utrumque sero calido fovendum. sicca lippitudo lumbulis suum exustis atque contritis et inpositis tollitur. capras negant lippire, quoniam quasdam herbas ed⟨i⟩nt, item dorcadas; ob id fimum earum cera circumdatuml nova luna devorari iubent. et quoniam noctu quoque aeque cernant, sanguine hircino lusciosos sanari putant, nyctalopas a Graecis dictos, caprae vero iocinere in vino austero decocto. quidam inassati iocineris sanie inungunt aut felle caprae, carnesque vesci eas et, dum coquantur, oculos vaporari ⟨i⟩is praecipiunt; id quoque referre arbitrantur, ut rutili coloris fuerit. volunt et suffiri oculos iocinere in ollis decocto, quidam inassato. fel quidem caprinum pluribus modis adsumunt, cum melle contra caligines, cum veratri candidi tertia parte contra glaucomata, cum vino contra cicatrices et albugines et caligines et pterygia et argema, ad palpebras vero evolso prius pilo cum suco oleris ita, ut unctio inarescat, contra ruptas tuniculas cum lacte mulieris. ad omnia inveteratum fel efficacius putant. nec abdicant fimum ex melle inlitum epiphoris, contraque dolores medullam, item pulmonem leporis, et ad caligines fel cum passo aut melle. lupino quoque adipe vel medulla snum fricari oculos contra lippitudines praecipiunt. nam vulpinam linguam habentes in armilla lippituros negant.", "st": "28.47"}, {"sp": "N", "t": "Aurium dolori et vitiis medentur urina apri in vitreo servata, fel apri vel suis vel bubulum cum oleo ce⟨d⟩rino et rosaceo aequis portionibus, praecipue vero taurinum cum porri suco tepidum vel cum melle, si suppurent, contraque odorem gravem per se, tepefactum in malicorio. rupta in ea parte cum lacte mulierum efficaciter sanat. quidam et in gravitate aures sic perluendas putant, alii cum senecta serpentium et aceto—includunt lana —collutas ante calida aqua aut, si maior sit gravitas, v⟨er⟩ri⟨n⟩um fel cum murra et ruta in malicorio excalfactum infundunt, lardum quoque pingue; item fimum asini recens cum rosaceo instillatur, omnia tepefacta. utilior equi spuma vel equini fimi recentis cinis cum rosaceo, butyrum recens, sebum bubulum cum adipe anserino, urina caprae vel tauri aut fullonia vetus, calfacta⟨e⟩ vapore per lagoenae collum subeunte—admiscent aceti tertiam partem et aliquid murrae —, vituli, qui nondum herbam gustaverit, fimum mixto felle eiusdem et cute, quam relincunt angues, excalefactis prius auribus; lana autem medicamina ea includuntur. prodest et sebum vituli cum anseris adipe et ocimi suco, eiusdem medulla admixto cumino trito infusa, virus verrinum e scrofa exceptum, priusquam terram attingat, contra dolores; auribus fractis glutinum e naturis vitulorum factum et in aqua liquatum; aliis vitiis adips vulpium, item fel caprinum cum rosaceo tepido aut porri suco aut, si rupta sint aliqua ibi, e lacte mulieris; si gravitas audiendi, fel bubulum cum urina caprae vel hirci, vel si pus sit. in quocumque autem usu putant efficaciora haec in cornu caprino per dies XX infumata. laudant et coagulum leporis tertia parte X̶ dimidiaque sacopen⟨i⟩i in Am⟨m⟩ineo vino.—Parotidas ursinus adips conprimit pari pondere cerae et taurini sebi— addunt quidam hypocisthidem —, et per se butyrum inlitum, si prius foveantur feni Graeci decocti suco, efficacius cum strychno. prosunt et vulpium testes et taurinus sanguis aridus tritus, urina caprae calefacta instillata auribus, fimum eiusdem cum axungia inlitum.", "st": "28.48"}, {"sp": "N", "t": "Dentes mobiles confirmat cervini cornus cinis doloresque eorum mitigat, sive infricentur sive colluantur. quidam efficaciorem ad omnes eosdem usus crudi cornus farinam arbitrantur. dentifricia utroque modo fiunt. magnum remedium est et in luporum capitis cinere. certum est in excrementis eorum plerumque inveniri ossa; haec adalligata eundem effectum habent, item leporina coagula per aurem infusa contra dolores. et capitis eorum cinis dentifricium est adiectoque nardo mulcet graveolentiam oris. aliqui murinorum capitum cinerem miscuisse malunt. reperitur in latere leporis os acui simile; hoc scari⟨ph⟩are dentes in dolore suadent. talus bubulus accensus eos, qui labent cum dolore, admotus confirmat; eiusdem cinis cum murra dentifricium est. ossa quoque ex ungulis suum combusta eundem usum praebent, item ossa ex acetabulis pernarum, circa quae coxendices vertuntur. isdem sanari demissis in fauces iumentorum verminationes notum est, sed et combustis dentes confirmari, asinino quoque lacte percussu vexatos aut dentium eiusdem cinere, item lichene equi cum oleo infuso per aurem. est autem hoc non hippomanes, quod alioqui noxium omitto, sed in equorum genibus ac super ungulas. praeterea in corde equorum invenitur os dentibus caninis maximis simile; hoc scari⟨ph⟩ari dolorem aut exempto dente mortui equi maxillis ad numerum eius, qui doleat, demonstrant. equarum virus a coitu in ellychniis accensum Anaxilaus prodidit lichenis equinorum capitum v⟨ire⟩s repraesentare monstrifice, similiter ex asinis. nam hippomanes tantas in veneficio vires habet, ut adfusum aeris mixturae in effigiem equae Olympiae admotos mares equos ad rabiem coitus agat. medetur dentibus et fabrile glutinum in aqua decoctum inlitum et mox paulo detractum ita, ut confestim conluantur vino, in quo decocti sint cortices mali Punici dulcis. efficax habetur et caprino lacte conlui dentes vel felle taurino. talorum caprae recentium cinis dentifricio placet et omnium fere villaticarum quadrupedum, ne saepius eadem dicantur.", "st": "28.49"}, {"sp": "N", "t": "Cutem in facie erugari et tenerescere candore lacte asinino putant, notumque est quasdam cottidie septi⟨es⟩ genas custodito numero fovere. Poppaea hoc Neronis principis instituit, balnearum quoque solia sic temperans, ob hoc asinarum gregibus eam comitantibus. impetus pituitae in facie butyro inlito tolluntur, efficacius cum cerussa, sincero vero ea vitia, quae serpunt, superinposita farina hordeacia, ulcera in facie membrana e partu bovis madida. frivolum videatur, non tamen omittendum propter desideria mulierum, talum candidi iuvenci XL diebus noctibusque, done resolvatur in liquorem, decoctum et inlitum linteolo candorem cutisque erugationem praestare. fimo taurino malas rubescere aiunt, non ut crocodileam inlini melius s⟨it⟩; foveri frigida et ante et postea iubent. testas et quae decolorem faciunt cutem fimum vituli cum oleo et cummi manu subactum emendat; ulcera oris ac rimas sebum vituli vel bovis cum adipe anserino et ocimi suco. est et alia mixtura sebo vituli cum medulla cervi et albae spinae foliis una tritis. idem praestat et medulla cum resina vel, si vaccina sit, et ius e cane vaccina. lichenas oris praestantissime vincit glutinum factum e genitalibus vitulorum, liquatum aceto cum sulpure vivo, ramo ficulneo permixtum, ita ut bis die recens inlinatur, item lepras ex melle et aceto decoctum, quas et iocur hirci calidum inlitum tollit, sicut elephantiasin fel caprinum; etiamnum lepras ac furfures tauri fel addito nitro, urina asini circa canis ortum; maculas in facie fel utriusque per sese aqua infractum evitatisque solibus ac ventis post detractam cutem. similis effectus et in taurino vitulinove felle cum semine cunilae, cinere e cornu cervino, si canicula exoriente conburatur. asinino sebo cicatricibus, a lichene leprisque maxime, color redditur. hirci fel et lentigines tollit admixto caseo cum vivo sulpure spongeaque cinere, ut sit mellis crassitudo. aliqui inveterato felle maluere uti, mixtis calidis furfuribus pondere oboli unius IIIIque mellis, prius defricatis maculis. efficax eiusdem et sebum cum melanthio et sulpure et iride, labrorum fissuris cum anserino adipe ac medulla cervina resinaque et calce.—Invenio aput auctores ⟨i⟩is, qui lentigines habeant, negari magices sacrificiorum usus.—", "st": "28.50"}, {"sp": "N", "t": "Lacte bubulo aut caprino tonsillae et arteriae exulceratae iuvantur. gargarizatur tepidum, ut est usus, expressum aut calefactum. caprinum utilius cum malva decoctum et sale exiguo. linguae exulcerationi et arteriarum prodest ius omasi gargarizatum, tonsillis autem privatim renes vulpium aridi cum melle triti inlitique, anginae fel taurinum vel caprinum cum melle, iocur melis ex aqua. oris gravitatem ulceraque butyrum emendat. spinam aliudve quid faucibus adhaerens felis extrinsecus fimo perfricatis aut reddi aut delabi tradunt. strumas discutit fel aprunum vel bubulum tepidum inlitum—nam coagulum leporis e vino in linteolo exulceratis dumtaxat inponitur—, discutit et ungulae asini vel equi cinis ex oleo vel aqua inlitus et urina calefacta et bovis ungulae cinis ex aqua, fimum quoque fervens ex aceto, item sebum caprinum cum calce aut fimum ex aceto decoctum, testes volpini. prodest et sapo, Galliarum hoc inventum rutilandis capillis. fit ex sebo et cinere, optimus fagino et caprino, duobus modis, spissus ac liquidus, uterque apud Germanos maiore in usu viris quam ferinis.", "st": "28.51"}, {"sp": "N", "t": "Cervicium dolores butyro aut adipe ursino perfricentur, rigores bubulo sebo, quod et strumis prodest cum oleo. dolorem inflexibilem—opisthotonum vocant —levat urina caprae auribus infusa aut fimum cum bulbis inlitum; ungues contusos fel cuiuscumque animalis circumligatum; pterygia digitorum fel tauri aridum aqua calida dissolutum. quidam adiciunt sulpur et alumen pari pondere omnium.", "st": "28.52"}, {"sp": "N", "t": "Tussim iocur lupi ex vino tepido sanat, ursinum fel admixto melle aut ex cornus bubuli summis partibus cinis vel saliva equi triduo pota—ecum mori tradunt— pulmo cervinus cum gula sua arefactus in fumo, dein tusus ex melle cottidiano ecligmate; efficacior ad id subulo cervorum generis. sanguinem expuentes cervini cornus cinis, coagulum leporis tertia parte denarii cum terra Samia et vino myrteo potum sanat; eiusdem fimi cinis in vino vesperi potus nocturnas tussis, pili quoque leporis suffiti extrahunt pulmonibus difficiles excreationes. purulentas autem exulcerationes pectoris pulmonisque et a pulmone graveolentiam halitus butyrum efficacissime iuvat cum pari modo mellis Attici decoctum, donec rufescat, et matutinis sumptum ad mensuram lingulae; quidam pro melle laricis resinam addere maluere. si sanguis reiciatur, efficacem tradunt bubulum sanguinem, modice et cum aceto sumptum. nam de taurino credere temerarium est; sed glutinum taurinum III obolis cum calida aqua bibitur in vetere sanguinis excreatione.", "st": "28.53"}, {"sp": "N", "t": "Stomachum exulceratum lactis asinini potus reficit, item bubuli; rosiones eius caro bubula mixto aceto et vino cocta; rheumatismos cornus cervini cinis; sanguinis excreationes haedinus sanguis recens ad cyathos ternos cum aceto acri pari modo fervens potus, coagulum tertia parte ex aceto potum;", "st": "28.54"}, {"sp": "N", "t": "iocineris dolores lupi iocur aridum ex mulso, asini iocur aridum cum petroselini partibus II ac nucibus III ex melle tritum et in cibo sumptum, sanguis hircinus cibo aptatus. suspiriosis ante omnia efficax est potus equiferorum sanguinis, proxime lactis asinini tepidi, bubuli decocti ita, ut serum ex eo bibatur, addito in II heminas cyatho nasturtii albi perfusi aqua. dein melle diluti. iocur quoque vulpinum aut pulmo in vino nigro aut fel ursinum in aqua laxat meatus spirandi.", "st": "28.55"}, {"sp": "N", "t": "Lumborum dolores et quaecumque alia molliri opus sit ursino adipe perfricari convenit, cinerem apruni aut suilli fimi inveterati aspergi potioni vini.—(Adferunt et Magi sua commenta: primum omnium rabiem hircorum, si mulceatur barba, mitigari, eadem praecisa non abire eos in alienum gregem). * ischiadicis fimum bubulum inponunt calfactum in foliis cinere ferventi. * huic admiscent fimum caprinum et subdito linteolo uncto cava manu, quantum pati possit, fervens sustineri iubent ita, ut si laeva pars doleat, haec medicina in dextera manu fiat aut e contrario, fimumque ad eum usum acus aereae punctu tolli iubent. modus est curationis, donec vapor ad lumbos pervenisse sentiatur; postea manum porro tuso inlinunt, item lumbos ipso fimo cum melle. suadent in eo dolore et testes leporis devcrare.* in renium dolore leporis renes crudos devorari iubent aut certe coctos ita, ne dente contingantur. ventris quidem dolore temptari negant talum leporis habentes.", "st": "28.56"}, {"sp": "N", "t": "Lienem sedat fel apri vel suis potum, cervini cornus cinis in aceto, efficacissime tamen inveteratus lien asini ita, ut in triduo sentiatur utilitas. asinini pulli fimum, quod primum edidit—poleam vocant—, Syri dant in aceto mulso. datur et equi lingua inveterata ex vino praesentaneo medicamento, ut didicisse se ex barbaris Caecilius Bion tradidit, et lien bubulus simili mode, recens autem assus vel elixus in cibo. in vesica quoque bovis alii capita xx tusa cum aceti sextario imponuntur ad lienis dolores. eadem ex causa emi lienem vituli, quanti indicatus sit, iubent Magi nulla pretii cunctatione, quoniam hoc quoque religiose pertineat, divisumque per longitudinem adnecti tunicae utrimque et induentem pati decidere ad pedes, dein collectum arefacere in umbra. cum hoc fiat, simul residere lienem aegri vitiatum liberarique eum morbo dicitur. prodest et pulmo vulpium cinere siccatus atque in aqua potus, item haedorum lien impositus.", "st": "28.57"}, {"sp": "N", "t": "Alvum sistit cervi sanguis, item cornus cinis, iocur aprunum ex vino potum citra salem recensque, item assum, vel suillum, hircinum decoctum ad quintas hemina in vino, coagulum leporis in vino ciceris magnitudine aut, si febris sit, ex aqua—aliqui et gallam adiciunt, alii per se leporis sanguine contenti sunt—, lac coctum, equini fimi cinis in aquae potu, taurini cornus veteris e parte ima cinis inspersus potioni aquae, sanguis hircinus carbone decoctus, corium caprinum cum suo pilo decoctum suco epoto, coagulum equi et sanguis caprinus vel medulla vel iocur.—Alvum solvit fel lupi cum elaterio umbilico inlitum vel lactis equini potus, item caprini cum sale et melle, caprae fel cum cyclamini suco et aluminis momento —aliqui et nitrum et aquam adiecisse malunt—, fel tauri cum absinthio tritum ac subditum pastillo, butyrum largius sumptum. —Coeliacis et dysintericis medetur iocur vaccinum, cornus cervini cinis III digitis captus in potione aquae, coagulum leporis subactum in pane, si vero sanguinem detrahant, in polenta, apruni vel suilli vel leporini fimi cinis inspersus potioni tepidi vini. vituli quoque ius vulgariter da⟨r⟩i inter auxilia coeliacorum et dysintericorum tradunt. lactis asinini potus utilior addito melle, nec minus efficax fimi cinis ex vino utrique vitio, item polea supra dicta, equi coagulum, quod aliqui hippacen appellant, etiam si sanguinem detrahant, vel fimi cinis dentiumque eiusdem tusorum farina salutares et bubuli lactis decocti potus. dysintericis addi mellis exiguum praecipiunt et, si tormina sint, cornus cervini cinerem aut fel taurinum cumino mixtum et cucurbitae carnes umbilico inponere. caseus recens vaccinus inmittitur ad utrumque vitium, item butyrum heminis IIII cum resinae terebinthinae sextante aut cum malva decocta aut cum rosaceo. datur et sebum vitulinum aut bubulum, item medulla —et coqu⟨i⟩tur cum farinae ceraeque exiguo et oleo, ut sorberi possit, medulla et in pane subigitur—, lac caprinum ad dimidias partes decoctum; si sint et tormina, additur protropum. torminibus satis esse remedii in leporis coagulo poto e vino tepido vel semel arbitrantur aliqui; cautiores et sanguine caprino cum farina hordeacea et resina ventrem inlinunt. ad omnes epiphoras ventris inlini caseum mollem suadent, veterem autem in farina⟨m⟩ tritum coeliacis et dysintericis dari, cyatho casei in cyathis vini cibarii III. sanguis caprinus decoctus cum medulla dysintericis, iocur assum caprae coeliacis subvenit, magisque etiam hirci, in vino austero decoctum potumque vel ex oleo myrteo umbilico inpositum. quidam decocunt a III sextariis aquae ad heminam addita ruta. utuntur et liene asso caprae hircive et sebo hirci in pane, qui cinere coctus sit, caprae a renibus maxime, ut per se hauriatur protinusque modice frigida. sorberi iubent aliqui et in aqua decoctum sebum admixta polenta et cumino et aneto acetoque. inlinunt et ventrem coeliacis fimo cum melle decocto. utuntur ad utrumque vitium et coagulo haedi in vino myrtite fabae magnitudine poto et sanguine eiusdem in cibum formato, quem sanguiculum vocant. infundunt dysintericis et glutinum taurinum aqua calida resolutum. inflationes discutit vitulinum fimum in vino decoctum.—Intestinorum vitiis magnopere prodest coagulum cervorum decoctum cum lente betaque atque ita in cibo sumptum, leporis pilorum cinis cum melle decoctus, lactis caprini potus decocti cum malva exiguo sale addito; si et coagulum addatur, maioribus emolumentis fiat. eadem vis est et in sebo caprino in sorbitione aliqua, uti protinus hauriatur frigida aqua. item feminum haedi cinis rupta intestina sarcire mire traditur, fimum leporis cum melle decoctum et cottidie fabae magnitudine sumptum ita, ut deploratos sanaverint. laudant et caprini capitis cum suis pilis discocti sucum.", "st": "28.58"}, {"sp": "N", "t": "Tenesmos, id est crebra et inanis voluntas desurgendi, tollitur poto lacte asinino, item bubulo.—Taenearum genera pellit cervini cornus cinis potus.—Quae in excrementis lupi diximus inveniri ossa, si terram non attigerint, colo medentur adalligata bracchio. polea quoque supra dicta magnopere prodest decocta in sapa, item suilli fimi farina addito cumino in aqua rutae decoctae, cornus cervini teneri cinis cocleis Africanis cum testa sua tusis mixtus in vini potione.", "st": "28.59"}, {"sp": "N", "t": "Vesicae calculorumque cruciatibus auxiliatur urina apri et ipsa vesica pro cibo sumpta, efficacius, si prius fumo maceretur utrumque. vesicam elixam mandi oportet, et a muliere feminae suis. inveniuntur in iocineribus eorum lapilli aut duritiae lapillis similes, candidae, sicut in vulgari sue, quibus contritis atque in vino potis pelli calculos aiunt. ipsi apro tam gravis urina sua est, ut nisi egesta fugae non sufficiat ac velut devinctus opprimatur; exuri illa tradunt eos. leporis renes inveterati in vino poti calculos pellunt. in pernae suum articulo os diximus, quod decoctum ius facit urinae utile. asini renes inveterati tritique e⟨x⟩ vino mero dati vesicae medentur. calculos expellunt lichenes equini ex vino aut mulso poti diebus XL. prodest et ungulae equinae cinis in vino aut aqua, item fimum caprarum in mulso, efficacius silvestrium, pili quoque caprini cinis; verendorum carbunculis cerebrum apri vel suis sanguisque. vitia vero, quae in eadem parte serpunt, iocur eorum combustum, maxime iunipiri ligno, cum charta et arrhenico sanat, fimi cinis, fel bubulum cum alumine Aegyptio ac murra ad crassitudinem mellis subactum, insuper beta ex vino cocta inposita, caro quoque; manantia vero ulcera sebum cum medulla vituli in vino decoctum, fel caprinum cum melle rubique suco, vel si serpant; fimum etiam prodesse cum melle dicunt aut cum aceto et per se butyrum. —Testium tumor sebo vituli addito nitro cohibetur vel fimo eiusdem ex aceto decocto.— Urinae incontinentiam cohibet vesica apruna, si assa mandatur, ungularum apri vel suis cinis potioni inspersus, vesica feminae suis combusta ac pota, item haedi, vel pulmo, cerebrum leporis in vino, eiusdem testiculi tosti vel coagulum cum anserino adipe in polenta, renes asini in mero triti potique. Magi verrini genitalis cinere poto ex vino dulci demonstrant urinam facere in canis cubili ac verba adicere, ne ipse urinam faciat ut canis in suo cubili. rursus ciet urinam vesica suis, si terrain non attigerit, inposita pubi.", "st": "28.60"}, {"sp": "N", "t": "Sedis vitiis praeclare prodest fel ursinum cum adipe; quidam adiciunt spumam argenti ac tus. prodest et butyrum cum adipe anserino ac rosaceo; modum ipsae res statuunt, ut sint inlitu faciles. praeclare medetur et taurinum fel in linteolis concerptis rimasque perducit ad cicatricem. inflationibus in ea parte sebum vituli, maxime ab inguinibus, cum ruta; ceteris vitiis medetur sanguis caprinus cum polenta, item fel caprinum condylomatis per se, item fel lupinum ex vino. panos et apostemata in quacumque parte sanguis ursinus discutit, item taurinus aridus tritus. praecipuum tamen remedium traditur in calculo onagri, quem dicitur, cum interficiatur, reddere urina liquidiorem initio, sed in terra spissantem se; hic adalligatus femini omnes impetus discutit omnique suppuratione liberat. est autem rarus inventu nec ex omni onagro, sed m⟨ir⟩e celebra⟨nt⟩ remedio. prodest et urina asini cum melanthio et ungulae equinae cinis cum oleo et aqua inlitus, sanguis equi, praecipue admissarii, sanguis bubulus, item fel. caro quoque eosdem effectus habet calida inposita et ungulae cinis ex aqua aut melle, urina caprarum, hircorum quoque carnes in aqua decoctae aut fimum ex⟨i⟩is cum melle decoctum, fel verrinum, urina suum in lana inposita.—Femina adteri adurique equitatu notum est; utilissimum est ad omnes inde causas spumam equi ex ore inguinibus inlinere.—Inguina et ex ulcerum causa intumescunt. remedio sunt equi saetae III totidem nodis alligatae intra ulcus.", "st": "28.61"}, {"sp": "N", "t": "Podagris medetur ursinus adips taurinumque sebum, pari pondere et cerae. addunt quidam hypocist⟨h⟩idem et gallam. alii hircinum praeferunt sebum cum fimo caprae et croco, sinapi, i⟨t⟩em caulibus hederae tritis ac perdicio vel flore cucumeris silvestris. item bovis fimum cum aceti faece magnificant et vituli, qui nondum herbam gustaverit, fimum aut per se sanguinem tauri, vulpem decoctam vivam, donec ossa tantum restent, lupumve vivum oleo cerati modo incoctum, sebum hircinum cum hel⟨x⟩ines parte aequa, sinapis tertia, fimi caprini cinerem cum axungia. quin et ischiadicos uri sub pollicibus pedum eo fimo fervente utilissime tradunt, articulorumque vitiis fel ursinum utilissimum esse et pedes leporis adalligatos, podagras quidem mitigari pede leporis viventi absciso, si quis secum adsidue habeat. —Perniones ursinus adips rimasque pedum omnes sarcit, efficacius alumine addito, sebum caprinum, dentium equi farina, aprunum vel suillum fel cum adipe, pulmo inpositus et si subtriti sint contunsive offensatione, si vero adusti frigore, leporini pili cinis; eiusdem pulmo contusis dissectus aut pulmonis cinis. sole adusta sebo asinino aptissime curantur, item bubulo cum rosaceo.—Clavos et rimas callique vitia fimum apri vel suis recens inlitum ac tertio die solutum sanat, talorum cinis, pulmo apr⟨u⟩nus aut suillus aut cervinus; adtritus calciamentorum urina asini cum lnto suo inlita; clavos sebum bubulum cum turis polline; perniones vero corium conbustum; melius, si ex vetere calciamento; iniurias e calceatu ex oleo corii caprini cinis. —Varicum dolores sedat fimi vitulini cinis cum lilii bulbis decoctus addito melle modico, itemque omnia inflammata et suppurationes minantia. eadem res et podagris prodest et articulariis morbis, e maribus praecipue vitulis; articulorum adtritis fel aprorum vel suum linteo calefacto inpositum, vituli, qui nondum herbam gustaverit, fimum, item caprinum cum melle in aceto decoctum.—Ungues scabros sebum vituli emendat, item caprinum admixta sandaraca.—Verrucas vero aufert fimi vitulini cinis ex aceto, asini urina et lutum.", "st": "28.62"}, {"sp": "N", "t": "Comitiali morbo testes ursinos edisse prodest vel aprunos bibisse ex lacte equino aut ex aqua, item aprunam urinam ex aceto mulso, efficacius quae inaruerit in vesica sua. dantur et suum testiculi inveterati tritique in suis lacte, praecedente vini abstinentia et sequente continuis quinis diebus. dantur et leporis sale custoditi pulmones cum turis tertia parte in vino albo per dies xxx, item coagula eiusdem; asini cerebrum ex aqua mulsa, infumatum prius in foliis, semuncia per dies VII, ungularum eius cinis coclearibus binis toto mense potus, item testes sale adservati et inspersi potioni in asinarum maxime lacte vel ex aqua. membrana partus earum, praecipue si marem pepererint, olefactata accedente morbo comitialium resistit. sunt qui e mare nigroque cor edendum cum pane sub diu prima aut seconda luna praecipiant, alii carnem, aliqui sanguinem aceto dilutum per dies XL bibendum. quidam urinam aquae ferrariae ex officinis miscent eademque potione et lymphatis medentur. comitialibus datur et lactis equini potus, lichen equi in aceto mulso bibendus; dantur et carnes caprinae in rogo hominis tostae, ut volunt Magi, sebum earum cum felle taurino pari pondere decoctum et in folliculo fellis reconditum ita, ne terrain attingat, potum vero ex aqua sublime. morbum ipsum deprehendit caprini cornus vel cervini usti nidor.—Sideratis urina pulli asinini nardo admixto perunctione prodesse dicitur.", "st": "28.63"}, {"sp": "N", "t": "Regio morbo cornus cervini cinis, sanguis asini ex vino, item fimum asinini pulli, quod primum edidit a partu, datum fabae magnitudine e vino medetur intra diem tertium. eadem et ex equino pullo similiterque vis est.", "st": "28.64"}, {"sp": "N", "t": "Fractis ossibus praesentaneus maxillarum apri cinis vel suis; item lardum elixun atque circumligatum mira celeritate solidat. costis quidem fractis laudatur unice caprinum fimum ex vino vetere: aperit, extrahit, persanat.", "st": "28.65"}, {"sp": "N", "t": "Febres arcet cervorum caro, ut diximus; eas quidem, quae certo dierum numero redeunt, oculus lupi, dexter salsus adalligatusque, si credimus Magis. est genus febrium, quod amphemerinon vocant; hoc liberari tradunt, si quis e vena auris asini III guttas sanguinis in II heminis aquae hauserit. quartanis Magi excrementa felis cum digito bubonis adalligari iubent et, ne recidant, non removeri septeno circumitu. quis hoc, quaeso, invenire potuit? quae est ista mixtura? cur digitus potissimum bubonis electus est? modestiores iocur felis decrescente luna occisae inveteratum sale ex vino bibendum ante accessiones quartanae dixere. iidem Magi fimi bubuli cinere consperso puerorum urina inlinunt digitos pedum manuumque. leporis cor adalligant, coagulum ante accessiones propinant. datur et caseus caprinus recens cum melle diligenter sero expresso.", "st": "28.66"}, {"sp": "N", "t": "Melancholicis fimum vituli in vino decoctum remedio est.—Lethargicos excitat asini lichen naribus inlitus ex aceto, caprini cornus nidor aut pilorum, iocur aprunum; itaque et veternosis datur.—Phthisicis medentur iocur lupi ex vino macro, suis feminae herbis pastae laridum, carnes asininae ex iure sumptae; hoc genere maxime in Achaia curant id malum. fimi quoque aridi, sed pabulo viridi pasto bove, fumum harundine haustum prodesse tradunt bubuli⟨v⟩e cornus mucronem exustum II coclearium mensura addito melle pilulis devoratis. caprae sebo in pulte alicacia et phthisim et tussim sanari vel recenti cum mulso liquefacto ita, ut uncia in cyathum addatur rutaeque ramo permisceatur, non pauci tradunt. rupicaprae sebi cyatho et lactis pari mensura deploratum phthisicum convaluisse certus auctor adfirmat. sunt qui et suum fimi cinerem profuisse scripserint in passo et cervi pulmonem, maxime subulonis, siccatum fumo tritumque in vino.", "st": "28.67"}, {"sp": "N", "t": "Hydropicis auxiliatur urina e vesica apri paulatim data in potu, efficacius quae inaruerit cum vesica sua, fimi taurini maxime, sed et bubuli—de armentivis loquor—, quod bolbiton vocant, cinis coclearium III in mulsi hemina, bovis feminae in mulieribus, ex altero sexu in viris, quod veluti mysterium occultarunt Magi, fimum vituli masculi inlitum, fimi vitulini cinis cum semine staphylini aequa portione ex vino, sanguis caprinus cum medulla. efficaciorem putant hirci, utique si lentisco pascatur.", "st": "28.68"}, {"sp": "N", "t": "Igni sacro ursinus adips inlinitur, maxime qui est ad renes, vitulinum fimum recens vel bubulum, caseus caprinus siccus cum porro, ramenta pellis cervinae delecta pumice ex aceto trita; rubor⟨i⟩ cum prurigine equi spuma aut ungulae cinis; eruptionibus pituitae asinini fimi cinis cum butyro; papulis nigris caseus caprinus siccus ex melle et aceto in balneis, oleo remoto; pusulis suilli fimi cinis aqua inlitus vel cornus cervini cinis,", "st": "28.69"}, {"sp": "N", "t": "luxatis recens fimum apr⟨u⟩num vel suillum, item vitulinum, verris spuma recens cum aceto, fimum caprinum cum melle, bubula caro inposita; ad tumores fimum suillum sub testo calefactum tritumque cum oleo. duritias corporum omnes mollit optime adips e lupis inlitus. in ⟨i⟩is, quae rumpere opus sit, plurimum proficit fimum bubulum in cinere calefactum aut caprinum in vino vel aceto decoctum; in furunculis sebum bubulum cum sale aut, si dolores sint, cum oleo liquefactum sine sale, simili modo caprinum;", "st": "28.70"}, {"sp": "N", "t": "in ambustis ursinus adips cum lilii radicibus, aprunum aut suillum fimum inveteratum, saetarum ex his e penicillis tectoriis cinis cum adipe tritus, tali bubuli cinis cum cera et medulla cervina, fel tauri, fimum leporis et caprarum fimum. sine cicatrice sanare dicitur glutinum. praestantissimum fit ex auribus taurorum et genitalibus, nec quicquam efficacius prodest ambustis, sed adulteratur nihil aeque, quibusvis pellibus inveteratis calciamentisque etiam decoctis. Rhodiacum fidelissimum, eoque pictores et medici utuntur; id quoque quo candidius, eo probatius; nigrum et lignosum damnatur.", "st": "28.71"}, {"sp": "N", "t": "Nervorum doloribus fimum caprinum decoctum in aceto cum melle utilissimum putant vel putrescente nervo. spasmata et percussu vitiata fimo apruno curant vere collecto et arefacto; sic et quadrigas agentes tractos rotave vulneratos et quoquo modo sanguine contuso, vel si recens inlinatur. sunt qui incoxisse aceto utilius putent. quin et in potu farinam eam ruptis convulsisque, eversis ex aceto salutarem promittunt. reverentiores cinerem eius ex aqua bibunt, feruntque et Neronem principem hac potione recreari solitum, cum sic quoque se trigario adprobare vellet. proximam suillo fimo vim putant.", "st": "28.72"}, {"sp": "N", "t": "Sanguinem sistit coagulum cervinum ex aceto, item leporis, huius quidem et pilorum cinis, item e fimo asini cinis inlitus—efficacior vis e maribus aceto admixto et in lana ad omne profluvium inposito—, similiter ex equino, capitis et feminum aut fimi vitulorum cinis inlitus ex aceto, item caprini cornus vel fimi ex aceto. hircini vero iocineris dissecti sanies efficacior, et cinis utriusque ex vino potus vel naribus ex aceto inlitus, hircini quoque utris, vinarii dumtaxat, cinis cum pari pondere resinae, quo genere sistitur sanguis et vulnus glutinatur. haedinum quoque coagulum ex aceto et feminum eius combustorum cinis similiter pollere traduntur.", "st": "28.73"}, {"sp": "N", "t": "Ulcera sanat in tibiis cruribusque ursinus adips admixta rubrica; quae vero serp⟨a⟩nt, fel aprunum cum resina et cerussa, maxillarum apri vel suum cinis, fimum suum inlitum siccum, item caprinum ex aceto sub⟨actum⟩et⟨sub⟩fervefactum. cetera purgantur et explentur butyro, cornus cervini cinere vel medulla cervi, felle taurino cum cyprino oleo aut irino. fimum recens suum vel inveterati farina inlinuntur vulneribus ferro factis. phagedaenis et fistulis inmittitur fel tauri cum suco porri aut lacte mulierum vel sanguis aridus cum cotyledone herba. carcinomata curat coagulum leporis cum pari pondere capparis adspersum vino, gangraenas ursinum fel pinna inlitum, asini ungularum cinis ea quae serpunt ulcera inspersus. sanguis equi adrodit carnes septica vi, item fimi equini inveterati favilla; ea vero, quae phagedaenas vocant in ulcerum genere, corii bubuli cinis cum melle. caro vituli recentia vulnera non patitur intumescere, fimum bubulum cum melle. f⟨i⟩mi vitulini cinis sordida ulcera et quae cacoēthe vocant et lacte mulieris sanant; recentes plagas ferro inlatas glutinum taurinum liquefactum, tertio die solutum. caseus caprinus siccus ex aceto ac melle purgat ulcera; quae vero serpant, cohibet sebum cum cera, idem addita pice ac sulpure percurat. similiter proficit ad caco ēthe haedi feminum cinis e lacte mulieris, et adversus carbunculos suis feminae cerebrum tostum inlitumque.", "st": "28.74"}, {"sp": "N", "t": "Scabiem hominis asininae medullae maxime abolent et urina eiusdem cum suo luto inlit⟨a⟩, butyrum etiam, quod in iumentis proficit cum resina calida, glutinum taurinum in aceto liquefactum addita calce, fel caprinum cum aluminis cinere; bovas fimum bubulum, unde et nomen traxere. canum scabies sanatur bubulo sanguine recenti iterumque, cum inarescat, inlito et postero die abluto cinere lixivo.", "st": "28.75"}, {"sp": "N", "t": "Spinae et similia corpori extrahuntur felis excrementis, item caprae ex vino, coagulo quocumque, sed maxime leporis, cum turis polline et oleo aut cum visci pari pondere aut cum propoli.—Cicatrices nigras sebum asininum reducit ad colorem, fel vituli extenuat calefactum. medici adiciunt murram et mel et crocum aereaque pyxide condunt; aliqui et florem aeris admiscent.", "st": "28.76"}, {"sp": "N", "t": "Mulierum purgationes adiuvat fel tauri in lana sucida adpositum—Olympias Thebana addit o⟨es⟩ypum et nitrum —, cornus cervini cinis potus, item vulva laborantes inlitus quoque et fel taurinum cum opio adpositum obolis binis. vulvas et pilo cervino suffire prodest. tradunt cervas, cum senserint se gravidas, lapillun devorare, quem in excrementis repertum aut in vulva— nam et ibi invenitur—custodire partus adalligatum. inveniuntur et ossicula in corde et in vulva perquam utilia gravidis parturientibusque. nam de pumice, qu⟨i⟩ in vaccarum utero simili modo invenitur, diximus in natura boum. lupi adips inlitus vulvas mollit, dolores earum iocur, carnes vero lupi edisse parituris prodest aut si incipientibus parturire sit iuxta qui ederit, adeo ut etiam contra inlatas noxias valeat. eundem supervenire perniciosum est. magnus et leporis usus mulieribus. vulvas adiuvat pulmo aridus potus, profluvia iocur cum Samia terra ex aqua potum, secundas coagulum—caventur pridiana balnea—, inlitum quoque cum croco et porri suco; ⟨in⟩ vellere adpositum abortus mortuos expellit. si vulva leporum in cibis sumatur, mares concipi putant; hoc et testiculis eorum et coagulo profici; conceptum leporis utero exemptum ⟨i⟩is, quae parere desierint, restibilem fecunditatem adferre. s⟨ic⟩ conceptus leporis saniem et viro Magi propinant, item virgini VIIII grana fimi, ut stent perpetuo mammae. coagul⟨um⟩ quoque ob id cum melle inlinunt, sanguinem ubi evolsos pilos renasci nolunt. inflationi vulvae fimum aprunum suillumve cum oleo inlini prodest. efficacius sistit farina aridi, ut aspergatur potioni, vel si gravidae aut puerperae torqueantur. lacte suis poto cum mulso, adiuvantur partus mulierum; per se vero potum deficientia ubera puerperarum replet. eadem circumlita sanguine feminae suis minus crescunt. si dole⟨a⟩nt, lactis asinini potu mulcentur, quod addito melle sumptum et purgationes earum adiuvat. sanat et vulvarum exulcerationes eiusdem animalis sebum inveteratum et in vellere adpositum duritias vulvarum emollit. per se vero recens vel inveteratum ex aqua inlitum psilotri vim optinet. eiusdem animalis lien inveteratus ex aqua inlitus mammis abundantiam facit, vulvas suffitu corrigit. ungulae asininae suffitio partum maturat, ut vel abortus evocetur, nec aliter adhibetur, quoniam viventem partum necat. eiusdem animalis fimum si recens inponatur, profluvia sanguinis mire sedare dicitur, nec non et cinis eiusdem fimi, qui et vulvae prodest inpositus. equi spuma inlita per dies XL, priusquam primum nascantur, pili restinguntur, item cornus cervini decocto; melius, si recentia sint cornua. lacte equino iuvantur vulvae collutae. quod si mortuus partus sentiatur, lichen equae e dulci potus eicit, item ungula suffitu aut fimum aridum. vulvas procidentes butyrum infusum sistit. induratam vulvam aperit fel bulbulum rosaceo admixto, foris vellere cum resina terebinthina inposito. aiunt et suffitu fimi e mare bove procidentes vulvas reprimi, partus adiuvari, conceptus vero vaccini lactis potu. sterilitatem a partus vexatione fieri certum est. hanc emendari Olympias Thebana adfirmat felle tauri et adipe serpentium et aerugine ac melle medicatis locis ante coitus. vitulinum quoque fel in purgationibus sub coitu adspersum vulvae etiam duritias vet⟨e⟩r⟨e⟩s emollit et profluvium minuit umbilico peruncto atque in totum vulvae prodest. modum statuunt fellis pondere X̶, opii tertiam, admixto amygdalino oleo, quantum satis esse appareat; haec in vellere inponunt. masculi fel vituli cum mellis dimidio tritum servatur ad vulvas. carnem vituli si cum aristolochia inassatam edant circa conceptum, marem parituras promittunt. medulla vituli in vino et aqua decocta cum sebo exulcerationibus vulvarum inposita prodest, item adips vulpium excrementumque felium, hoc cum resina et rosaceo inpositum. caprino cornu suffiri vulvam utilissimum putant. silvestrium caprarum sanguis cum palma marina pilos detrahit; ceterarum vero fel callum vulvarum emollit inspersum et a purgatione conceptus facit. sic quoque psilotri vis efficitur; evulsis pilis triduo servatur inlitum. profluvium quamvis inmensum urinae caprae potu sisti obstetrices promittunt et si fimum inlinatur. membrana caprarum, in qua partus editur, inveterata potuque sumpta in vino secundas pellit. haedorum pilis suffiri vulvas utile putant et in profluvio sanguinis coagulum bibi aut cum hyoscyami semine inponi. e bove silvestri nigro si sanguine ricini lumbi perungantur mulieri, taedium veneris fieri dicit Osthanes, idem amoris potu hirci urinae admixto propter fastidium nardo.", "st": "28.77"}, {"sp": "N", "t": "Infantibus nihil butyro utilius per se et cum melle, privatim et in dentitione et ad gingivas et ad oris ulcera. dens lupi adalligatus infantium pavores prohibet dentien⟨d⟩ique morbos, quod et pellis lupina praestat. dentes quidem eorum maximi equis quoque adalligati infatigabilem cursum praestare dicuntur. leporum coagulo ubere inlito sistitur infantium alvus. iocur asini admixta modice panace instillatum in os a comitialibus morbis et aliis infantes tuetur; hoc XL diebus fieri praecipiunt. et pellis asini iniecta inpavidos infantes facit. dentes, qui equis primum cadunt, facilem dentitionem praestant adalligati infantibus; efficacius, si terram non attigere. lien bubulus in melle et datur et inlinitur ad lienis dolores; ⟨se⟩da⟨t⟩ ulcera manantia cum melle lien vituli, in vino decoctus tritusque et inlitus ulcuscula oris. cerebrum caprae Magi per anulum aureum traiectum, priusquam lac detur, infantibus instillant contra comitiales ceterosque infantium morbos. caprinum fimum inquietos infantes adalligatum panno cohibet, maxime puellas. lacte caprino aut cerebro leporum perunctae gingivae faciles dentitiones faciunt.", "st": "28.78"}, {"sp": "N", "t": "Somnos fieri lepore sumpto in cibis Cato arbitrabatur, vulgus et gratiam corpori in VIIII dies, frivolo quidem ioco, cui tamen aliqua debeat subesse causa in tanta persuasione. Magi felle caprae, sacrificatae dumtaxat, inlito oculis vel sub pulvino posito somnum allici dicunt.—Sudores inhibet cornus caprini cinis e myrteo oleo perunctis.", "st": "28.79"}, {"sp": "N", "t": "Coitus stimulat fel aprunum inlitum, item medullae suum haustae, sebum asininum anseris masculi adipe admixto inlitum; item a coitu equi Vergilio quoque descriptum virus et testiculi equini aridi, ut potioni interi possint, dexterve asini testis in vino potus portioneve adalligatus bracchiali; eiusdem a coitu spuma conlecta russeo panno et inclusa argento, ut Osthanes tradit. Salpe genitale id in oleum fervens mergi iubet septies eoque perungui pertinentes partes, Dalion cinerem ex eodem bibi vel tauri a coitu urinam, luto ipso inlini pubem. at e diverso⟨ta⟩uri fimo inlito cohibetur virorum venus.— Ebrietatem arcet pulmo apri aut suis assus, ieiunis in cibo sumptus eo die, item haedinus.", "st": "28.80"}, {"sp": "N", "t": "Mira praeterea traduntur in iisdem animalibus: vestigium equi excussum ungula, ut solet plerumque, si quis collectum reponat, singultus remedium esse recordantibus, quonam loco id reposuerint; iocur luporum equinae ungulae simile esse; rumpi equos, qui vestigia luporum sub equite sequantur; talis suum discordiae vim quandam inesse; in incendiis, si fimi aliquid egeratur e stabulis, facilius extrahi nec recurrere oves bovesque; hircorum carnes virus non resipere, si panem hordeacium eo die, quo interficiantur, ederint laserve dilutum biberint, nullas vero teredinem sentire luna decrescente induratas sale. adeoque nihil omissum est, ut leporem surdum celerius pinguescere reperiamus, animalium vero medicinas: si sanguis profluat iumentis, suillum fimum ex vino infundendum, boum autem morbis sebum, sulpur vivum, alium silvestre, o⟨v⟩um c⟨rud⟩um trita in vino danda aut vulpis adipem; carnem caballinam discoctam potu suum morbis mederi, omnium vero quadripedum morbis capram solidam cum corio et rana⟨m⟩ rubeta⟨m⟩ discoctas; gallinaceos non attingi a vulpibus, qui iocur animalis eius aridum ederint, vel si pellicula ex eo collo induta galli inierint; similiter in felle mustelae; boves in Cypro contra tormina hominum excrementis sibi mederi; non sup⟨t⟩er⟨i⟩ pedes bourn, si prius cornua ima pice liquida perunguantur; lupos in agrum non accedere, si capti unius pedibus infractis cultroque adacto paulatim sanguis circa fines agri spargatur atque ipse defodiatur in eo loco, ex quo coeperit trahi; aut si vomerem, quo primus sulcus eo anno in agro ductus sit, excussum aratro focus Larum, quo familia conveniet, urat, lupum nulli animalium nociturum in eo agro, quam diu id fiat.", "st": "28.81"}, {"sp": "N", "t": "Hinc deinde praevertemur ad animalia sui generis, quae aut placida non sunt aut fera.", "st": "28.81"}], []);})();
